import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum AppMode {
  HOME = 'HOME',
  ANALYSIS = 'ANALYSIS',
  HISTORY = 'HISTORY',
  LEARNING = 'LEARNING'
}

export enum UserRole {
  STUDENT = 'STUDENT',
  PROFESSIONAL = 'PROFESSIONAL',
  INTERN = 'INTERN'
}

export interface StructuralAnalysis {
  elementName: string;
  type: string;
  dimensions: string;
  materialDetails: string;
  structuralFunction: string;
  isCodeReferences: string[];
  constructionSteps: string[];
  qualityChecks: string[];
}

export interface TranscriptionItem {
  speaker: 'user' | 'model';
  text: string;
}

export interface AnalysisResult {
  id: string;
  timestamp: number;
  image: string;
  data: StructuralAnalysis;
}

import { GoogleGenAI, Modality, Type, GenerateContentResponse, LiveServerMessage } from "@google/genai";
import { CIVIL_ENGINEER_SYSTEM_PROMPT } from "../constants";
import { StructuralAnalysis } from "../types";

const API_KEY = process.env.API_KEY || '';

export const analyzeImage = async (base64Image: string): Promise<StructuralAnalysis> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [
      {
        parts: [
          { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
          { text: "Analyze this civil engineering structure. Provide a JSON response identifying the element, type, dimensions, material details, structural function, IS code references, construction steps, and quality checks." }
        ]
      }
    ],
    config: {
      systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT,
      responseMimeType: 'application/json',
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          elementName: { type: Type.STRING },
          type: { type: Type.STRING },
          dimensions: { type: Type.STRING },
          materialDetails: { type: Type.STRING },
          structuralFunction: { type: Type.STRING },
          isCodeReferences: { type: Type.ARRAY, items: { type: Type.STRING } },
          constructionSteps: { type: Type.ARRAY, items: { type: Type.STRING } },
          qualityChecks: { type: Type.ARRAY, items: { type: Type.STRING } },
        },
        required: ["elementName", "type", "dimensions"]
      }
    }
  });

  return JSON.parse(response.text || '{}') as StructuralAnalysis;
};

// Audio helpers
export const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
};

export const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useEffect } from 'react';
import { AppMode, UserRole, AnalysisResult } from './types';
import CameraInterface from './components/CameraInterface';
import Home from './components/Home';
import AnalysisView from './components/AnalysisView';
import { MOCK_ANALYSES } from './constants';

const App: React.FC = () => {
  const [mode, setMode] = useState<AppMode>(AppMode.HOME);
  const [role, setRole] = useState<UserRole>(UserRole.STUDENT);
  const [currentAnalysis, setCurrentAnalysis] = useState<AnalysisResult | null>(null);
  const [history, setHistory] = useState<AnalysisResult[]>(MOCK_ANALYSES);

  const startAnalysis = () => setMode(AppMode.ANALYSIS);

  const handleCaptureComplete = (result: AnalysisResult) => {
    setCurrentAnalysis(result);
    setHistory(prev => [result, ...prev]);
    // Stay in analysis mode but change UI state to show results
  };

  const handleBack = () => {
    setMode(AppMode.HOME);
    setCurrentAnalysis(null);
  };

  return (
    <div className="flex flex-col h-screen bg-slate-900 text-white overflow-hidden">
      {mode === AppMode.HOME && (
        <Home 
          role={role} 
          setRole={setRole} 
          onStart={startAnalysis} 
          history={history}
          onSelectHistory={(item) => {
            setCurrentAnalysis(item);
            setMode(AppMode.ANALYSIS);
          }}
        />
      )}

      {mode === AppMode.ANALYSIS && !currentAnalysis && (
        <CameraInterface 
          onBack={handleBack} 
          onComplete={handleCaptureComplete} 
        />
      )}

      {mode === AppMode.ANALYSIS && currentAnalysis && (
        <AnalysisView 
          analysis={currentAnalysis} 
          onBack={handleBack} 
          role={role}
        />
      )}
    </div>
  );
};

export default App;

