import React, { useRef, useState, useEffect } from 'react';
import { analyzeImage } from '../services/gemini';
import { AnalysisResult } from '../types';

interface CameraInterfaceProps {
  onBack: () => void;
  onComplete: (result: AnalysisResult) => void;
}

const CameraInterface: React.FC<CameraInterfaceProps> = ({ onBack, onComplete }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const startCamera = async () => {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment' },
          audio: false 
        });
        setStream(s);
        if (videoRef.current) {
          videoRef.current.srcObject = s;
        }
      } catch (err) {
        setError('Camera permission denied or not available.');
      }
    };
    startCamera();
    return () => {
      stream?.getTracks().forEach(track => track.stop());
    };
  }, []);

  const captureAndAnalyze = async () => {
    if (!videoRef.current || !canvasRef.current) return;

    setIsProcessing(true);
    setError(null);

    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    if (ctx) {
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

      const base64Image = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];

      try {
        const data = await analyzeImage(base64Image);
        onComplete({
          id: Date.now().toString(),
          timestamp: Date.now(),
          image: canvas.toDataURL('image/jpeg'),
          data
        });
      } catch (err) {
        setError('Analysis failed. Please try again.');
        setIsProcessing(false);
      }
    }
  };

  return (
    <div className="relative h-full w-full bg-black overflow-hidden flex flex-col">
      {/* Video Feed */}
      <video 
        ref={videoRef} 
        autoPlay 
        playsInline 
        className="flex-1 w-full object-cover"
      />

      {/* HUD Overlays */}
      <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
        <div className="w-64 h-64 border-2 border-white/30 rounded-3xl relative">
            <div className="absolute -top-1 -left-1 w-8 h-8 border-t-4 border-l-4 border-blue-500 rounded-tl-lg"></div>
            <div className="absolute -top-1 -right-1 w-8 h-8 border-t-4 border-r-4 border-blue-500 rounded-tr-lg"></div>
            <div className="absolute -bottom-1 -left-1 w-8 h-8 border-b-4 border-l-4 border-blue-500 rounded-bl-lg"></div>
            <div className="absolute -bottom-1 -right-1 w-8 h-8 border-b-4 border-r-4 border-blue-500 rounded-br-lg"></div>
        </div>
      </div>

      {/* Top Controls */}
      <div className="absolute top-0 left-0 right-0 p-6 flex justify-between items-start">
        <button 
          onClick={onBack}
          className="bg-black/40 backdrop-blur-md p-3 rounded-full text-white"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>
      </div>

      {/* Bottom Controls */}
      <div className="p-10 bg-gradient-to-t from-black to-transparent flex flex-col items-center">
        {error && <div className="text-red-400 text-xs mb-4 bg-red-900/40 px-3 py-1 rounded-full">{error}</div>}

        <button 
          onClick={captureAndAnalyze}
          disabled={isProcessing}
          className={`w-20 h-20 rounded-full border-4 ${isProcessing ? 'border-blue-900 animate-pulse' : 'border-white'} flex items-center justify-center active:scale-90 transition-transform`}
        >
          <div className={`w-16 h-16 rounded-full ${isProcessing ? 'bg-blue-600 animate-pulse' : 'bg-white'}`}></div>
        </button>
        <p className="text-white/60 text-xs mt-4 font-medium uppercase tracking-widest">
          {isProcessing ? 'Analyzing Structural Elements...' : 'Tap to Analyze Structure'}
        </p>
      </div>

      <canvas ref={canvasRef} />
    </div>
  );
};

export default CameraInterface;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GoogleGenAI, Modality, Blob, LiveServerMessage } from '@google/genai';
import { encode, decode, decodeAudioData } from '../services/gemini';
import { StructuralAnalysis, TranscriptionItem } from '../types';
import { CIVIL_ENGINEER_SYSTEM_PROMPT } from '../constants';

interface VoiceLiveSessionProps {
  context: StructuralAnalysis;
  initialPrompt: string;
}

const VoiceLiveSession: React.FC<VoiceLiveSessionProps> = ({ context, initialPrompt }) => {
  const [isActive, setIsActive] = useState(false);
  const [transcription, setTranscription] = useState<TranscriptionItem[]>([]);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isListening, setIsListening] = useState(false);

  const nextStartTimeRef = useRef(0);
  const audioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const currentInputTranscriptionRef = useRef('');
  const currentOutputTranscriptionRef = useRef('');

  const stopSession = useCallback(() => {
    setIsActive(false);
    setIsListening(false);
    setIsSpeaking(false);
    streamRef.current?.getTracks().forEach(t => t.stop());
    sessionPromiseRef.current?.then(session => session.close());
    sourcesRef.current.forEach(s => s.stop());
    sourcesRef.current.clear();
  }, []);

  const startSession = async () => {
    try {
      const API_KEY = process.env.API_KEY || '';
      const ai = new GoogleGenAI({ apiKey: API_KEY });

      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            setIsActive(true);
            setIsListening(true);

            // Microphone streaming
            const source = audioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);

            scriptProcessor.onaudioprocess = (e) => {
              if (!isActive) return;
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createBlob(inputData);
              sessionPromise.then(session => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };

            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextRef.current!.destination);

            // Send initial context
            sessionPromise.then(session => {
              session.sendRealtimeInput({ 
                media: { 
                  data: encode(new TextEncoder().encode(`I am looking at a ${context.elementName}. ${initialPrompt}`)), 
                  mimeType: 'text/plain' 
                } 
              });
            });
          },
          onmessage: async (message: LiveServerMessage) => {
            // Handle Transcription
            if (message.serverContent?.outputTranscription) {
              currentOutputTranscriptionRef.current += message.serverContent.outputTranscription.text;
            } else if (message.serverContent?.inputTranscription) {
              currentInputTranscriptionRef.current += message.serverContent.inputTranscription.text;
            }

            if (message.serverContent?.turnComplete) {
              const uText = currentInputTranscriptionRef.current;
              const mText = currentOutputTranscriptionRef.current;
              if (uText || mText) {
                setTranscription(prev => [
                  ...prev, 
                  ...(uText ? [{ speaker: 'user' as const, text: uText }] : []),
                  ...(mText ? [{ speaker: 'model' as const, text: mText }] : [])
                ]);
              }
              currentInputTranscriptionRef.current = '';
              currentOutputTranscriptionRef.current = '';
            }

            // Handle Audio Output
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio && outputAudioContextRef.current) {
              setIsSpeaking(true);
              const ctx = outputAudioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);

              const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              });
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              sourcesRef.current.add(source);
            }

            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => s.stop());
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
            }
          },
          onerror: (e) => console.error('Gemini Live Error:', e),
          onclose: () => stopSession()
        },
        config: {
          responseModalities: [Modality.AUDIO],
          systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT + `\nContext: We are discussing a ${context.elementName} which is a ${context.type}. Specs: ${context.materialDetails}. Dimensions: ${context.dimensions}.`,
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          },
          outputAudioTranscription: {},
          inputAudioTranscription: {}
        }
      });
      sessionPromiseRef.current = sessionPromise;
    } catch (err) {
      console.error('Failed to start session:', err);
    }
  };

  const createBlob = (data: Float32Array): Blob => {
    const int16 = new Int16Array(data.length);
    for (let i = 0; i < data.length; i++) {
      int16[i] = data[i] * 32768;
    }
    return {
      data: encode(new Uint8Array(int16.buffer)),
      mimeType: 'audio/pcm;rate=16000',
    };
  };

  useEffect(() => {
    return () => stopSession();
  }, [stopSession]);

  return (
    <div className="flex flex-col h-full bg-slate-950 p-6 space-y-6 pb-40">
      {/* Waveform Visualization (Mock) */}
      <div className="h-32 flex items-center justify-center space-x-1">
        {[...Array(20)].map((_, i) => (
          <div 
            key={i} 
            className={`w-1 bg-blue-500 rounded-full transition-all duration-150 ${
              isActive ? (isSpeaking || isListening ? 'animate-bounce' : 'h-2') : 'h-1 bg-slate-800'
            }`}
            style={{ 
                height: isActive ? `${Math.random() * 60 + 20}%` : '4px',
                animationDelay: `${i * 0.05}s`
            }}
          ></div>
        ))}
      </div>

      {!isActive ? (
        <div className="flex-1 flex flex-col items-center justify-center text-center px-4">
          <div className="bg-blue-600/20 p-6 rounded-full mb-6">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
            </svg>
          </div>
          <h3 className="text-lg font-bold mb-2">Voice Discussion</h3>
          <p className="text-slate-400 text-sm mb-8">Ask follow-up questions about this structure naturally. The AI will explain details using IS codes and engineering principles.</p>
          <button 
            onClick={startSession}
            className="bg-blue-600 hover:bg-blue-700 active:scale-95 px-8 py-4 rounded-2xl font-bold flex items-center shadow-xl shadow-blue-900/40"
          >
            Start Conversation
          </button>
        </div>
      ) : (
        <div className="flex-1 flex flex-col space-y-4 overflow-y-auto">
          {transcription.map((t, idx) => (
            <div key={idx} className={`flex ${t.speaker === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[80%] p-4 rounded-2xl text-sm ${
                t.speaker === 'user' ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-slate-800 text-slate-200 rounded-tl-none border border-slate-700'
              }`}>
                {t.text}
              </div>
            </div>
          ))}
          {isActive && (
             <div className="flex justify-center py-4">
                <span className="text-[10px] uppercase font-bold tracking-widest text-slate-600">
                    {isSpeaking ? 'AI is speaking...' : isListening ? 'Listening to you...' : 'Thinking...'}
                </span>
             </div>
