import { GoogleGenAI, Modality, Type, GenerateContentResponse, LiveServerMessage } from "@google/genai";
import { CIVIL_ENGINEER_SYSTEM_PROMPT } from "../constants";
import { StructuralAnalysis } from "../types";

const API_KEY = process.env.API_KEY || '';

export const analyzeImage = async (base64Image: string): Promise<StructuralAnalysis> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [
      {
        parts: [
          { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
          { text: "Analyze this image for civil engineering details. Identify the object, its specs, construction method, load capacity, costs, and scan for any defects or quality issues. Return valid JSON." }
        ]
      }
    ],
    config: {
      systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT,
      responseMimeType: 'application/json',
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          elementName: { type: Type.STRING },
          type: { type: Type.STRING },
          dimensions: { type: Type.STRING },
          materialDetails: { type: Type.STRING },
          structuralFunction: { type: Type.STRING },
          loadCapacity: { type: Type.STRING },
          costEstimate: { type: Type.STRING },
          isCodeReferences: { type: Type.ARRAY, items: { type: Type.STRING } },
          constructionSteps: { type: Type.ARRAY, items: { type: Type.STRING } },
          qualityChecks: { type: Type.ARRAY, items: { type: Type.STRING } },
          defects: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                type: { type: Type.STRING },
                severity: { type: Type.STRING, description: "Minor, Moderate, Major, or Critical" },
                cause: { type: Type.STRING },
                impact: { type: Type.STRING },
                remedy: { type: Type.STRING }
              },
              required: ["type", "severity", "remedy"]
            }
          }
        },
        required: ["elementName", "type", "dimensions", "defects"]
      }
    }
  });

  return JSON.parse(response.text || '{}') as StructuralAnalysis;
};

// Audio helpers
export const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
};

export const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useRef, useState, useEffect } from 'react';
import { analyzeImage } from '../services/gemini';
import { AnalysisResult } from '../types';

interface CameraInterfaceProps {
  onBack: () => void;
  onComplete: (result: AnalysisResult) => void;
}

const CameraInterface: React.FC<CameraInterfaceProps> = ({ onBack, onComplete }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const startCamera = async () => {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment' },
          audio: false 
        });
        setStream(s);
        if (videoRef.current) {
          videoRef.current.srcObject = s;
        }
      } catch (err) {
        setError('Camera permission denied or not available.');
      }
    };
    startCamera();
    return () => {
      stream?.getTracks().forEach(track => track.stop());
    };
  }, []);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      const imageData = event.target?.result as string;
      const base64Image = imageData.split(',')[1];

      try {
        const data = await analyzeImage(base64Image);
        onComplete({
          id: Date.now().toString(),
          timestamp: Date.now(),
          image: imageData,
          data
        });
      } catch (err) {
        setError('Analysis failed. Please try again.');
        setIsProcessing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const captureAndAnalyze = async () => {
    if (!videoRef.current || !canvasRef.current) return;

    setIsProcessing(true);
    setError(null);

    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    if (ctx) {
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

      const base64Image = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];

      try {
        const data = await analyzeImage(base64Image);
        onComplete({
          id: Date.now().toString(),
          timestamp: Date.now(),
          image: canvas.toDataURL('image/jpeg'),
          data
        });
      } catch (err) {
        setError('Analysis failed. Please try again.');
        setIsProcessing(false);
      }
    }
  };

  return (
    <div className="relative h-full w-full bg-black overflow-hidden flex flex-col">
      {/* Video Feed */}
      <video 
        ref={videoRef} 
        autoPlay 
        playsInline 
        className="flex-1 w-full object-cover"
      />

      {/* HUD Overlays */}
      <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
        <div className="w-64 h-64 border-2 border-white/30 rounded-3xl relative">
            <div className="absolute -top-1 -left-1 w-8 h-8 border-t-4 border-l-4 border-blue-500 rounded-tl-lg"></div>
            <div className="absolute -top-1 -right-1 w-8 h-8 border-t-4 border-r-4 border-blue-500 rounded-tr-lg"></div>
            <div className="absolute -bottom-1 -left-1 w-8 h-8 border-b-4 border-l-4 border-blue-500 rounded-bl-lg"></div>
            <div className="absolute -bottom-1 -right-1 w-8 h-8 border-b-4 border-r-4 border-blue-500 rounded-br-lg"></div>
        </div>
      </div>

      {/* Top Controls */}
      <div className="absolute top-0 left-0 right-0 p-6 flex justify-between items-start">
        <button 
          onClick={onBack}
          className="bg-black/40 backdrop-blur-md p-3 rounded-full text-white"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>
      </div>

      {/* Bottom Controls */}
      <div className="p-10 bg-gradient-to-t from-black to-transparent flex flex-col items-center">
        {error && <div className="text-red-400 text-xs mb-4 bg-red-900/40 px-3 py-1 rounded-full">{error}</div>}

        <div className="flex items-center space-x-8">
            {/* Gallery Upload Button */}
            <button 
                onClick={() => fileInputRef.current?.click()}
                className="bg-white/10 p-4 rounded-full border border-white/20 text-white"
            >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                </svg>
            </button>

            {/* Main Shutter */}
            <button 
                onClick={captureAndAnalyze}
                disabled={isProcessing}
                className={`w-20 h-20 rounded-full border-4 ${isProcessing ? 'border-blue-900 animate-pulse' : 'border-white'} flex items-center justify-center active:scale-90 transition-transform`}
            >
                <div className={`w-16 h-16 rounded-full ${isProcessing ? 'bg-blue-600 animate-pulse' : 'bg-white'}`}></div>
            </button>

            <div className="w-14"></div> {/* Spacer for symmetry */}
        </div>

        <p className="text-white/60 text-xs mt-4 font-medium uppercase tracking-widest">
          {isProcessing ? 'Analyzing Structural Elements...' : 'Tap to Analyze or Upload'}
