import React, { useRef, useState, useEffect } from 'react';
import { analyzeImage } from '../services/gemini';
import { AnalysisResult } from '../types';

interface CameraInterfaceProps {
  onBack: () => void;
  onComplete: (result: AnalysisResult) => void;
}

const CameraInterface: React.FC<CameraInterfaceProps> = ({ onBack, onComplete }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [angle, setAngle] = useState({ alpha: 0, beta: 0, gamma: 0 });

  useEffect(() => {
    const startCamera = async () => {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1920 }, height: { ideal: 1080 } },
          audio: false 
        });
        setStream(s);
        if (videoRef.current) {
          videoRef.current.srcObject = s;
        }
      } catch (err) {
        console.error('Camera access error:', err);
        setError('CRITICAL: CAMERA_PERM_DENIED');
      }
    };

    const handleOrientation = (e: DeviceOrientationEvent) => {
      setAngle({
        alpha: Math.round(e.alpha || 0),
        beta: Math.round(e.beta || 0),
        gamma: Math.round(e.gamma || 0)
      });
    };

    startCamera();
    window.addEventListener('deviceorientation', handleOrientation);

    return () => {
      stream?.getTracks().forEach(track => track.stop());
      window.removeEventListener('deviceorientation', handleOrientation);
    };
  }, []);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Reset error and start processing
    setError(null);
    setIsProcessing(true);

    const reader = new FileReader();
    reader.onload = async (event) => {
      const imageData = event.target?.result as string;
      const base64Image = imageData.split(',')[1];

      try {
        const data = await analyzeImage(base64Image);
        onComplete({
          id: Date.now().toString(),
          timestamp: Date.now(),
          image: imageData,
          data
        });
      } catch (err) {
        console.error('Analysis error:', err);
        setError('PROC_ERROR: IMG_ANALYSIS_FAILED');
        setIsProcessing(false);
      } finally {
        // Clear the input value to allow the same file to be selected again if needed
        if (fileInputRef.current) {
          fileInputRef.current.value = '';
        }
      }
    };
    reader.onerror = () => {
      setError('FILE_READ_ERROR: READ_FAILED');
      setIsProcessing(false);
    };
    reader.readAsDataURL(file);
  };

  const captureAndAnalyze = async () => {
    if (!videoRef.current || !canvasRef.current) return;

    setIsProcessing(true);
    setError(null);

    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    if (ctx) {
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
      const imageData = canvas.toDataURL('image/jpeg', 0.8);
      const base64Image = imageData.split(',')[1];

      try {
        const data = await analyzeImage(base64Image);
        onComplete({
          id: Date.now().toString(),
          timestamp: Date.now(),
          image: imageData,
          data
        });
      } catch (err) {
        console.error('Capture error:', err);
        setError('PROC_ERROR: CAPTURE_FAIL');
        setIsProcessing(false);
      }
    }
  };

  return (
    <div className="relative h-full w-full bg-black overflow-hidden flex flex-col font-mono">
      {/* Video Feed */}
      <video ref={videoRef} autoPlay playsInline className="flex-1 w-full object-cover opacity-80" />

      {/* Scanline Animation during processing */}
      {isProcessing && <div className="absolute inset-0 z-30 pointer-events-none overflow-hidden"><div className="scanline"></div></div>}

      {/* Technical HUD Overlay */}
      <div className="absolute inset-0 pointer-events-none flex flex-col justify-between p-6 z-10 text-[10px] text-blue-400">
        {/* Top HUD */}
        <div className="flex justify-between items-start">
            <div className="flex flex-col space-y-1">
                <div className="flex items-center space-x-2">
                    <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse"></span>
                    <span className="font-bold uppercase tracking-wider">Live System Feed</span>
                </div>
                <div className="text-slate-500">RES: {videoRef.current?.videoWidth || 0}x{videoRef.current?.videoHeight || 0}</div>
                <div className="text-slate-500">FRM: 60FPS</div>
            </div>
            <div className="text-right">
                <div className="font-bold">ORIENTATION</div>
                <div className="text-slate-300">A: {angle.alpha}° | B: {angle.beta}° | G: {angle.gamma}°</div>
                <div className="text-slate-500 uppercase mt-1">Sensor: Active</div>
            </div>
        </div>

        {/* Targeting Reticle */}
        <div className="flex-1 flex items-center justify-center relative">
          <div className="w-72 h-72 border border-blue-500/20 relative flex items-center justify-center">
             {/* Dynamic Corners */}
             <div className="absolute top-0 left-0 w-8 h-8 border-t-2 border-l-2 border-blue-500"></div>
             <div className="absolute top-0 right-0 w-8 h-8 border-t-2 border-r-2 border-blue-500"></div>
             <div className="absolute bottom-0 left-0 w-8 h-8 border-b-2 border-l-2 border-blue-500"></div>
             <div className="absolute bottom-0 right-0 w-8 h-8 border-b-2 border-r-2 border-blue-500"></div>

             {/* Center Crosshair */}
             <div className="w-10 h-[1px] bg-blue-500/50"></div>
             <div className="h-10 w-[1px] bg-blue-500/50 absolute"></div>

             {/* Scale marks */}
             <div className="absolute top-1/2 -left-6 transform -translate-y-1/2 flex flex-col space-y-1">
                <div className="w-2 h-[1px] bg-blue-400"></div>
                <div className="w-4 h-[1px] bg-blue-400"></div>
                <div className="w-2 h-[1px] bg-blue-400"></div>
