        </div>

        {/* Bottom HUD */}
        <div className="flex justify-between items-end">
            <div className="w-32 bg-slate-900/60 p-2 border border-slate-700">
                <div className="font-bold mb-1 uppercase text-slate-400">Spectrum</div>
