        </div>
      </div>

      {/* Actual Interface Controls */}
      <div className="absolute top-0 left-0 right-0 p-6 flex justify-between z-20 pointer-events-none">
        <button 
          onClick={onBack}
          className="bg-slate-900/80 backdrop-blur-md p-3 rounded-xl text-white border border-slate-700 pointer-events-auto active:scale-95"
