            {error && <div className="text-red-400 text-[10px] mb-4 bg-red-950/80 px-4 py-2 rounded border border-red-500/50 mono uppercase tracking-widest">{error}</div>}

            <div className="flex items-center space-x-12">
                <button 
                    onClick={() => fileInputRef.current?.click()}
