import React, { useRef, useState, useEffect } from 'react';
import { analyzeImage } from '../services/gemini';
import { AnalysisResult } from '../types';

interface CameraInterfaceProps {
  onBack: () => void;
  onComplete: (result: AnalysisResult) => void;
}

const CameraInterface: React.FC<CameraInterfaceProps> = ({ onBack, onComplete }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [angle, setAngle] = useState({ alpha: 0, beta: 0, gamma: 0 });
  const [loadingText, setLoadingText] = useState('Initializing Analysis...');

  const loadingMessages = [
    'Detecting structural geometry...',
    'Parsing material properties...',
    'Checking IS Code compliance...',
    'Calculating load thresholds...',
    'Scanning for surface defects...',
    'Generating cost estimations...'
  ];

  useEffect(() => {
    let interval: number;
    if (isProcessing) {
      let i = 0;
      interval = window.setInterval(() => {
        setLoadingText(loadingMessages[i % loadingMessages.length]);
        i++;
      }, 2000);
    }
    return () => clearInterval(interval);
  }, [isProcessing]);

  useEffect(() => {
    const startCamera = async () => {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1920 }, height: { ideal: 1080 } },
          audio: false 
        });
        setStream(s);
        if (videoRef.current) {
          videoRef.current.srcObject = s;
        }
      } catch (err) {
        console.error('Camera access error:', err);
        setError('CRITICAL: CAMERA_PERM_DENIED');
      }
    };

    const handleOrientation = (e: DeviceOrientationEvent) => {
      setAngle({
        alpha: Math.round(e.alpha || 0),
        beta: Math.round(e.beta || 0),
        gamma: Math.round(e.gamma || 0)
      });
    };

    startCamera();
    window.addEventListener('deviceorientation', handleOrientation);

    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
      window.removeEventListener('deviceorientation', handleOrientation);
    };
  }, []);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setError(null);
    setIsProcessing(true);

    const reader = new FileReader();
    reader.onload = async (event) => {
      const imageData = event.target?.result as string;
      const base64Image = imageData.split(',')[1];

      try {
        const data = await analyzeImage(base64Image);
        onComplete({
          id: Date.now().toString(),
          timestamp: Date.now(),
          image: imageData,
          data
        });
      } catch (err) {
        console.error('Analysis error:', err);
        setError('PROC_ERROR: IMG_ANALYSIS_FAILED');
        setIsProcessing(false);
      } finally {
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.onerror = () => {
      setError('FILE_READ_ERROR: READ_FAILED');
      setIsProcessing(false);
    };
    reader.readAsDataURL(file);
  };

  const captureAndAnalyze = async () => {
    if (!videoRef.current || !canvasRef.current) return;

    setIsProcessing(true);
    setError(null);

    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    if (ctx) {
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
      const imageData = canvas.toDataURL('image/jpeg', 0.8);
      const base64Image = imageData.split(',')[1];

      try {
        const data = await analyzeImage(base64Image);
        onComplete({
          id: Date.now().toString(),
          timestamp: Date.now(),
          image: imageData,
          data
        });
      } catch (err) {
        console.error('Capture error:', err);
        setError('PROC_ERROR: CAPTURE_FAIL');
        setIsProcessing(false);
      }
    }
  };

  return (
    <div className="relative h-full w-full bg-black overflow-hidden flex flex-col font-mono">
      {/* Processing / Loading Overlay */}
      {isProcessing && (
        <div className="absolute inset-0 z-50 bg-slate-950/95 backdrop-blur-xl flex flex-col items-center justify-center p-8">
          <div className="relative mb-12">
            <div className="w-32 h-32 border-4 border-blue-500/20 rounded-full pulse-ring absolute inset-0"></div>
            <div className="w-32 h-32 border-4 border-t-blue-500 rounded-full animate-spin"></div>
            <div className="absolute inset-0 flex items-center justify-center">
               <span className="text-3xl">🏗️</span>
            </div>
          </div>

          <div className="text-center">
            <h2 className="text-xl font-black text-white uppercase tracking-tighter italic mb-2">Neural Scan in Progress</h2>
            <p className="text-blue-500 text-[10px] font-bold uppercase tracking-[0.3em] mb-8 mono animate-pulse">{loadingText}</p>

            <div className="bg-slate-900 border border-slate-800 p-4 rounded-xl max-w-xs mx-auto">
              <div className="flex items-center space-x-2 text-[8px] text-slate-500 mono mb-2 uppercase">
                <span className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></span>
                <span>Optimizing Gemini Processing Pipeline</span>
              </div>
              <div className="h-1 bg-slate-800 rounded-full overflow-hidden">
                <div className="h-full bg-blue-500 progress-loading origin-left"></div>
              </div>
            </div>
          </div>

          <div className="absolute bottom-12 left-0 right-0 text-center opacity-30 text-[8px] uppercase tracking-widest text-slate-500">
            CivilVision AI v1.2.4 | System Active
          </div>
        </div>
      )}

      {/* Video Feed */}
      <video ref={videoRef} autoPlay playsInline className="flex-1 w-full object-cover opacity-80" />

      {/* Scanline Animation */}
      <div className="absolute inset-0 z-30 pointer-events-none overflow-hidden">
        <div className="scanline"></div>
      </div>

      {/* Technical HUD Overlay */}
      <div className="absolute inset-0 pointer-events-none flex flex-col justify-between p-6 z-10 text-[10px] text-blue-400">
        <div className="flex justify-between items-start">
            <div className="flex flex-col space-y-1">
                <div className="flex items-center space-x-2">
                    <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse"></span>
                    <span className="font-bold uppercase tracking-wider italic">Site Vis_Stream</span>
                </div>
                <div className="text-slate-500">ENGINE: GEMINI_FLASH_3</div>
                <div className="text-slate-500">MODE: HI_RES_STRUCT</div>
            </div>
            <div className="text-right">
                <div className="font-bold">TELEMETRY</div>
                <div className="text-slate-300 italic">BETA: {angle.beta}° | GAM: {angle.gamma}°</div>
                <div className="text-slate-500 uppercase mt-1">Status: Stable</div>
            </div>
        </div>

        <div className="flex-1 flex items-center justify-center relative">
          <div className="w-72 h-72 border border-blue-500/20 relative flex items-center justify-center">
             <div className="absolute top-0 left-0 w-8 h-8 border-t-2 border-l-2 border-blue-500"></div>
             <div className="absolute top-0 right-0 w-8 h-8 border-t-2 border-r-2 border-blue-500"></div>
             <div className="absolute bottom-0 left-0 w-8 h-8 border-b-2 border-l-2 border-blue-500"></div>
             <div className="absolute bottom-0 right-0 w-8 h-8 border-b-2 border-r-2 border-blue-500"></div>
             <div className="w-10 h-[1px] bg-blue-500/50"></div>
             <div className="h-10 w-[1px] bg-blue-500/50 absolute"></div>
          </div>
        </div>
      </div>

      <div className="absolute top-0 left-0 right-0 p-6 flex justify-between z-20 pointer-events-none">
        <button 
          onClick={onBack}
          className="bg-slate-900/80 backdrop-blur-md p-3 rounded-xl text-white border border-slate-700 pointer-events-auto active:scale-95"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>
      </div>

      <div className="p-8 bg-gradient-to-t from-slate-950 via-slate-950/80 to-transparent z-20">
        <div className="flex flex-col items-center">
            {error && <div className="text-red-400 text-[10px] mb-4 bg-red-950/80 px-4 py-2 rounded border border-red-500/50 mono uppercase tracking-widest">{error}</div>}

            <div className="flex items-center space-x-12">
                <button 
                    onClick={() => fileInputRef.current?.click()}
                    disabled={isProcessing}
                    className="group bg-slate-800/80 p-4 rounded-2xl border border-slate-700 text-slate-400 active:scale-90 transition-all hover:text-white hover:border-blue-500 disabled:opacity-50"
                >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                    </svg>
                </button>

                <button 
                    onClick={captureAndAnalyze}
                    disabled={isProcessing}
                    className="relative w-24 h-24 rounded-full flex items-center justify-center group active:scale-[0.85] transition-all"
                >
                    <div className="absolute inset-0 rounded-full border-4 border-dashed border-slate-700 opacity-50 pulse-ring"></div>
                    <div className="w-18 h-18 rounded-full flex items-center justify-center bg-white shadow-[0_0_30px_rgba(59,130,246,0.3)]">
                        <div className="w-16 h-16 border-2 border-slate-200 rounded-full flex items-center justify-center">
                          <div className="w-12 h-12 bg-slate-900 rounded-full"></div>
                        </div>
                    </div>
                </button>

                <div className="w-14"></div>
            </div>

            <div className="mt-8 flex flex-col items-center">
                <div className="text-[10px] font-bold text-blue-500 uppercase tracking-[0.3em] mb-1 italic">
                    Focus on Structure
                </div>
            </div>
        </div>
      </div>

      <input 
        type="file" 
        ref={fileInputRef} 
        className="hidden" 
        accept="image/*" 
        onChange={handleFileUpload} 
      />
      <canvas ref={canvasRef} />
    </div>
  );
};

