import React, { useRef, useState, useEffect } from 'react';
import { analyzeImage } from '../services/gemini.ts';
import { AnalysisResult } from '../types.ts';

interface CameraInterfaceProps {
  onBack: () => void;
  onComplete: (result: AnalysisResult) => void;
}

const CameraInterface: React.FC<CameraInterfaceProps> = ({ onBack, onComplete }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [angle, setAngle] = useState({ alpha: 0, beta: 0, gamma: 0 });
  const [loadingText, setLoadingText] = useState('Initializing Analysis...');

  const loadingMessages = [
    'Detecting structural geometry...',
    'Parsing material properties...',
    'Checking IS Code compliance...',
    'Calculating load thresholds...',
    'Scanning for surface defects...',
    'Generating cost estimations...'
  ];

  useEffect(() => {
    let interval: number;
    if (isProcessing) {
      let i = 0;
      interval = window.setInterval(() => {
        setLoadingText(loadingMessages[i % loadingMessages.length]);
        i++;
      }, 2000);
    }
    return () => clearInterval(interval);
  }, [isProcessing]);

  useEffect(() => {
    const startCamera = async () => {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1920 }, height: { ideal: 1080 } },
          audio: false 
        });
        setStream(s);
        if (videoRef.current) {
          videoRef.current.srcObject = s;
        }
      } catch (err) {
        console.error('Camera access error:', err);
        setError('CRITICAL: CAMERA_PERM_DENIED');
      }
    };

    const handleOrientation = (e: DeviceOrientationEvent) => {
      setAngle({
        alpha: Math.round(e.alpha || 0),
        beta: Math.round(e.beta || 0),
        gamma: Math.round(e.gamma || 0)
      });
    };

    startCamera();
    window.addEventListener('deviceorientation', handleOrientation);

    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
      window.removeEventListener('deviceorientation', handleOrientation);
    };
  }, []);

  const captureAndAnalyze = async () => {
    if (!videoRef.current || !canvasRef.current) return;

    setIsProcessing(true);
    setError(null);

    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    if (ctx) {
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
      const imageData = canvas.toDataURL('image/jpeg', 0.8);
      const base64Image = imageData.split(',')[1];

      try {
        const data = await analyzeImage(base64Image);
        onComplete({
          id: Date.now().toString(),
          timestamp: Date.now(),
          image: imageData,
          data
        });
      } catch (err) {
        console.error('Capture error:', err);
        setError('PROC_ERROR: CAPTURE_FAIL');
        setIsProcessing(false);
      }
    }
  };

  return (
    <div className="relative h-full w-full bg-black overflow-hidden flex flex-col font-mono">
      {/* Processing Overlay */}
      {isProcessing && (
        <div className="absolute inset-0 z-50 bg-slate-950/95 backdrop-blur-xl flex flex-col items-center justify-center p-8">
          <div className="relative mb-12">
            <div className="w-32 h-32 border-4 border-blue-500/20 rounded-full pulse-ring absolute inset-0"></div>
            <div className="w-32 h-32 border-4 border-t-blue-500 rounded-full animate-spin"></div>
            <div className="absolute inset-0 flex items-center justify-center text-3xl">🏗️</div>
          </div>
          <h2 className="text-xl font-black text-white uppercase tracking-tighter italic mb-2">Analyzing Capture</h2>
          <p className="text-blue-500 text-[10px] font-bold uppercase tracking-[0.3em] mb-8 animate-pulse">{loadingText}</p>
        </div>
      )}

      {/* Video Feed */}
      <video ref={videoRef} autoPlay playsInline className="flex-1 w-full object-cover opacity-80" />
      <div className="absolute inset-0 z-30 pointer-events-none overflow-hidden"><div className="scanline"></div></div>

      {/* HUD */}
      <div className="absolute inset-0 pointer-events-none p-6 z-10 text-[10px] text-blue-400 flex flex-col justify-between">
        <div className="flex justify-between">
            <div className="flex flex-col space-y-1">
                <div className="flex items-center space-x-2">
                    <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse"></span>
                    <span className="font-bold uppercase italic">Site_Vision_Live</span>
                </div>
            </div>
            <div className="text-right">BETA: {angle.beta}° | GAM: {angle.gamma}°</div>
        </div>
        <div className="flex-1 flex items-center justify-center">
          <div className="w-64 h-64 border border-blue-500/30 relative">
             <div className="absolute top-0 left-0 w-8 h-8 border-t-2 border-l-2 border-blue-500"></div>
             <div className="absolute bottom-0 right-0 w-8 h-8 border-b-2 border-r-2 border-blue-500"></div>
          </div>
        </div>
      </div>

      <div className="absolute top-0 left-0 right-0 p-6 flex justify-between z-20">
        <button onClick={onBack} className="bg-slate-900/80 p-3 rounded-xl border border-slate-700 text-white"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>
      </div>

      <div className="p-10 bg-gradient-to-t from-slate-950 flex flex-col items-center z-20">
        {error && <div className="text-red-400 text-[10px] mb-4 uppercase">{error}</div>}
        <button 
          onClick={captureAndAnalyze}
          disabled={isProcessing}
          className="relative w-24 h-24 rounded-full flex items-center justify-center group active:scale-[0.85] transition-all"
        >
          <div className="absolute inset-0 rounded-full border-4 border-dashed border-blue-500/50 pulse-ring"></div>
          <div className="w-18 h-18 rounded-full bg-white shadow-2xl flex items-center justify-center">
             <div className="w-16 h-16 border-2 border-slate-200 rounded-full flex items-center justify-center">
                <div className="w-10 h-10 bg-slate-900 rounded-full flex items-center justify-center">
                    <div className="w-2 h-2 bg-blue-500 rounded-full animate-ping"></div>
                </div>
             </div>
          </div>
        </button>
        <div className="mt-4 text-[10px] text-blue-500 font-bold tracking-widest uppercase">Capture Frame for AI Analysis</div>
      </div>
      <canvas ref={canvasRef} />
    </div>
  );
};

export default CameraInterface;

