        }
      });

      // Pass history to the model
      const response = await chat.sendMessage({ message: userMessage });
      setMessages(prev => [...prev, { role: 'model', text: response.text || "I'm sorry, I couldn't process that request." }]);
    } catch (err) {
      setMessages(prev => [...prev, { role: 'model', text: "ERROR: Connection to Engineering Neural Network lost." }]);
