import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { CIVIL_ENGINEER_SYSTEM_PROMPT } from "../constants.ts";
import { StructuralAnalysis } from "../types.ts";

export const analyzeImage = async (base64Image: string, userContext?: string): Promise<StructuralAnalysis> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY_MISSING");
  }

  const ai = new GoogleGenAI({ apiKey });

  const prompt = userContext 
    ? `The user says this detection was wrong. User context: "${userContext}". Please re-analyze this image with this specific focus. Identify object, specs, and defects. Return valid JSON.`
    : "Analyze this image for civil engineering details. Identify the object, its specs, construction method, load capacity, costs, and scan for any defects or quality issues. Return valid JSON.";

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [
      {
        parts: [
          { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
          { text: prompt }
        ]
      }
    ],
    config: {
      systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT,
      responseMimeType: 'application/json',
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          elementName: { type: Type.STRING },
          type: { type: Type.STRING },
          dimensions: { type: Type.STRING },
          materialDetails: { type: Type.STRING },
          structuralFunction: { type: Type.STRING },
          loadCapacity: { type: Type.STRING },
          costEstimate: { type: Type.STRING },
          isCodeReferences: { type: Type.ARRAY, items: { type: Type.STRING } },
          constructionSteps: { type: Type.ARRAY, items: { type: Type.STRING } },
          qualityChecks: { type: Type.ARRAY, items: { type: Type.STRING } },
          defects: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                type: { type: Type.STRING },
                severity: { type: Type.STRING, description: "Minor, Moderate, Major, or Critical" },
                cause: { type: Type.STRING },
                impact: { type: Type.STRING },
                remedy: { type: Type.STRING }
              },
              required: ["type", "severity", "remedy"]
            }
          }
        },
        required: ["elementName", "type", "dimensions", "defects"]
      }
    }
  });

  return JSON.parse(response.text || '{}') as StructuralAnalysis;
};

export const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
};

export const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState } from 'react';
import { AnalysisResult, UserRole, StructuralAnalysis } from '../types.ts';
import EngineeringChatbot from './EngineeringChatbot.tsx';
