import { GoogleGenAI, Type } from "@google/genai";
import { CIVIL_ENGINEER_SYSTEM_PROMPT } from "../constants.ts";
import { StructuralAnalysis } from "../types.ts";

export const analyzeImage = async (base64Image: string, userContext?: string): Promise<StructuralAnalysis> => {
  const apiKey = process.env.API_KEY;

  if (!apiKey) {
    const errorMsg = "API_KEY_MISSING: Ensure API_KEY is set in Vercel/Environment variables.";
    console.error(errorMsg);
    throw new Error(errorMsg);
  }

  const ai = new GoogleGenAI({ apiKey });

  const promptText = userContext 
    ? `The user says the previous detection was wrong. Correct focus: "${userContext}". Re-analyze the image. Start with a simple summary: 1. What is it? 2. What is it used for? 3. How is it used? Use very simple English. Then provide technical specs and defects in JSON.`
    : `Perform a structural site analysis. First, explain in very simple English for a beginner: 
       - Exactly what is this object? 
       - What is its primary use or purpose on a site? 
       - How does it function or how is it used by engineers?
       Then provide full technical data and defect analysis in JSON format.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
          { text: promptText }
        ]
      },
      config: {
        systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT + "\nIMPORTANT: The fields 'basicDescription', 'purpose', and 'usage' must be written in simple, non-technical English for easy understanding by anyone.",
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            elementName: { type: Type.STRING },
            basicDescription: { type: Type.STRING, description: "Simple explanation of what the object is." },
            purpose: { type: Type.STRING, description: "Simple explanation of what it is used for." },
            usage: { type: Type.STRING, description: "Simple explanation of how it is used on site." },
            type: { type: Type.STRING },
            dimensions: { type: Type.STRING },
            materialDetails: { type: Type.STRING },
            structuralFunction: { type: Type.STRING },
            loadCapacity: { type: Type.STRING },
            costEstimate: { type: Type.STRING },
            isCodeReferences: { type: Type.ARRAY, items: { type: Type.STRING } },
            constructionSteps: { type: Type.ARRAY, items: { type: Type.STRING } },
            qualityChecks: { type: Type.ARRAY, items: { type: Type.STRING } },
            defects: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  type: { type: Type.STRING },
                  severity: { type: Type.STRING, description: "Minor, Moderate, Major, or Critical" },
                  cause: { type: Type.STRING },
                  impact: { type: Type.STRING },
                  remedy: { type: Type.STRING }
                },
                required: ["type", "severity", "remedy"]
              }
            }
          },
          required: ["elementName", "basicDescription", "purpose", "usage", "defects"]
        }
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("EMPTY_RESPONSE: The AI returned no content.");
    }

    return JSON.parse(text) as StructuralAnalysis;
  } catch (error: any) {
    console.error("Gemini Analysis Detailed Error:", error);
    // Rethrow with more context if it's a specific API error
    if (error.message?.includes('403')) {
      throw new Error("AUTH_ERROR: Invalid API Key or Permissions.");
    }
    if (error.message?.includes('429')) {
      throw new Error("QUOTA_ERROR: API Rate limit reached.");
    }
    throw error;
  }
};

export const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
};

export const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useRef, useState, useEffect } from 'react';
import { analyzeImage } from '../services/gemini.ts';
import { AnalysisResult } from '../types.ts';

interface CameraInterfaceProps {
  onBack: () => void;
  onComplete: (result: AnalysisResult) => void;
}

const CameraInterface: React.FC<CameraInterfaceProps> = ({ onBack, onComplete }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [progress, setProgress] = useState(0);
  const [timer, setTimer] = useState(10.0);

  useEffect(() => {
    let interval: number;
    if (isProcessing) {
      interval = window.setInterval(() => {
        setProgress(p => Math.min(p + 1.5, 99));
        setTimer(t => Math.max(t - 0.1, 0.5));
      }, 100);
    }
    return () => clearInterval(interval);
  }, [isProcessing]);

  useEffect(() => {
    const startCamera = async () => {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } },
          audio: false 
        });
        setStream(s);
        if (videoRef.current) videoRef.current.srcObject = s;
      } catch (err) {
        console.error("Camera Access Error:", err);
        setError('CRITICAL: CAMERA_ACCESS_DENIED');
      }
    };
    startCamera();
    return () => stream?.getTracks().forEach(track => track.stop());
  }, []);

  const handleCapture = async () => {
    if (!videoRef.current || !canvasRef.current || isProcessing) return;

    setIsProcessing(true);
    setProgress(0);
    setTimer(10.0);
    setError(null);

    const canvas = canvasRef.current;
    const video = videoRef.current;
    const ctx = canvas.getContext('2d');

    if (ctx) {
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      ctx.drawImage(video, 0, 0);
      const imageData = canvas.toDataURL('image/jpeg', 0.8);
      const base64 = imageData.split(',')[1];

      try {
        const result = await analyzeImage(base64);
        onComplete({
          id: Date.now().toString(),
          timestamp: Date.now(),
          image: imageData,
          data: result
        });
      } catch (err: any) {
        console.error("Detection Failure Context:", err);
        // Show the actual error message if possible to help debug Vercel issues
        const errorType = err.message?.includes('API_KEY') ? 'AUTH_ERROR' : 'SITE_SCAN_FAILED';
        setError(`DETECTION_ERROR: ${err.message || errorType}`);
        setIsProcessing(false);
      }
    }
  };

  return (
    <div className="relative h-full w-full bg-black overflow-hidden flex flex-col font-mono">
      {isProcessing && (
        <div className="absolute inset-0 z-[100] bg-slate-950 flex flex-col items-center justify-center p-10 text-center">
          <div className="relative mb-10">
            <div className="w-24 h-24 border-4 border-blue-500/20 rounded-full"></div>
            <div className="w-24 h-24 border-4 border-t-blue-500 rounded-full animate-spin absolute top-0"></div>
          </div>
          <h2 className="text-xl font-black text-white uppercase italic tracking-tighter mb-4">Neural Analysis Active</h2>
          <div className="w-full max-w-xs bg-slate-900 h-2 rounded-full overflow-hidden mb-4">
             <div className="bg-blue-500 h-full transition-all duration-300" style={{ width: `${progress}%` }}></div>
          </div>
          <p className="text-blue-500 text-xs font-bold uppercase tracking-[0.2em]">Estimated Wait: {timer.toFixed(1)}s</p>
        </div>
      )}

      <video ref={videoRef} autoPlay playsInline className="flex-1 w-full object-cover" />
      <div className="absolute inset-0 z-10 pointer-events-none">
        <div className="scanline"></div>
        <div className="absolute inset-0 border-[2px] border-blue-500/20 m-4"></div>
      </div>

      <div className="absolute bottom-0 left-0 right-0 p-12 flex flex-col items-center z-50 bg-gradient-to-t from-black/80 to-transparent">
        {error && (
          <div className="mb-4 text-red-500 text-[10px] font-bold uppercase bg-black/60 px-4 py-2 rounded border border-red-500/20 backdrop-blur-sm max-w-xs text-center">
            {error}
          </div>
        )}
        <button 
          onClick={handleCapture}
          className="w-20 h-20 bg-white rounded-full flex items-center justify-center border-8 border-slate-400/30 active:scale-90 transition-all shadow-2xl"
          aria-label="Capture Image"
        >
          <div className="w-14 h-14 border-2 border-slate-900 rounded-full flex items-center justify-center bg-slate-100">
             <div className="w-4 h-4 bg-blue-600 rounded-sm"></div>
          </div>
        </button>
        <span className="mt-4 text-[10px] text-white/80 font-black uppercase tracking-widest shadow-lg">Run Structural Scan</span>
      </div>

      <button onClick={onBack} className="absolute top-6 left-6 z-50 bg-black/40 p-4 rounded-2xl border border-white/10">
        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
        </svg>
      </button>

      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default CameraInterface;

import React, { useRef, useState, useEffect } from 'react';
