import React, { useState, useEffect } from 'react';
import { AppMode, UserRole, AnalysisResult } from './types.ts';
import CameraInterface from './components/CameraInterface.tsx';
import Home from './components/Home.tsx';
import AnalysisView from './components/AnalysisView.tsx';
import Knowledge from './components/Knowledge.tsx';
import Settings from './components/Settings.tsx';
import UploadView from './components/UploadView.tsx';
import { MOCK_ANALYSES } from './constants.ts';

const App: React.FC = () => {
  const [mode, setMode] = useState<AppMode>(AppMode.HOME);
  const [role, setRole] = useState<UserRole>(UserRole.STUDENT);
  const [currentAnalysis, setCurrentAnalysis] = useState<AnalysisResult | null>(null);
  const [history, setHistory] = useState<AnalysisResult[]>(MOCK_ANALYSES);
  const [hasApiKey, setHasApiKey] = useState<boolean>(true); // Initial state

  // Check for API key presence more aggressively
  useEffect(() => {
    const checkKey = async () => {
      // Check environment variable OR window.aistudio state
      const envKey = process.env.API_KEY || (window as any).process?.env?.API_KEY;
      const studioKey = await (window as any).aistudio?.hasSelectedApiKey();

      if (!envKey && !studioKey) {
        setHasApiKey(false);
      } else {
        setHasApiKey(true);
      }
    };
    checkKey();

    // Set a small interval to re-check in case injection is delayed
    const interval = setInterval(checkKey, 2000);
    return () => clearInterval(interval);
  }, []);

  const handleOpenKeySelection = async () => {
    if ((window as any).aistudio?.openSelectKey) {
      try {
        await (window as any).aistudio.openSelectKey();
        // Force state update immediately after dialog
        setHasApiKey(true);
      } catch (err) {
        console.error("Key selection failed:", err);
      }
    } else {
      alert("Billing setup required: Please ensure you are viewing this app via the authorized Vercel URL.");
    }
  };

  const startCamera = () => setMode(AppMode.ANALYSIS);
  const startUpload = () => setMode(AppMode.UPLOAD);
  const openKnowledge = () => setMode(AppMode.KNOWLEDGE);
  const openSettings = () => setMode(AppMode.SETTINGS);

  const handleCaptureComplete = (result: AnalysisResult) => {
    setCurrentAnalysis(result);
    setHistory(prev => [result, ...prev]);
    setMode(AppMode.ANALYSIS);
  };

  const handleBack = () => {
    setMode(AppMode.HOME);
    setCurrentAnalysis(null);
  };

  if (!hasApiKey) {
    return (
      <div className="flex flex-col h-screen bg-slate-950 items-center justify-center p-8 text-center font-mono">
        <div className="blueprint-border p-10 max-w-sm w-full bg-slate-900/50 backdrop-blur-xl">
          <div className="w-16 h-16 bg-blue-600 rounded-2xl mx-auto mb-6 flex items-center justify-center text-3xl shadow-2xl shadow-blue-500/20">
            📡
          </div>
          <h1 className="text-xl font-black text-white uppercase italic tracking-tighter mb-4">Neural Link Required</h1>
          <p className="text-[10px] text-slate-400 leading-relaxed mb-8 uppercase font-bold">
            To enable structural vision, click below to connect your Google Cloud billing project.
          </p>
          <button 
            onClick={handleOpenKeySelection}
            className="w-full bg-blue-600 hover:bg-blue-500 text-white py-4 rounded-xl font-black text-[10px] uppercase tracking-[0.2em] transition-all active:scale-95 shadow-lg shadow-blue-500/30"
          >
            Establish Secure Link
          </button>
          <div className="mt-6 flex items-center justify-center space-x-2">
            <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse"></span>
            <span className="text-[8px] text-slate-500 uppercase font-black">Ready for Initialization</span>
          </div>
          <p className="mt-8 text-[8px] text-slate-600 leading-tight">
            Note: You must select a key from a project with an active billing account.
            <br/><br/>
            <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" className="text-blue-500 underline">Billing Documentation</a>
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-slate-900 text-white overflow-hidden font-sans">
      {mode === AppMode.HOME && (
        <Home 
          onStart={startCamera} 
          onUpload={startUpload}
          onKnowledge={openKnowledge}
          onSettings={openSettings}
          history={history}
          onSelectHistory={(item) => {
            setCurrentAnalysis(item);
            setMode(AppMode.ANALYSIS);
          }}
        />
      )}

      {mode === AppMode.ANALYSIS && !currentAnalysis && (
        <CameraInterface 
          onBack={handleBack} 
          onComplete={handleCaptureComplete} 
        />
      )}

      {mode === AppMode.UPLOAD && (
        <UploadView 
          onBack={handleBack} 
          onComplete={handleCaptureComplete} 
        />
      )}

      {mode === AppMode.ANALYSIS && currentAnalysis && (
        <AnalysisView 
          analysis={currentAnalysis} 
          onBack={handleBack} 
          role={role}
        />
      )}

      {mode === AppMode.KNOWLEDGE && (
        <Knowledge onBack={handleBack} />
      )}

      {mode === AppMode.SETTINGS && (
        <Settings onBack={handleBack} role={role} setRole={setRole} stats={{ analyses: history.length, saved: 5, days: 12 }} />
      )}
    </div>
  );
};

export default App;

