  }

  const ai = new GoogleGenAI({ apiKey });

  const promptText = userContext 
    ? `RE-ANALYSIS: Focus on "${userContext}". Provide a simple executive summary, technical details, and defects in JSON.`
    : `STRUCTURAL SITE SCAN: Analyze the image as a world-class civil engineer.
       1. CREATE AN EXECUTIVE SUMMARY: A 2-3 sentence explanation for a beginner and 3-4 bullet points of the most important engineering facts.
       2. TECHNICAL SPECS: Materials, dimensions, and codes.
       3. DEFECTS: Any visible issues.
       Return the entire analysis as valid JSON.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
          { text: promptText }
        ]
      },
      config: {
        systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT + "\nIMPORTANT: You must include an 'executiveSummary' object. The 'brief' should be very simple English. The 'keyEngineeringPoints' should be the 3-4 most critical facts about the structure's safety or function.",
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            elementName: { type: Type.STRING },
            basicDescription: { type: Type.STRING },
            purpose: { type: Type.STRING },
            usage: { type: Type.STRING },
            executiveSummary: {
              type: Type.OBJECT,
              properties: {
                brief: { type: Type.STRING, description: "A simple 2-3 sentence overview." },
                keyEngineeringPoints: { 
                  type: Type.ARRAY, 
                  items: { type: Type.STRING },
                  description: "3-4 bullet points of critical engineering facts."
                }
              },
              required: ["brief", "keyEngineeringPoints"]
            },
            type: { type: Type.STRING },
            dimensions: { type: Type.STRING },
            materialDetails: { type: Type.STRING },
            structuralFunction: { type: Type.STRING },
            loadCapacity: { type: Type.STRING },
            costEstimate: { type: Type.STRING },
            isCodeReferences: { type: Type.ARRAY, items: { type: Type.STRING } },
            constructionSteps: { type: Type.ARRAY, items: { type: Type.STRING } },
            qualityChecks: { type: Type.ARRAY, items: { type: Type.STRING } },
            defects: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  type: { type: Type.STRING },
                  severity: { type: Type.STRING },
                  cause: { type: Type.STRING },
                  impact: { type: Type.STRING },
                  remedy: { type: Type.STRING }
                },
                required: ["type", "severity", "remedy"]
              }
            }
          },
          required: ["elementName", "executiveSummary", "defects"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("EMPTY_RESPONSE");
    return JSON.parse(text) as StructuralAnalysis;
  } catch (error: any) {
    console.error("Analysis Error:", error);
    throw error;
  }
};

export const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
};

export const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

