import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from '@google/genai';
import { StructuralAnalysis } from '../types.ts';
import { CIVIL_ENGINEER_SYSTEM_PROMPT } from '../constants.ts';

interface EngineeringChatbotProps {
  context: StructuralAnalysis;
}

const EngineeringChatbot: React.FC<EngineeringChatbotProps> = ({ context }) => {
  const [messages, setMessages] = useState<{ role: 'user' | 'model'; text: string }[]>([
    { role: 'model', text: `Expert Consultant online. I've processed the scan for the ${context.elementName}. How can I assist you with technical specifications, methodology, or IS Code compliance?` }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsTyping(true);

    try {
      const apiKey = process.env.API_KEY || (window as any).process?.env?.API_KEY;
      const ai = new GoogleGenAI({ apiKey: apiKey || '' });

      const chat = ai.chats.create({
        model: 'gemini-3-pro-preview',
        config: {
          systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT + `\n
          CONTEXT: Inspecting ${context.elementName}.
          METHODOLOGY_DATA: ${JSON.stringify(context.constructionMethodology)}
          LAB_EXPERIMENT_DATA: ${JSON.stringify(context.labExperiment)}
          DEFECTS_DATA: ${JSON.stringify(context.defects)}

          FORMATTING RULES:
          1. Use **bold** for key terms and IS Codes.
          2. Use bullet points for lists.
          3. Use clear paragraph breaks.
          4. If discussing a lab test, explain the 'why' behind the procedure steps.
          5. Avoid long walls of text.`,
        }
      });

      const response = await chat.sendMessage({ message: userMessage });
      setMessages(prev => [...prev, { role: 'model', text: response.text || "Consultant is unable to provide a precise response. Please re-establish Neural Link." }]);
    } catch (err) {
      console.error("Chat Error:", err);
      setMessages(prev => [...prev, { role: 'model', text: "ERROR: Secure Link interrupted. Please verify your connection or re-initialize." }]);
    } finally {
      setIsTyping(false);
    }
  };

  const formatText = (text: string) => {
    return text.split('\n').map((line, i) => {
      let processed = line;
      processed = processed.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
      const isBullet = processed.trim().startsWith('* ') || processed.trim().startsWith('- ');

      return (
        <p key={i} 
           className={`mb-2 ${isBullet ? 'pl-4 relative' : ''}`}
           dangerouslySetInnerHTML={{ __html: isBullet ? `<span class="absolute left-0">•</span> ${processed.substring(2)}` : processed }} 
        />
      );
    });
  };

  return (
    <div className="flex flex-col h-full bg-slate-950 font-mono">
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-4 scrollbar-hide">
        {messages.map((m, idx) => (
          <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-4 rounded-2xl text-xs font-bold leading-relaxed ${
              m.role === 'user' 
              ? 'bg-blue-600 text-white rounded-tr-none shadow-lg shadow-blue-500/10' 
              : 'bg-slate-900 text-slate-300 border border-slate-800 rounded-tl-none'
            }`}>
              <div className="text-[8px] uppercase opacity-50 mb-2 tracking-widest">{m.role === 'user' ? 'Operator' : 'AI Consultant'}</div>
              <div className="chat-content">
                {formatText(m.text)}
              </div>
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex justify-start">
            <div className="bg-slate-900 text-blue-500 p-4 rounded-2xl rounded-tl-none border border-slate-800 flex space-x-1">
              <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce"></div>
              <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
              <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '0.4s' }}></div>
            </div>
          </div>
        )}
      </div>

      <div className="p-6 bg-slate-900/50 border-t border-slate-800">
        <div className="flex items-center bg-slate-950 border border-slate-800 rounded-2xl px-4 py-2">
          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSend()}
            placeholder="CONSULT_ON_METHODOLOGY..."
            className="flex-1 bg-transparent border-none outline-none text-xs font-bold py-2 text-white"
          />
          <button onClick={handleSend} className="p-2 text-blue-500 hover:text-white transition-colors">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
};

export default EngineeringChatbot;

