import { GoogleGenAI, Type } from "@google/genai";
import { CIVIL_ENGINEER_SYSTEM_PROMPT } from "../constants.ts";
import { StructuralAnalysis } from "../types.ts";

export const analyzeImage = async (base64Image: string, userContext?: string): Promise<StructuralAnalysis> => {
  const apiKey = process.env.API_KEY || (window as any).process?.env?.API_KEY;

  if (!apiKey) {
    throw new Error("API_KEY_MISSING: Secure link not established.");
  }

  const ai = new GoogleGenAI({ apiKey });

  const promptText = userContext 
    ? `REFINE ANALYSIS FOR: "${userContext}".
       IF LAB EQUIPMENT: You MUST provide a full 'labExperiment' object with step-by-step preparation and testing procedures.
       IF SITE/STRUCTURE: You MUST provide a full 'constructionMethodology' with concrete mix design and reinforcement specs.
       MANDATORY: Fill 'purpose', 'usage', 'loadCapacity', 'isCodeReferences', and 'qualityChecks' with precise engineering data. No generic text.`
    : `DEEP CIVIL ENGINEERING ANALYSIS:
       1. IDENTIFICATION: Is this a Field Structure (Building/Bridge/Metro) or Lab Apparatus (Slump Cone/CTM/Sieve)?
       2. TECHNICAL SPECS: You MUST provide exact 'elementName', 'purpose', 'usage', 'type', 'dimensions', 'materialDetails', 'loadCapacity'.
       3. SITE DATA: For structures, generate 'constructionMethodology' including concrete Grade (M25/M30), exact Mix Proportions, and detailed Phase Timeline.
       4. LAB DATA: For equipment, generate 'labExperiment' including Objective, full Apparatus list, step-by-step Procedure, and Calculation Formulas.
       5. COMPLIANCE: Cite specific IS Codes (e.g., IS 456, IS 516, IS 1199).
       6. QUALITY & DEFECTS: Provide a list of 'qualityChecks' and any visible 'defects' with severity.
       7. SUMMARY: A concise 'executiveSummary' for site supervisors.
       OUTPUT: Valid JSON only. Do not omit mandatory fields.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
          { text: promptText }
        ]
      },
      config: {
        systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT + "\nYou are an expert site engineer. Your response must be data-rich. For every element, explain its exact purpose and usage in the project lifecycle. If it's a test, describe it like a lab manual.",
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            elementName: { type: Type.STRING },
            basicDescription: { type: Type.STRING },
            purpose: { type: Type.STRING },
            usage: { type: Type.STRING },
            executiveSummary: {
              type: Type.OBJECT,
              properties: {
                brief: { type: Type.STRING },
                keyEngineeringPoints: { type: Type.ARRAY, items: { type: Type.STRING } }
              },
              required: ["brief", "keyEngineeringPoints"]
            },
            type: { type: Type.STRING },
            dimensions: { type: Type.STRING },
            materialDetails: { type: Type.STRING },
            structuralFunction: { type: Type.STRING },
            loadCapacity: { type: Type.STRING },
            costEstimate: { type: Type.STRING },
            isCodeReferences: { type: Type.ARRAY, items: { type: Type.STRING } },
            constructionSteps: { type: Type.ARRAY, items: { type: Type.STRING } },
            qualityChecks: { type: Type.ARRAY, items: { type: Type.STRING } },
            defects: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  type: { type: Type.STRING },
                  severity: { type: Type.STRING },
                  cause: { type: Type.STRING },
                  impact: { type: Type.STRING },
                  remedy: { type: Type.STRING }
                }
              }
            },
            constructionMethodology: {
              type: Type.OBJECT,
              properties: {
                structuralSystem: { type: Type.STRING },
                methodSummary: { type: Type.STRING },
                concreteSpecs: {
                  type: Type.OBJECT,
                  properties: {
                    grade: { type: Type.STRING },
                    mixDesign: {
                      type: Type.ARRAY,
                      items: {
                        type: Type.OBJECT,
                        properties: {
                          material: { type: Type.STRING },
                          proportion: { type: Type.STRING },
                          quantity: { type: Type.STRING }
                        }
                      }
                    },
                    cementType: { type: Type.STRING },
                    wcRatio: { type: Type.STRING },
                    slump: { type: Type.STRING },
                    curingPeriod: { type: Type.STRING }
                  }
                },
                processBreakdown: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      phase: { type: Type.STRING },
                      timeline: { type: Type.STRING },
                      steps: { type: Type.ARRAY, items: { type: Type.STRING } },
                      qualityChecks: { type: Type.ARRAY, items: { type: Type.STRING } }
                    }
                  }
                },
                reinforcementSpecs: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      element: { type: Type.STRING },
                      mainBars: { type: Type.STRING },
                      ties: { type: Type.STRING },
                      grade: { type: Type.STRING }
                    }
                  }
                }
              }
            },
            labExperiment: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                objective: { type: Type.STRING },
                apparatus: { type: Type.ARRAY, items: { type: Type.STRING } },
                materialsMix: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      material: { type: Type.STRING },
                      ratio: { type: Type.STRING },
                      quantity: { type: Type.STRING }
                    }
                  }
                },
                procedure: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      part: { type: Type.STRING },
                      steps: { type: Type.ARRAY, items: { type: Type.STRING } }
                    }
                  }
                },
                calculations: {
                  type: Type.OBJECT,
                  properties: {
                    formula: { type: Type.STRING },
                    variables: { type: Type.STRING },
                    example: { type: Type.STRING }
                  }
                },
                acceptanceCriteria: { type: Type.ARRAY, items: { type: Type.STRING } },
                commonMistakes: { type: Type.ARRAY, items: { type: Type.STRING } },
                referenceStandards: { type: Type.ARRAY, items: { type: Type.STRING } }
              }
            }
          },
          required: ["elementName", "purpose", "usage", "executiveSummary", "qualityChecks"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("EMPTY_RESPONSE");
    return JSON.parse(text) as StructuralAnalysis;
  } catch (error: any) {
    console.error("Analysis Error:", error);
    throw error;
  }
};

export const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
};

export const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

