import React, { useRef, useState, useEffect } from 'react';
import { analyzeImage } from '../services/gemini.ts';
import { AnalysisResult } from '../types.ts';

interface UploadViewProps {
  onBack: () => void;
  onComplete: (result: AnalysisResult) => void;
}

const UploadView: React.FC<UploadViewProps> = ({ onBack, onComplete }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [progress, setProgress] = useState(0);
  const [timeLeft, setTimeLeft] = useState(12.0);

  const getStatusMessage = (p: number) => {
    if (p < 33) return '[Scanning Aggregate Texture...]';
    if (p < 66) return '[Calculating Volumetric Ratios...]';
    return '[Cross-referencing IS Codes...]';
  };

  useEffect(() => {
    let interval: number;

    if (isProcessing) {
      const startTime = Date.now();
      const ESTIMATED_TOTAL_MS = 12000;

      interval = window.setInterval(() => {
        const elapsed = Date.now() - startTime;
        const newProgress = Math.min((elapsed / ESTIMATED_TOTAL_MS) * 100, 96);
        setProgress(newProgress);
        setTimeLeft(Math.max((ESTIMATED_TOTAL_MS - elapsed) / 1000, 0.5));
      }, 100);
    }

    return () => {
      clearInterval(interval);
    };
  }, [isProcessing]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setError(null);
    setIsProcessing(true);
    setProgress(0);
    setTimeLeft(12.0);

    const reader = new FileReader();
    reader.onload = async (event) => {
      const imageData = event.target?.result as string;
      const base64Image = imageData.split(',')[1];

      try {
        const data = await analyzeImage(base64Image);
        setProgress(100);
        setTimeLeft(0);

        setTimeout(() => {
          onComplete({
            id: Date.now().toString(),
            timestamp: Date.now(),
            image: imageData,
            data
          });
        }, 300);
      } catch (err: any) {
        console.error("Upload Error:", err);
        setError(`PROC_ERROR: ${err.message || 'UPLOAD_ANALYSIS_FAILED'}`);
        setIsProcessing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="flex flex-col h-full bg-slate-950 font-mono">
      <div className="px-6 py-4 flex items-center justify-between bg-slate-900 border-b border-blue-500/20">
        <button onClick={onBack} className="p-2 text-slate-400">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
          </svg>
        </button>
        <span className="text-[10px] font-black uppercase text-blue-500 tracking-widest">Document Analysis</span>
        <div className="w-8"></div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-8">
        {isProcessing ? (
          <div className="w-full max-w-xs text-center">
            <div className="relative mb-8 flex justify-center">
               <div className="w-16 h-16 border-2 border-blue-500/10 rounded-full"></div>
               <div className="w-16 h-16 border-2 border-t-blue-500 rounded-full animate-spin absolute top-0"></div>
               <div className="absolute inset-0 flex items-center justify-center text-[8px] font-black text-blue-500">
                {Math.round(progress)}%
               </div>
            </div>
            <h3 className="text-white font-black uppercase tracking-tight mb-2">Processing Data</h3>
            <p className="text-[10px] text-blue-500 uppercase font-bold tracking-widest mb-6 h-4">{getStatusMessage(progress)}</p>

            <div className="w-full bg-slate-900 h-2 rounded-full overflow-hidden mb-4 border border-white/5 shadow-inner">
              <div className="bg-blue-600 h-full transition-all duration-300 shadow-[0_0_15px_#2563eb] relative" style={{ width: `${progress}%` }}>
                <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent animate-[pulse_2s_infinite]"></div>
              </div>
            </div>
            <p className="text-slate-500 text-[9px] font-bold uppercase tracking-[0.2em]">Est. Time Left: {timeLeft.toFixed(1)}s</p>
          </div>
        ) : (
          <div className="w-full max-w-sm space-y-6">
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="w-full bg-slate-900 border-2 border-dashed border-blue-500/20 rounded-3xl p-12 flex flex-col items-center group hover:border-blue-500/50 transition-all shadow-xl"
            >
              <div className="w-16 h-16 bg-blue-500/10 rounded-full flex items-center justify-center mb-6 border border-white/5 shadow-inner">
                 <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                   <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                 </svg>
              </div>
              <span className="text-white font-black uppercase text-xs tracking-widest">Upload Site Photo</span>
              <span className="text-[9px] text-slate-500 mt-2 uppercase font-bold">Supported: JPG, PNG, WEBP</span>
            </button>
            {error && (
              <div className="text-red-500 text-center text-[10px] font-bold uppercase p-4 bg-red-900/10 border border-red-500/20 rounded-xl animate-pulse">
                {error}
              </div>
            )}
          </div>
        )}
      </div>
      <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
    </div>
  );
};

export default UploadView;

