import React, { useState, useMemo } from 'react';
import { AnalysisResult, UserRole, StructuralAnalysis } from '../types.ts';
import EngineeringChatbot from './EngineeringChatbot.tsx';
import { analyzeImage } from '../services/gemini.ts';

interface AnalysisViewProps {
  analysis: AnalysisResult;
  onBack: () => void;
  role: UserRole;
}

const AnalysisView: React.FC<AnalysisViewProps> = ({ analysis: initialAnalysis, onBack, role }) => {
  const [currentAnalysis, setCurrentAnalysis] = useState<AnalysisResult>(initialAnalysis);
  const [isVerified, setIsVerified] = useState(false);
  const [isWrong, setIsWrong] = useState(false);
  const [refinementContext, setRefinementContext] = useState('');
  const [isReAnalyzing, setIsReAnalyzing] = useState(false);
  const [isSynthesizing, setIsSynthesizing] = useState(false);
  const [activeTab, setActiveTab] = useState<'summary' | 'technical' | 'inspection' | 'consult' | 'chat'>('summary');

  const engineeringData = currentAnalysis.data;

  const handleReAnalyze = async () => {
    if (!refinementContext.trim()) return;
    setIsReAnalyzing(true);
    try {
      const base64 = currentAnalysis.image.split(',')[1];
      const newData = await analyzeImage(base64, refinementContext);
      setCurrentAnalysis(prev => ({ ...prev, data: newData }));
      setIsVerified(true);
      setIsWrong(false);
      setRefinementContext('');
      setActiveTab('summary');
    } catch (err) {
      console.error("Re-analysis failed:", err);
      alert("System encountered a processing error. Please retry.");
    } finally {
      setIsReAnalyzing(false);
    }
  };

  const generateReport = () => {
    setIsSynthesizing(true);

    // Aggregate all data into a formatted report
    const timestamp = new Date().toLocaleString();
    const reportContent = `
=========================================
CIVILVISION AI - STRUCTURAL ANALYSIS REPORT
=========================================
GENERATED: ${timestamp}
PROJECT_ID: ${currentAnalysis.id}
-----------------------------------------

1. ELEMENT IDENTIFICATION
-----------------------------------------
NAME: ${engineeringData.elementName}
TYPE: ${engineeringData.type}
DIMENSIONS: ${engineeringData.dimensions}
MATERIAL: ${engineeringData.materialDetails}

2. EXECUTIVE SUMMARY
-----------------------------------------
BRIEF: ${engineeringData.executiveSummary.brief}
KEY POINTS:
${engineeringData.executiveSummary.keyEngineeringPoints.map(p => `- ${p}`).join('\n')}

3. TECHNICAL SPECIFICATIONS (IS 456 & 1199)
-----------------------------------------
PURPOSE: ${engineeringData.purpose}
STRUCTURAL FUNCTION: ${engineeringData.structuralFunction}
LOAD CAPACITY: ${engineeringData.loadCapacity}
IS CODES: ${engineeringData.isCodeReferences?.join(', ') || 'IS 456:2000'}

4. QUALITY & INSPECTION
-----------------------------------------
CHECKS:
${engineeringData.qualityChecks?.map(c => `- ${c}`).join('\n') || 'N/A'}

DEFECTS DETECTED:
${engineeringData.defects?.map(d => `- [${d.severity}] ${d.type}: ${d.cause}`).join('\n') || 'None detected'}

5. EXPERT CONSULTATION
-----------------------------------------
RECOMMENDATIONS:
${engineeringData.consultation?.recommendations?.join('\n- ') || 'Proceed with standard curing protocols.'}

NEXT STEPS:
- Cast 150mm cubes for strength verification.
- Cure for 28 days as per IS 516.
- Maintain W/C ratio 0.40-0.45.

=========================================
END OF REPORT - CIVILVISION AI PRO
=========================================
    `;

    setTimeout(() => {
      const blob = new Blob([reportContent], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `CivilVision_Report_${engineeringData.elementName.replace(/\s+/g, '_')}.txt`;
      link.click();
      setIsSynthesizing(false);
    }, 2000);
  };

  const handleShare = async () => {
    const shareData = {
      title: `Structural Analysis: ${engineeringData.elementName}`,
      text: `CivilVision AI has analyzed this ${engineeringData.elementName}. Findings: ${engineeringData.executiveSummary.brief}`,
      url: window.location.href
    };

    if (navigator.share) {
      try {
        await navigator.share(shareData);
      } catch (err) {
        console.log("Share cancelled or failed:", err);
      }
    } else {
      // Fallback: Copy to clipboard
      try {
        await navigator.clipboard.writeText(`${shareData.text} \n\nView full report in CivilVision AI.`);
        alert("Report summary copied to clipboard.");
