import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from '@google/genai';
import { StructuralAnalysis } from '../types.ts';
import { CIVIL_ENGINEER_SYSTEM_PROMPT } from '../constants.ts';

interface Message {
  role: 'user' | 'model';
  text: string;
  timestamp: string;
}

interface EngineeringChatbotProps {
  context: StructuralAnalysis;
  onMessagesUpdate?: (messages: Message[]) => void;
}

const EngineeringChatbot: React.FC<EngineeringChatbotProps> = ({ context, onMessagesUpdate }) => {
  const [messages, setMessages] = useState<Message[]>([
    { 
      role: 'model', 
      text: `### Expert Consultant Online\nI've processed the scan for the **${context.elementName}**. How can I assist you with technical specifications, methodology, or IS Code compliance?\n\n- **Mix Design** validation\n- **Defect** remediation\n- **IS Code** cross-referencing`,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
    if (onMessagesUpdate) {
        onMessagesUpdate(messages);
    }
  }, [messages, isTyping, onMessagesUpdate]);

  const handleSend = async (customInput?: string) => {
    const userMessage = (customInput || input).trim();
    if (!userMessage || isTyping) return;

    const time = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage, timestamp: time }]);
    setIsTyping(true);

    try {
      const apiKey = process.env.API_KEY || (window as any).process?.env?.API_KEY;
      const ai = new GoogleGenAI({ apiKey: apiKey || '' });

      const chat = ai.chats.create({
        model: 'gemini-3-pro-preview',
        config: {
          systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT + `\n
          CONTEXT: Inspecting ${context.elementName}.
          METHODOLOGY_DATA: ${JSON.stringify(context.constructionMethodology)}
          LAB_EXPERIMENT_DATA: ${JSON.stringify(context.labExperiment)}
          DEFECTS_DATA: ${JSON.stringify(context.defects)}

          FORMATTING RULES:
          1. Use ### for headers.
          2. Use **bold** for key terms and IS Codes.
          3. Use backticks \`value\` for specific engineering measurements like "380 kg/m³".
          4. Use bullet points (- ) for lists.
          5. Ensure highly technical and precise responses.`,
        }
      });

      const response = await chat.sendMessage({ message: userMessage });
      const modelTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      setMessages(prev => [...prev, { 
        role: 'model', 
        text: response.text || "Consultant is unable to provide a precise response. Please re-establish Neural Link.",
        timestamp: modelTime
      }]);
    } catch (err) {
      console.error("Chat Error:", err);
      setMessages(prev => [...prev, { 
        role: 'model', 
        text: "ERROR: Secure Link interrupted. Please verify your connection or re-initialize.",
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  const toggleVoiceInput = () => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Speech recognition is not supported in this browser.");
      return;
    }

    if (isListening) {
      setIsListening(false);
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onerror = () => setIsListening(false);

    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput(transcript);
      // Optional: Auto-send after voice recognition
      // handleSend(transcript);
    };

    recognition.start();
  };

  const formatText = (text: string) => {
    return text.split('\n').map((line, i) => {
      let processed = line.trim();
      if (!processed) return <div key={i} className="h-2" />;

      if (processed.startsWith('### ')) {
        return (
          <h3 key={i} className="text-sm font-black text-white uppercase tracking-tight border-b border-slate-700 pb-1 mb-3 mt-4 first:mt-0">
            {processed.replace('### ', '')}
          </h3>
        );
      }

      const renderSpans = (str: string) => {
        const parts = str.split(/(\*\*.*?\*\*|`.*?`)/g);
        return parts.map((part, index) => {
          if (part.startsWith('**') && part.endsWith('**')) {
            return <strong key={index} className="text-white font-black">{part.slice(2, -2)}</strong>;
          }
          if (part.startsWith('`') && part.endsWith('`')) {
            return <code key={index} className="bg-blue-500/20 text-blue-400 px-1.5 py-0.5 rounded font-mono text-[10px] border border-blue-500/20 mx-0.5">{part.slice(1, -1)}</code>;
          }
          return part;
        });
      };

      if (processed.startsWith('- ') || processed.startsWith('* ')) {
        return (
          <div key={i} className="pl-6 relative mb-2 leading-[1.6]">
            <span className="absolute left-0 top-1.5 w-1.5 h-1.5 bg-orange-500 rounded-sm" />
            <span className="text-slate-200">{renderSpans(processed.substring(2))}</span>
          </div>
        );
      }

      return (
        <p key={i} className="mb-3 text-slate-300 leading-[1.6]">
          {renderSpans(processed)}
        </p>
      );
    });
  };

  return (
    <div className="flex flex-col h-full bg-slate-950 font-mono relative">
      <div 
        ref={scrollRef} 
        className="flex-1 overflow-y-auto p-6 space-y-8 scrollbar-hide pb-32"
      >
        {messages.map((m, idx) => (
          <div key={idx} className={`flex w-full ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`flex flex-col max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
              <div className={`text-[8px] font-black uppercase tracking-[0.2em] mb-1.5 px-2.5 py-1 rounded-full border ${
                m.role === 'user' 
                ? 'bg-blue-500/10 text-blue-400 border-blue-500/20 mr-1' 
                : 'bg-slate-800/50 text-slate-400 border-slate-700/50 ml-1'
              }`}>
                {m.role === 'user' ? 'Field Operator' : 'Expert Consultant'}
              </div>

              <div className={`p-4 text-xs font-bold shadow-2xl relative ${
                m.role === 'user' 
                ? 'bg-[#2563EB] text-white rounded-lg rounded-br-none' 
                : 'bg-[#1F2937] border border-slate-700/50 rounded-lg rounded-bl-none'
              }`}>
                <div className="chat-content">
                  {formatText(m.text)}
                </div>

                <div className={`mt-2 text-[7px] font-black uppercase tracking-tighter opacity-40 ${m.role === 'user' ? 'text-right' : 'text-left'}`}>
                  {m.timestamp}
                </div>
              </div>
            </div>
          </div>
        ))}

        {isTyping && (
          <div className="flex justify-start">
            <div className="flex flex-col items-start max-w-[80%]">
              <div className="text-[8px] font-black uppercase tracking-[0.2em] mb-1.5 px-2.5 py-1 rounded-full bg-slate-800/50 text-slate-400 ml-1 border border-slate-700/50">
                Consultant Processing
              </div>
              <div className="bg-[#1F2937] text-blue-500 p-4 rounded-lg rounded-bl-none border border-slate-700/50 flex space-x-1.5">
                <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce"></div>
                <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
                <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '0.4s' }}></div>
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="absolute bottom-6 left-6 right-6 z-20">
        <div className="bg-slate-900/80 backdrop-blur-2xl border border-blue-500/40 rounded-2xl px-4 py-2 flex items-center shadow-[0_0_25px_rgba(37,99,235,0.25)]">
          <button 
            onClick={toggleVoiceInput}
            className={`p-2 transition-all shrink-0 rounded-full ${isListening ? 'bg-red-500 text-white animate-pulse' : 'text-slate-500 hover:text-blue-400'}`}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
            </svg>
          </button>

          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSend()}
            placeholder={isListening ? "Listening..." : "CONSULT_ON_METHODOLOGY..."}
            className="flex-1 bg-transparent border-none outline-none text-xs font-bold py-3 px-2 text-white placeholder:text-slate-600"
          />

          <button 
            onClick={() => handleSend()} 
            disabled={!input.trim() || isTyping}
            className="p-2 text-blue-500 hover:text-white transition-all disabled:opacity-30 disabled:grayscale"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 transform rotate-45" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
};

