import React, { useRef, useState, useEffect } from 'react';
import { analyzeImage } from '../services/gemini.ts';
import { AnalysisResult } from '../types.ts';

interface CameraInterfaceProps {
  onBack: () => void;
  onComplete: (result: AnalysisResult) => void;
}

const CameraInterface: React.FC<CameraInterfaceProps> = ({ onBack, onComplete }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [progress, setProgress] = useState(0);
  const [timer, setTimer] = useState(12.0);

  const getStatusMessage = (p: number) => {
    if (p < 33) return '[Scanning Aggregate Texture...]';
    if (p < 66) return '[Calculating Volumetric Ratios...]';
    return '[Cross-referencing IS Codes...]';
  };

  useEffect(() => {
    let interval: number;

    if (isProcessing) {
      const startTime = Date.now();
      const ESTIMATED_TOTAL_MS = 12000;

      interval = window.setInterval(() => {
        const elapsed = Date.now() - startTime;
        const newProgress = Math.min((elapsed / ESTIMATED_TOTAL_MS) * 100, 96);
        setProgress(newProgress);
        setTimer(Math.max((ESTIMATED_TOTAL_MS - elapsed) / 1000, 0.5));
      }, 100);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isProcessing]);

  useEffect(() => {
    const startCamera = async () => {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } },
          audio: false 
        });
        setStream(s);
        if (videoRef.current) videoRef.current.srcObject = s;
      } catch (err) {
        console.error("Camera Access Error:", err);
        setError('CRITICAL: CAMERA_ACCESS_DENIED');
      }
    };
    startCamera();
    return () => stream?.getTracks().forEach(track => track.stop());
  }, []);

  const handleCapture = async () => {
    if (!videoRef.current || !canvasRef.current || isProcessing) return;

    setIsProcessing(true);
    setProgress(0);
    setTimer(12.0);
    setError(null);

    const canvas = canvasRef.current;
    const video = videoRef.current;
    const ctx = canvas.getContext('2d');

    if (ctx) {
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      ctx.drawImage(video, 0, 0);
      const imageData = canvas.toDataURL('image/jpeg', 0.8);
      const base64 = imageData.split(',')[1];

      try {
        // Set a global timeout for the API call to prevent "forever loading"
        const resultPromise = analyzeImage(base64);
        const timeoutPromise = new Promise((_, reject) => 
          setTimeout(() => reject(new Error("ENGINEERING_LINK_TIMEOUT")), 30000)
        );

        const result = await Promise.race([resultPromise, timeoutPromise]) as any;

        setProgress(100);
        setTimer(0);
        setTimeout(() => {
          onComplete({
            id: Date.now().toString(),
            timestamp: Date.now(),
            image: imageData,
            data: result
          });
        }, 500);
      } catch (err: any) {
        console.error("Detection Failure:", err);
        setError(`DETECTION_ERROR: ${err.message || 'SITE_SCAN_FAILED'}`);
        // Reset processing state so user can try again
        setIsProcessing(false);
        setProgress(0);
      }
    } else {
      setIsProcessing(false);
      setError("CANVAS_CONTEXT_ERR");
    }
  };

  return (
    <div className="relative h-full w-full bg-black overflow-hidden flex flex-col font-mono">
      {isProcessing && (
        <div className="absolute inset-0 z-[100] bg-slate-950 flex flex-col items-center justify-center p-10 text-center">
          <div className="relative mb-10">
            <div className="w-24 h-24 border-4 border-blue-500/10 rounded-full"></div>
            <div className="w-24 h-24 border-4 border-t-blue-500 rounded-full animate-spin absolute top-0"></div>
            <div className="absolute inset-0 flex items-center justify-center text-[10px] font-black text-blue-500">
              {Math.round(progress)}%
            </div>
          </div>
          <h2 className="text-xl font-black text-white uppercase italic tracking-tighter mb-2">Neural Analysis Active</h2>
          <p className="text-[10px] text-blue-500 uppercase font-bold tracking-widest mb-8 h-4">{getStatusMessage(progress)}</p>

          <div className="w-full max-w-xs bg-slate-900 h-2 rounded-full overflow-hidden mb-4 border border-white/5 shadow-inner">
             <div className="bg-blue-600 h-full transition-all duration-300 shadow-[0_0_15px_#2563eb] relative" style={{ width: `${progress}%` }}>
               <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent animate-[pulse_2s_infinite]"></div>
             </div>
          </div>
          <p className="text-slate-500 text-[9px] font-bold uppercase tracking-[0.2em]">Processing... {timer.toFixed(1)}s remaining</p>

          {timer < 2 && (
            <button 
              onClick={() => setIsProcessing(false)} 
              className="mt-12 text-[8px] text-slate-700 underline uppercase tracking-widest font-black"
            >
              Abort Link Sync
            </button>
          )}
        </div>
      )}

      <video ref={videoRef} autoPlay playsInline className="flex-1 w-full object-cover" />
      <div className="absolute inset-0 z-10 pointer-events-none">
        <div className="scanline"></div>
        <div className="absolute inset-0 border-[2px] border-blue-500/20 m-4"></div>
      </div>

      <div className="absolute bottom-0 left-0 right-0 p-12 flex flex-col items-center z-50 bg-gradient-to-t from-black/80 to-transparent">
        {error && (
          <div className="mb-4 text-red-500 text-[10px] font-bold uppercase bg-black/60 px-4 py-2 rounded border border-red-500/20 backdrop-blur-sm max-w-xs text-center">
            {error}
          </div>
        )}
        <button 
          onClick={handleCapture}
          className="w-20 h-20 bg-white rounded-full flex items-center justify-center border-8 border-slate-400/30 active:scale-90 transition-all shadow-2xl"
          aria-label="Capture Image"
        >
          <div className="w-14 h-14 border-2 border-slate-900 rounded-full flex items-center justify-center bg-slate-100">
             <div className="w-4 h-4 bg-blue-600 rounded-sm"></div>
          </div>
        </button>
        <span className="mt-4 text-[10px] text-white/80 font-black uppercase tracking-widest shadow-lg">Run Structural Scan</span>
      </div>

      <button onClick={onBack} className="absolute top-6 left-6 z-50 bg-black/40 p-4 rounded-2xl border border-white/10">
        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
        </svg>
      </button>

      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default CameraInterface;

import React, { useRef, useState, useEffect } from 'react';
import { analyzeImage } from '../services/gemini.ts';
import { AnalysisResult } from '../types.ts';

interface UploadViewProps {
  onBack: () => void;
  onComplete: (result: AnalysisResult) => void;
}

const UploadView: React.FC<UploadViewProps> = ({ onBack, onComplete }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [progress, setProgress] = useState(0);
  const [timeLeft, setTimeLeft] = useState(12.0);

  const getStatusMessage = (p: number) => {
    if (p < 33) return '[Scanning Aggregate Texture...]';
    if (p < 66) return '[Calculating Volumetric Ratios...]';
    return '[Cross-referencing IS Codes...]';
  };

  useEffect(() => {
    let interval: number;

    if (isProcessing) {
      const startTime = Date.now();
      const ESTIMATED_TOTAL_MS = 12000;

      interval = window.setInterval(() => {
        const elapsed = Date.now() - startTime;
        const newProgress = Math.min((elapsed / ESTIMATED_TOTAL_MS) * 100, 96);
        setProgress(newProgress);
        setTimeLeft(Math.max((ESTIMATED_TOTAL_MS - elapsed) / 1000, 0.5));
      }, 100);
    }

    return () => {
      clearInterval(interval);
    };
  }, [isProcessing]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setError(null);
    setIsProcessing(true);
    setProgress(0);
    setTimeLeft(12.0);

    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = async () => {
        // Resize logic to prevent mobile browser memory issues
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        const MAX_DIM = 1280;

        if (width > height) {
          if (width > MAX_DIM) {
            height *= MAX_DIM / width;
            width = MAX_DIM;
          }
        } else {
          if (height > MAX_DIM) {
            width *= MAX_DIM / height;
            height = MAX_DIM;
          }
        }

        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(img, 0, 0, width, height);
          const imageData = canvas.toDataURL('image/jpeg', 0.85);
          const base64Image = imageData.split(',')[1];

          try {
            const data = await analyzeImage(base64Image);
            setProgress(100);
            setTimeLeft(0);

            setTimeout(() => {
              onComplete({
                id: Date.now().toString(),
                timestamp: Date.now(),
                image: imageData,
                data
              });
            }, 300);
          } catch (err: any) {
            console.error("Upload Error:", err);
            setError(`PROC_ERROR: ${err.message || 'UPLOAD_ANALYSIS_FAILED'}`);
            setIsProcessing(false);
          }
        }
      };
      img.onerror = () => {
        setError("FILE_READ_ERROR: Invalid image format.");
        setIsProcessing(false);
      };
      img.src = event.target?.result as string;
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="flex flex-col h-full bg-slate-950 font-mono">
      <div className="px-6 py-4 flex items-center justify-between bg-slate-900 border-b border-blue-500/20">
        <button onClick={onBack} className="p-2 text-slate-400">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
          </svg>
        </button>
        <span className="text-[10px] font-black uppercase text-blue-500 tracking-widest">Document Analysis</span>
        <div className="w-8"></div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-8">
        {isProcessing ? (
          <div className="w-full max-w-xs text-center">
            <div className="relative mb-8 flex justify-center">
               <div className="w-16 h-16 border-2 border-blue-500/10 rounded-full"></div>
               <div className="w-16 h-16 border-2 border-t-blue-500 rounded-full animate-spin absolute top-0"></div>
               <div className="absolute inset-0 flex items-center justify-center text-[8px] font-black text-blue-500">
                {Math.round(progress)}%
               </div>
            </div>
            <h3 className="text-white font-black uppercase tracking-tight mb-2">Processing Data</h3>
            <p className="text-[10px] text-blue-500 uppercase font-bold tracking-widest mb-6 h-4">{getStatusMessage(progress)}</p>

            <div className="w-full bg-slate-900 h-2 rounded-full overflow-hidden mb-4 border border-white/5 shadow-inner">
              <div className="bg-blue-600 h-full transition-all duration-300 shadow-[0_0_15px_#2563eb] relative" style={{ width: `${progress}%` }}>
                <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent animate-[pulse_2s_infinite]"></div>
              </div>
            </div>
            <p className="text-slate-500 text-[9px] font-bold uppercase tracking-[0.2em]">Est. Time Left: {timeLeft.toFixed(1)}s</p>
          </div>
        ) : (
          <div className="w-full max-w-sm space-y-6">
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="w-full bg-slate-900 border-2 border-dashed border-blue-500/20 rounded-3xl p-12 flex flex-col items-center group hover:border-blue-500/50 transition-all shadow-xl"
            >
              <div className="w-16 h-16 bg-blue-500/10 rounded-full flex items-center justify-center mb-6 border border-white/5 shadow-inner">
                 <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                   <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                 </svg>
              </div>
              <span className="text-white font-black uppercase text-xs tracking-widest">Upload Site Photo</span>
              <span className="text-[9px] text-slate-500 mt-2 uppercase font-bold">Supported: JPG, PNG, WEBP</span>
            </button>
            {error && (
              <div className="text-red-500 text-center text-[10px] font-bold uppercase p-4 bg-red-900/10 border border-red-500/20 rounded-xl animate-pulse">
                {error}
              </div>
            )}
          </div>
        )}
      </div>
      <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
    </div>
  );
};

export default UploadView;

import React, { useState, useMemo } from 'react';
import { AnalysisResult, UserRole, StructuralAnalysis } from '../types.ts';
import EngineeringChatbot from './EngineeringChatbot.tsx';
import { analyzeImage } from '../services/gemini.ts';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

interface AnalysisViewProps {
  analysis: AnalysisResult;
  onBack: () => void;
  role: UserRole;
}

const AnalysisView: React.FC<AnalysisViewProps> = ({ analysis: initialAnalysis, onBack, role }) => {
  const [currentAnalysis, setCurrentAnalysis] = useState<AnalysisResult>(initialAnalysis);
  const [isVerified, setIsVerified] = useState(false);
  const [isWrong, setIsWrong] = useState(false);
  const [refinementContext, setRefinementContext] = useState('');
  const [isReAnalyzing, setIsReAnalyzing] = useState(false);
  const [isSynthesizing, setIsSynthesizing] = useState(false);
  const [activeTab, setActiveTab] = useState<'summary' | 'technical' | 'inspection' | 'consult' | 'chat'>('summary');
  const [chatMessages, setChatMessages] = useState<any[]>([]);

  const engineeringData = currentAnalysis.data;

  const handleReAnalyze = async () => {
    if (!refinementContext.trim()) return;
    setIsReAnalyzing(true);
    try {
      const base64 = currentAnalysis.image.split(',')[1];
      const newData = await analyzeImage(base64, refinementContext);
      setCurrentAnalysis(prev => ({ ...prev, data: newData }));
      setIsVerified(true);
      setIsWrong(false);
      setRefinementContext('');
      setActiveTab('summary');
    } catch (err) {
      console.error("Re-analysis failed:", err);
      alert("System encountered a processing error. Please retry.");
    } finally {
      setIsReAnalyzing(false);
    }
  };

  /**
   * Internal function to generate the jsPDF document instance.
   * Shared by both Download and Share functionalities.
   * Includes an engineering data validation layer.
   */
  const generateReportInternal = async (): Promise<jsPDF> => {
    const doc = new jsPDF();
    const pageWidth = doc.internal.pageSize.getWidth();
    const timestamp = new Date().toLocaleString();
    const margin = 20;
    let yPos = 20;

    // --- 1. Engineering Validation Layer ---
    let validatedGrade = engineeringData.constructionMethodology?.concreteSpecs?.grade || 'M25';
    const mixDesign = engineeringData.constructionMethodology?.concreteSpecs?.mixDesign || [];

    // Grade Verification Logic: Check for M20 Nominal Mix (1:1.5:3)
    const cement = mixDesign.find(m => m.material.toLowerCase().includes('cement'));
    const sand = mixDesign.find(m => m.material.toLowerCase().includes('sand') || m.material.toLowerCase().includes('fine'));
    const aggregate = mixDesign.find(m => m.material.toLowerCase().includes('aggregate') || m.material.toLowerCase().includes('coarse'));

    if (cement?.proportion === '1' && sand?.proportion === '1.5' && aggregate?.proportion === '3') {
      validatedGrade = "M20 (Nominal Mix)";
    }

    // Mix Consistency: W/C Ratio formatting
    let validatedWc = engineeringData.constructionMethodology?.concreteSpecs?.wcRatio || '0.45';
    if (!isNaN(parseFloat(validatedWc))) {
      validatedWc = parseFloat(validatedWc).toFixed(2);
    }

    // IS 456:2000 Cement Content Check for M25
    let validationNote = "";
    if (validatedGrade.includes('M25')) {
      const cementQty = parseFloat(cement?.quantity || '0');
      if (cementQty < 300) {
        validationNote = "NOTE: Cement content below IS 456 minimum (300kg/m³). Verify site exposure conditions.";
      } else if (cementQty > 450) {
        validationNote = "NOTE: Cement content high (>450kg/m³). Monitor heat of hydration.";
      }
    }

    // --- 2. Document Rendering ---

    // Header
    doc.setFontSize(18);
    doc.setTextColor(37, 99, 235); // Blue-600
    doc.setFont('helvetica', 'bold');
    doc.text("CivilVision AI - Engineering Inspection Report", margin, yPos);

    yPos += 10;
    doc.setFontSize(10);
    doc.setTextColor(100);
    doc.setFont('helvetica', 'normal');
    doc.text(`Date: ${timestamp}`, margin, yPos);
    doc.text(`Project ID: ${currentAnalysis.id}`, pageWidth - 70, yPos);

    yPos += 10;
    doc.setDrawColor(200);
    doc.line(margin, yPos, pageWidth - margin, yPos);

    yPos += 15;

    // Visual Evidence
    doc.setFontSize(14);
    doc.setTextColor(0);
    doc.setFont('helvetica', 'bold');
    doc.text("VISUAL EVIDENCE", margin, yPos);

    yPos += 10;
    try {
      const imgWidth = 100;
      const imgHeight = 60;
      const xPos = (pageWidth - imgWidth) / 2;
      doc.addImage(currentAnalysis.image, 'JPEG', xPos, yPos, imgWidth, imgHeight);
      yPos += imgHeight + 15;
    } catch (e) {
      yPos += 10;
      doc.text("[Image Placeholder: Error rendering site photo]", margin, yPos);
      yPos += 10;
    }

    // Section 1: SUMMARY
    doc.setFontSize(14);
    doc.setFont('helvetica', 'bold');
    doc.text("SECTION 1: EXECUTIVE SUMMARY", margin, yPos);
    yPos += 10;

    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');
    const briefSplit = doc.splitTextToSize(engineeringData.executiveSummary.brief, pageWidth - (margin * 2));
    doc.text(briefSplit, margin, yPos);
    yPos += (briefSplit.length * 5) + 5;

    doc.setFont('helvetica', 'bold');
    doc.text("Primary Function & Suitability:", margin, yPos);
    yPos += 7;
    doc.setFont('helvetica', 'normal');
    doc.text(`- Function: ${engineeringData.structuralFunction || 'General Structural Support'}`, margin + 5, yPos);
    yPos += 5;
    doc.text(`- Field Application: ${engineeringData.usage || 'Standard Civil Infrastructure'}`, margin + 5, yPos);
    yPos += 15;

    // Section 2: TECHNICAL
    if (yPos > 240) { doc.addPage(); yPos = 20; }
    doc.setFontSize(14);
    doc.setFont('helvetica', 'bold');
    doc.text("SECTION 2: TECHNICAL SPECIFICATIONS", margin, yPos);
    yPos += 10;

    doc.setFontSize(11);
    doc.text(`Identified Grade: ${validatedGrade}`, margin, yPos);
    yPos += 7;
    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');
    doc.text(`W/C Ratio: ${validatedWc}`, margin, yPos);
    yPos += 10;

    if (mixDesign.length > 0) {
      doc.setFont('helvetica', 'bold');
      doc.text("Concrete Mix Design Table:", margin, yPos);
      yPos += 5;
      (doc as any).autoTable({
        startY: yPos,
        head: [['Material', 'Proportion', 'Quantity', 'Units']],
        body: mixDesign.map(item => {
          const isWater = item.material.toLowerCase().includes('water');
          return [
            item.material, 
            item.proportion, 
            item.quantity, 
            isWater ? 'liters' : 'kg'
          ];
        }),
        margin: { left: margin },
        theme: 'striped', // alternating row colors
        headStyles: { fillColor: [37, 99, 235], fontSize: 10 },
        bodyStyles: { fontSize: 9 },
        alternateRowStyles: { fillColor: [240, 248, 255] }
      });
      yPos = (doc as any).lastAutoTable.finalY + 8;

      if (validationNote) {
        doc.setFontSize(8);
        doc.setTextColor(220, 38, 38); // red-600
        doc.text(validationNote, margin, yPos);
        yPos += 10;
        doc.setTextColor(0);
      } else {
        yPos += 5;
      }
    }

    doc.setFontSize(11);
    doc.setFont('helvetica', 'bold');
    doc.text("Step-by-Step Procedure:", margin, yPos);
    yPos += 7;
    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');
    const steps = engineeringData.constructionSteps || [];
    steps.forEach((step, i) => {
      const stepText = `${i + 1}. ${step}`;
      const splitStep = doc.splitTextToSize(stepText, pageWidth - (margin * 2) - 5);
      if (yPos + (splitStep.length * 5) > 275) { doc.addPage(); yPos = 20; }
      doc.text(splitStep, margin + 5, yPos);
      yPos += (splitStep.length * 5) + 2;
    });
    yPos += 10;

    // Section 3: INSPECTION
    if (yPos > 230) { doc.addPage(); yPos = 20; }
    doc.setFontSize(14);
    doc.setFont('helvetica', 'bold');
    doc.text("SECTION 3: QUALITY & INSPECTION", margin, yPos);
    yPos += 10;

    doc.setFontSize(11);
    doc.text("Quality Inspection Checklist:", margin, yPos);
    yPos += 7;
    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');
    const qChecks = engineeringData.qualityChecks || [];
    qChecks.forEach(check => {
      doc.text(`[ ] ${check}`, margin + 5, yPos);
      yPos += 6;
    });
    yPos += 10;

    doc.setFont('helvetica', 'bold');
    doc.text("Slump Pattern Analysis:", margin, yPos);
    yPos += 7;
    doc.setFont('helvetica', 'normal');
    doc.text("• True Slump: Consistent subsidence, acceptable for standard RCC.", margin + 5, yPos);
    yPos += 5;
    doc.text("• Shear/Collapse: No signs of instability detected in visual assessment.", margin + 5, yPos);
    yPos += 15;

    // Section 4: CONSULT
    if (yPos > 230) { doc.addPage(); yPos = 20; }
    doc.setFontSize(14);
    doc.setFont('helvetica', 'bold');
    doc.text("SECTION 4: EXPERT RECOMMENDATIONS", margin, yPos);
    yPos += 10;

    const recommendations = engineeringData.consultation?.recommendations || [];
    recommendations.forEach(rec => {
      const recText = `• ${rec}`;
      const splitRec = doc.splitTextToSize(recText, pageWidth - (margin * 2) - 5);
      if (yPos + (splitRec.length * 5) > 275) { doc.addPage(); yPos = 20; }
      doc.text(splitRec, margin + 5, yPos);
      yPos += (splitRec.length * 5) + 2;
    });

    yPos += 10;
    doc.setFont('helvetica', 'bold');
    doc.text("Next Steps (Strength Verification):", margin, yPos);
    yPos += 7;
    doc.setFont('helvetica', 'normal');
    const nextSteps = engineeringData.consultation?.nextSteps || [
      "Cast 150mm cubes for strength verification.", 
      "Cure for 28 days as per IS 516 (27±2°C)."
    ];
    nextSteps.forEach(step => {
      doc.text(`- ${step}`, margin + 5, yPos);
      yPos += 6;
    });

    // Section 5: CHAT LOG
    if (chatMessages.length > 0) {
      doc.addPage();
      yPos = 20;
      doc.setFontSize(14);
      doc.setFont('helvetica', 'bold');
      doc.text("SECTION 5: TECHNICAL CHAT LOG", margin, yPos);
      yPos += 15;

      chatMessages.forEach(msg => {
          const roleLabel = msg.role === 'user' ? 'Operator' : 'AI Consultant';
          doc.setFont('helvetica', 'bold');
          doc.setFontSize(9);
          doc.setTextColor(msg.role === 'user' ? 0 : 37, 99, 235);
          doc.text(`${roleLabel} (${msg.timestamp}):`, margin, yPos);
          yPos += 5;

          doc.setFont('helvetica', 'normal');
          doc.setTextColor(0);
          doc.setFontSize(8);
          const msgSplit = doc.splitTextToSize(msg.text, pageWidth - (margin * 2) - 10);
          if (yPos + (msgSplit.length * 4) > 280) { doc.addPage(); yPos = 20; }
          doc.text(msgSplit, margin + 5, yPos);
          yPos += (msgSplit.length * 4) + 6;
      });
    }

    // Footers
    const totalPages = (doc as any).internal.getNumberOfPages();
    for (let i = 1; i <= totalPages; i++) {
      doc.setPage(i);
      const footerY = 285;
      doc.setFontSize(8);
      doc.setTextColor(150);
      doc.setFont('helvetica', 'normal');
      doc.text(`Page ${i} of ${totalPages}`, pageWidth - 40, footerY);

      if (i === totalPages) {
          doc.setTextColor(0);
          doc.setFontSize(10);
          doc.line(margin, footerY - 15, 80, footerY - 15);
          doc.text("Authorized Engineer's Signature", margin, footerY - 10);
          doc.text("Stamp & Designation", margin, footerY - 5);
      }
    }

    return doc;
  };

  const generateReport = async () => {
    setIsSynthesizing(true);
    try {
      const doc = await generateReportInternal();
      doc.save(`CivilVision_Report_${engineeringData.elementName.replace(/\s+/g, '_')}.pdf`);
    } catch (error) {
        console.error("PDF synthesis error:", error);
        alert("Report synthesis failed. Error code: STRUCT_PDF_ERR");
    } finally {
      setIsSynthesizing(false);
    }
  };

  const handleShare = async () => {
    setIsSynthesizing(true);
    try {
      const doc = await generateReportInternal();
      const pdfBlob = doc.output('blob');
      const filename = `CivilVision_Report_${engineeringData.elementName.replace(/\s+/g, '_')}.pdf`;
      const file = new File([pdfBlob], filename, { type: 'application/pdf' });

      const concreteGrade = engineeringData.constructionMethodology?.concreteSpecs?.grade || 'M25';
      const shareData: any = {
        title: `CivilVision AI: Slump Test Analysis Report - ${new Date().toLocaleDateString()}`,
        text: `Technical inspection for Concrete Grade ${concreteGrade} completed. View the attached detailed engineering report.`,
        files: [file]
      };

      if (navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share(shareData);
      } else if (navigator.share) {
        // Fallback for browsers that support sharing text but not files
        await navigator.share({
          title: shareData.title,
          text: shareData.text,
          url: window.location.href
        });
      } else {
        throw new Error("WEB_SHARE_UNAVAILABLE");
      }
    } catch (err: any) {
      console.warn("Native share failed or was cancelled:", err);
      // Fallback: Copy to clipboard
      try {
        const text = `CivilVision AI Report: ${engineeringData.elementName}\nStatus: ${engineeringData.executiveSummary.brief}\nReport Date: ${new Date().toLocaleDateString()}`;
        await navigator.clipboard.writeText(text);
        alert("Native sharing unavailable. Report summary copied to clipboard.");
      } catch (clipErr) {
        alert("Sharing service not available on this device.");
      }
    } finally {
      setIsSynthesizing(false);
    }
  };

  if (!isVerified) {
    return (
      <div className="flex flex-col h-full bg-theme-main font-mono">
        <div className="px-6 py-4 flex items-center justify-between border-b border-theme bg-theme-card/50 backdrop-blur-md">
          <button onClick={onBack} className="p-2 -ml-2 text-theme-muted">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
            </svg>
          </button>
          <span className="text-[10px] font-black uppercase text-blue-500 tracking-[0.2em]">Verification Loop</span>
          <div className="w-8"></div>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-6 flex flex-col items-center pb-24">
          <div className="w-full aspect-video min-h-[220px] rounded-3xl overflow-hidden border border-theme shadow-2xl relative bg-slate-900">
            <img 
              src={currentAnalysis.image} 
              alt="Scan" 
              className="w-full h-full object-contain block" 
              onLoad={(e) => (e.currentTarget.style.opacity = '1')}
              style={{ opacity: 0, transition: 'opacity 0.3s ease-in-out' }}
            />
            <div className="scanline absolute inset-0 pointer-events-none opacity-20"></div>
          </div>

          <div className="w-full bg-theme-card/80 border border-theme rounded-3xl p-6 text-center shadow-lg">
            <h2 className="text-[9px] text-blue-500 font-black uppercase tracking-widest mb-3">Identified Element</h2>
            <div className="text-xl font-black uppercase italic text-theme-main mb-2 leading-tight tracking-tight">{engineeringData.elementName}</div>
            <p className="text-[10px] text-theme-muted font-medium px-4 leading-relaxed italic">
              {engineeringData.executiveSummary?.brief || engineeringData.basicDescription || "Visual identification complete. Awaiting confirm."}
            </p>
          </div>

          {!isWrong ? (
            <div className="w-full space-y-4 pt-4">
              <p className="text-center text-[10px] text-theme-muted font-bold uppercase tracking-widest">Confirm AI accuracy?</p>
              <div className="grid grid-cols-2 gap-4">
                <button 
                  onClick={() => setIsVerified(true)}
                  className="bg-blue-600 hover:bg-blue-500 text-white py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all active:scale-95 shadow-xl shadow-blue-500/20"
                >
                  Confirm
                </button>
                <button 
                  onClick={() => setIsWrong(true)}
                  className="bg-theme-card border border-theme text-theme-muted py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all hover:border-red-500/30 hover:text-red-400"
                >
                  Wrong
                </button>
              </div>
            </div>
          ) : (
            <div className="w-full space-y-6 pt-2 animate-in fade-in slide-in-from-bottom-2 duration-300">
               <div className="space-y-3">
                 <label className="text-[10px] text-blue-500 uppercase font-black ml-1 tracking-widest">Add Context</label>
                 <textarea 
                   value={refinementContext}
                   onChange={(e) => setRefinementContext(e.target.value)}
                   placeholder="e.g. 'Concrete Slump Test setup...'"
                   className="w-full bg-theme-card border border-theme rounded-2xl p-4 text-[11px] font-bold text-theme-main outline-none focus:border-blue-500 h-28 resize-none shadow-inner"
                 />
               </div>
               <div className="flex gap-4">
                 <button onClick={() => setIsWrong(false)} className="flex-1 bg-theme-card text-theme-muted py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest border border-theme">Back</button>
                 <button 
                   disabled={!refinementContext.trim() || isReAnalyzing}
                   onClick={handleReAnalyze}
                   className="flex-[2] bg-blue-600 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest disabled:opacity-50 transition-all"
                 >
                   {isReAnalyzing ? 'Syncing...' : 'Re-Detect Now'}
                 </button>
               </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-theme-main overflow-hidden font-sans">
      {/* Synthesis Overlay */}
      {isSynthesizing && (
        <div className="absolute inset-0 z-[100] bg-slate-950/90 backdrop-blur-xl flex flex-col items-center justify-center p-8 text-center font-mono">
           <div className="w-16 h-16 border-4 border-blue-500/20 border-t-blue-500 rounded-full animate-spin mb-6"></div>
           <h3 className="text-lg font-black text-white uppercase italic tracking-tighter mb-2">Synthesizing Report</h3>
           <p className="text-[10px] text-blue-500 uppercase font-bold tracking-widest">Aggregating Cross-Tab Data...</p>
        </div>
      )}

      <div className="px-6 py-4 flex items-center justify-between bg-theme-card/90 border-b border-theme sticky top-0 z-30 backdrop-blur-xl">
        <button onClick={onBack} className="p-2 -ml-2 text-theme-muted hover:text-theme-main transition-colors">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
          </svg>
        </button>
        <div className="text-center">
            <div className="text-[9px] mono text-blue-500 uppercase font-black tracking-[0.2em]">Engineering Protocol</div>
            <div className="text-xs font-black uppercase truncate max-w-[180px] tracking-tight">{engineeringData.elementName}</div>
        </div>
        <div className="flex items-center space-x-2">
            <div className="w-2 h-2 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.5)]"></div>
            <span className="text-[9px] mono text-theme-muted font-black uppercase">Active</span>
        </div>
      </div>

      <div className="flex-1 flex flex-col overflow-hidden">
        <div className="analysis-content scrollbar-hide">
          <div className="relative w-full h-64 bg-slate-950 overflow-hidden">
            <img src={currentAnalysis.image} alt="Ref" className="w-full h-full object-contain block" />
            <div className="absolute inset-0 bg-gradient-to-t from-theme-main via-transparent to-transparent"></div>
            <div className="absolute bottom-6 left-6 right-6 flex flex-col">
              <h3 className="text-2xl font-black uppercase italic tracking-tighter text-white drop-shadow-2xl leading-none">{engineeringData.elementName}</h3>
              <div className="flex flex-wrap gap-2 mt-3">
                  <span className="bg-blue-600/90 text-white text-[9px] font-bold px-2 py-1 rounded-lg uppercase tracking-wider shadow-lg">{engineeringData.type || "Structural"}</span>
                  <span className="bg-theme-card/90 text-theme-muted text-[9px] font-bold px-2 py-1 rounded-lg border border-theme uppercase tracking-wider mono">{engineeringData.dimensions || "N/A"}</span>
              </div>
            </div>
          </div>

          <div className="sticky top-0 z-20 px-4 py-3 bg-theme-main/95 backdrop-blur-xl border-b border-theme shadow-xl overflow-x-auto scrollbar-hide">
            <div className="flex p-1 bg-theme-card/50 rounded-2xl border border-theme relative min-w-max">
              {[
                { id: 'summary', label: 'Summary' },
                { id: 'technical', label: 'Technical' },
                { id: 'inspection', label: 'Inspection' },
                { id: 'consult', label: 'Consult' },
                { id: 'chat', label: 'Chat' }
              ].map((t) => (
                <button 
                    key={t.id}
                    onClick={() => setActiveTab(t.id as any)}
                    className={`px-4 py-2.5 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all duration-300 relative z-10 ${
                        activeTab === t.id ? 'text-white' : 'text-theme-muted hover:text-theme-main'
                    }`}
                >
                    {activeTab === t.id && (
                      <div className="absolute inset-0 bg-blue-600 rounded-xl shadow-[0_4px_20px_rgba(37,99,235,0.3)]"></div>
                    )}
                    <span className="relative z-10">{t.label}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="p-6 space-y-8 animate-in fade-in duration-500 tab-content">
            {activeTab === 'summary' && (
              <div className="space-y-6">
                <div className="bg-blue-600/10 p-6 rounded-3xl border border-blue-500/20 shadow-xl">
                  <div className="flex items-center space-x-3 mb-6">
                    <div className="w-8 h-8 rounded-full bg-blue-600/20 flex items-center justify-center text-lg shadow-lg">📝</div>
