export const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
};

export const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from '@google/genai';
import { StructuralAnalysis } from '../types.ts';
import { CIVIL_ENGINEER_SYSTEM_PROMPT } from '../constants.ts';

interface Message {
  role: 'user' | 'model';
  text: string;
  timestamp: string;
}

interface EngineeringChatbotProps {
  context: StructuralAnalysis;
  onMessagesUpdate?: (messages: Message[]) => void;
}

const EngineeringChatbot: React.FC<EngineeringChatbotProps> = ({ context, onMessagesUpdate }) => {
  const [messages, setMessages] = useState<Message[]>([
    { 
      role: 'model', 
      text: `### Expert Consultant Online\nI've processed the scan for the **${context.elementName}**. How can I assist you with technical specifications, methodology, or IS Code compliance?\n\n- **Mix Design** validation\n- **Defect** remediation\n- **IS Code** cross-referencing`,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
    if (onMessagesUpdate) {
        onMessagesUpdate(messages);
    }
  }, [messages, isTyping, onMessagesUpdate]);

  const handleSend = async (customInput?: string) => {
    const userMessage = (customInput || input).trim();
    if (!userMessage || isTyping) return;

    const time = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage, timestamp: time }]);
    setIsTyping(true);

    try {
      const apiKey = process.env.API_KEY || (window as any).process?.env?.API_KEY;
      const ai = new GoogleGenAI({ apiKey: apiKey || '' });

      const chat = ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
          thinkingConfig: { thinkingBudget: 0 },
          systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT + `\n
          CONTEXT: Inspecting ${context.elementName}.
          METHODOLOGY_DATA: ${JSON.stringify(context.constructionMethodology)}
          LAB_EXPERIMENT_DATA: ${JSON.stringify(context.labExperiment)}
          DEFECTS_DATA: ${JSON.stringify(context.defects)}

          FORMATTING RULES:
          1. Use ### for headers.
          2. Use **bold** for key terms and IS Codes.
          3. Use backticks \`value\` for specific engineering measurements like "380 kg/m³".
          4. Use bullet points (- ) for lists.
          5. Ensure highly technical and precise responses.`,
        }
      });

      const response = await chat.sendMessage({ message: userMessage });
      const modelTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      setMessages(prev => [...prev, { 
        role: 'model', 
        text: response.text || "Consultant is unable to provide a precise response. Please re-establish Neural Link.",
        timestamp: modelTime
      }]);
    } catch (err) {
      console.error("Chat Error:", err);
      setMessages(prev => [...prev, { 
        role: 'model', 
        text: "ERROR: Secure Link interrupted. Please verify your connection or re-initialize.",
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  const toggleVoiceInput = () => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Speech recognition is not supported in this browser.");
      return;
    }

    if (isListening) {
      setIsListening(false);
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onerror = () => setIsListening(false);

    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput(transcript);
      // Optional: Auto-send after voice recognition
      // handleSend(transcript);
    };

    recognition.start();
  };

  const formatText = (text: string) => {
    return text.split('\n').map((line, i) => {
      let processed = line.trim();
      if (!processed) return <div key={i} className="h-2" />;

      if (processed.startsWith('### ')) {
        return (
          <h3 key={i} className="text-sm font-black text-white uppercase tracking-tight border-b border-slate-700 pb-1 mb-3 mt-4 first:mt-0">
            {processed.replace('### ', '')}
          </h3>
        );
      }

      const renderSpans = (str: string) => {
        const parts = str.split(/(\*\*.*?\*\*|`.*?`)/g);
        return parts.map((part, index) => {
          if (part.startsWith('**') && part.endsWith('**')) {
            return <strong key={index} className="text-white font-black">{part.slice(2, -2)}</strong>;
          }
          if (part.startsWith('`') && part.endsWith('`')) {
            return <code key={index} className="bg-blue-500/20 text-blue-400 px-1.5 py-0.5 rounded font-mono text-[10px] border border-blue-500/20 mx-0.5">{part.slice(1, -1)}</code>;
          }
          return part;
        });
      };

      if (processed.startsWith('- ') || processed.startsWith('* ')) {
        return (
          <div key={i} className="pl-6 relative mb-2 leading-[1.6]">
            <span className="absolute left-0 top-1.5 w-1.5 h-1.5 bg-orange-500 rounded-sm" />
            <span className="text-slate-200">{renderSpans(processed.substring(2))}</span>
          </div>
        );
      }

      return (
        <p key={i} className="mb-3 text-slate-300 leading-[1.6]">
          {renderSpans(processed)}
        </p>
      );
    });
  };

  return (
    <div className="flex flex-col h-full bg-slate-950 font-mono relative">
      <div 
        ref={scrollRef} 
        className="flex-1 overflow-y-auto p-6 space-y-8 scrollbar-hide pb-32"
      >
        {messages.map((m, idx) => (
          <div key={idx} className={`flex w-full ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`flex flex-col max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
              <div className={`text-[8px] font-black uppercase tracking-[0.2em] mb-1.5 px-2.5 py-1 rounded-full border ${
                m.role === 'user' 
                ? 'bg-blue-500/10 text-blue-400 border-blue-500/20 mr-1' 
                : 'bg-slate-800/50 text-slate-400 border-slate-700/50 ml-1'
              }`}>
                {m.role === 'user' ? 'Field Operator' : 'Expert Consultant'}
              </div>

              <div className={`p-4 text-xs font-bold shadow-2xl relative ${
                m.role === 'user' 
                ? 'bg-[#2563EB] text-white rounded-lg rounded-br-none' 
                : 'bg-[#1F2937] border border-slate-700/50 rounded-lg rounded-bl-none'
              }`}>
                <div className="chat-content">
                  {formatText(m.text)}
                </div>

                <div className={`mt-2 text-[7px] font-black uppercase tracking-tighter opacity-40 ${m.role === 'user' ? 'text-right' : 'text-left'}`}>
                  {m.timestamp}
                </div>
              </div>
            </div>
          </div>
        ))}

        {isTyping && (
          <div className="flex justify-start">
            <div className="flex flex-col items-start max-w-[80%]">
              <div className="text-[8px] font-black uppercase tracking-[0.2em] mb-1.5 px-2.5 py-1 rounded-full bg-slate-800/50 text-slate-400 ml-1 border border-slate-700/50">
                Consultant Processing
              </div>
              <div className="bg-[#1F2937] text-blue-500 p-4 rounded-lg rounded-bl-none border border-slate-700/50 flex space-x-1.5">
                <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce"></div>
                <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
                <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '0.4s' }}></div>
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="absolute bottom-6 left-6 right-6 z-20">
        <div className="bg-slate-900/80 backdrop-blur-2xl border border-blue-500/40 rounded-2xl px-4 py-2 flex items-center shadow-[0_0_25px_rgba(37,99,235,0.25)]">
          <button 
            onClick={toggleVoiceInput}
            className={`p-2 transition-all shrink-0 rounded-full ${isListening ? 'bg-red-500 text-white animate-pulse' : 'text-slate-500 hover:text-blue-400'}`}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
            </svg>
          </button>

          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSend()}
            placeholder={isListening ? "Listening..." : "CONSULT_ON_METHODOLOGY..."}
            className="flex-1 bg-transparent border-none outline-none text-xs font-bold py-3 px-2 text-white placeholder:text-slate-600"
          />

          <button 
            onClick={() => handleSend()} 
            disabled={!input.trim() || isTyping}
            className="p-2 text-blue-500 hover:text-white transition-all disabled:opacity-30 disabled:grayscale"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 transform rotate-45" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
};

export default EngineeringChatbot;

import React, { useRef, useState, useEffect } from 'react';
import { analyzeImage } from '../services/gemini.ts';
import { AnalysisResult } from '../types.ts';

interface CameraInterfaceProps {
  onBack: () => void;
  onComplete: (result: AnalysisResult) => void;
}

const CameraInterface: React.FC<CameraInterfaceProps> = ({ onBack, onComplete }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [progress, setProgress] = useState(0);
  const [timer, setTimer] = useState(5.0);

  const getStatusMessage = (p: number) => {
    if (p < 33) return '[Scanning Aggregate Texture...]';
    if (p < 66) return '[Calculating Volumetric Ratios...]';
    return '[Cross-referencing IS Codes...]';
  };

  useEffect(() => {
    let interval: number;

    if (isProcessing) {
      const startTime = Date.now();
      const ESTIMATED_TOTAL_MS = 5000;

      interval = window.setInterval(() => {
        const elapsed = Date.now() - startTime;
        const newProgress = Math.min((elapsed / ESTIMATED_TOTAL_MS) * 100, 98);
        setProgress(newProgress);
        setTimer(Math.max((ESTIMATED_TOTAL_MS - elapsed) / 1000, 0.1));
      }, 50);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isProcessing]);

  useEffect(() => {
    const startCamera = async () => {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } },
          audio: false 
        });
        setStream(s);
        if (videoRef.current) videoRef.current.srcObject = s;
      } catch (err) {
        console.error("Camera Access Error:", err);
        setError('CRITICAL: CAMERA_ACCESS_DENIED');
      }
    };
    startCamera();
    return () => stream?.getTracks().forEach(track => track.stop());
  }, []);

  const handleCapture = async () => {
    if (!videoRef.current || !canvasRef.current || isProcessing) return;

    setIsProcessing(true);
    setProgress(0);
    setTimer(5.0);
    setError(null);

    const canvas = canvasRef.current;
    const video = videoRef.current;
    const ctx = canvas.getContext('2d');

    if (ctx) {
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      ctx.drawImage(video, 0, 0);
      const imageData = canvas.toDataURL('image/jpeg', 0.8);
      const base64 = imageData.split(',')[1];

      try {
        const resultPromise = analyzeImage(base64);
        const timeoutPromise = new Promise((_, reject) => 
          setTimeout(() => reject(new Error("ENGINEERING_LINK_TIMEOUT")), 25000)
        );

        const result = await Promise.race([resultPromise, timeoutPromise]) as any;

        setProgress(100);
        setTimer(0);
        setTimeout(() => {
          onComplete({
            id: Date.now().toString(),
            timestamp: Date.now(),
            image: imageData,
            data: result
          });
        }, 200);
      } catch (err: any) {
        console.error("Detection Failure:", err);
        setError(`DETECTION_ERROR: ${err.message || 'SITE_SCAN_FAILED'}`);
        setIsProcessing(false);
        setProgress(0);
      }
    } else {
      setIsProcessing(false);
      setError("CANVAS_CONTEXT_ERR");
    }
  };

  return (
    <div className="relative h-full w-full bg-black overflow-hidden flex flex-col font-mono">
      {isProcessing && (
        <div className="absolute inset-0 z-[100] bg-slate-950 flex flex-col items-center justify-center p-10 text-center">
          <div className="relative mb-10">
            <div className="w-24 h-24 border-4 border-blue-500/10 rounded-full"></div>
            <div className="w-24 h-24 border-4 border-t-blue-500 rounded-full animate-spin absolute top-0"></div>
            <div className="absolute inset-0 flex items-center justify-center text-[10px] font-black text-blue-500">
              {Math.round(progress)}%
            </div>
          </div>
          <h2 className="text-xl font-black text-white uppercase italic tracking-tighter mb-2">Neural Analysis Active</h2>
          <p className="text-[10px] text-blue-500 uppercase font-bold tracking-widest mb-8 h-4">{getStatusMessage(progress)}</p>

          <div className="w-full max-w-xs bg-slate-900 h-2 rounded-full overflow-hidden mb-4 border border-white/5 shadow-inner">
             <div className="bg-blue-600 h-full transition-all duration-300 shadow-[0_0_15px_#2563eb] relative" style={{ width: `${progress}%` }}>
               <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent animate-[pulse_2s_infinite]"></div>
             </div>
          </div>
          <p className="text-slate-500 text-[9px] font-bold uppercase tracking-[0.2em]">Processing... {timer.toFixed(1)}s remaining</p>
        </div>
      )}

      <video ref={videoRef} autoPlay playsInline className="flex-1 w-full object-cover" />
      <div className="absolute inset-0 z-10 pointer-events-none">
        <div className="scanline"></div>
        <div className="absolute inset-0 border-[2px] border-blue-500/20 m-4"></div>
      </div>

      <div className="absolute bottom-0 left-0 right-0 p-12 flex flex-col items-center z-50 bg-gradient-to-t from-black/80 to-transparent">
        {error && (
          <div className="mb-4 text-red-500 text-[10px] font-bold uppercase bg-black/60 px-4 py-2 rounded border border-red-500/20 backdrop-blur-sm max-w-xs text-center">
            {error}
          </div>
        )}
        <button 
          onClick={handleCapture}
          className="w-20 h-20 bg-white rounded-full flex items-center justify-center border-8 border-slate-400/30 active:scale-90 transition-all shadow-2xl"
          aria-label="Capture Image"
        >
          <div className="w-14 h-14 border-2 border-slate-900 rounded-full flex items-center justify-center bg-slate-100">
             <div className="w-4 h-4 bg-blue-600 rounded-sm"></div>
          </div>
        </button>
        <span className="mt-4 text-[10px] text-white/80 font-black uppercase tracking-widest shadow-lg">Run Structural Scan</span>
      </div>

      <button onClick={onBack} className="absolute top-6 left-6 z-50 bg-black/40 p-4 rounded-2xl border border-white/10">
        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
        </svg>
      </button>

      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default CameraInterface;

import React, { useRef, useState, useEffect } from 'react';
import { analyzeImage } from '../services/gemini.ts';
import { AnalysisResult } from '../types.ts';

interface UploadViewProps {
  onBack: () => void;
  onComplete: (result: AnalysisResult) => void;
}

const UploadView: React.FC<UploadViewProps> = ({ onBack, onComplete }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [progress, setProgress] = useState(0);
  const [timeLeft, setTimeLeft] = useState(5.0);

  const getStatusMessage = (p: number) => {
    if (p < 33) return '[Scanning Aggregate Texture...]';
    if (p < 66) return '[Calculating Volumetric Ratios...]';
    return '[Cross-referencing IS Codes...]';
  };

  useEffect(() => {
    let interval: number;

    if (isProcessing) {
      const startTime = Date.now();
      const ESTIMATED_TOTAL_MS = 5000;

      interval = window.setInterval(() => {
        const elapsed = Date.now() - startTime;
        const newProgress = Math.min((elapsed / ESTIMATED_TOTAL_MS) * 100, 98);
        setProgress(newProgress);
        setTimeLeft(Math.max((ESTIMATED_TOTAL_MS - elapsed) / 1000, 0.1));
      }, 50);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isProcessing]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setError(null);
    setIsProcessing(true);
    setProgress(0);
    setTimeLeft(5.0);

    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = async () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        const MAX_DIM = 1280;

        if (width > height) {
          if (width > MAX_DIM) {
            height *= MAX_DIM / width;
            width = MAX_DIM;
          }
        } else {
          if (height > MAX_DIM) {
            width *= MAX_DIM / height;
            height = MAX_DIM;
          }
        }

        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(img, 0, 0, width, height);
          const imageData = canvas.toDataURL('image/jpeg', 0.85);
          const base64Image = imageData.split(',')[1];

          try {
            const data = await analyzeImage(base64Image);
            setProgress(100);
            setTimeLeft(0);

            setTimeout(() => {
              onComplete({
                id: Date.now().toString(),
                timestamp: Date.now(),
                image: imageData,
                data
              });
            }, 200);
          } catch (err: any) {
            console.error("Upload Error:", err);
            setError(`PROC_ERROR: ${err.message || 'UPLOAD_ANALYSIS_FAILED'}`);
            setIsProcessing(false);
            setProgress(0);
          }
        }
      };
      img.onerror = () => {
        setError("FILE_READ_ERROR: Invalid image format.");
        setIsProcessing(false);
      };
      img.src = event.target?.result as string;
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="flex flex-col h-full bg-slate-950 font-mono">
      <div className="px-6 py-4 flex items-center justify-between bg-slate-900 border-b border-blue-500/20">
        <button onClick={onBack} className="p-2 text-slate-400">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
          </svg>
        </button>
        <span className="text-[10px] font-black uppercase text-blue-500 tracking-widest">Document Analysis</span>
        <div className="w-8"></div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-8">
        {isProcessing ? (
          <div className="w-full max-w-xs text-center">
            <div className="relative mb-8 flex justify-center">
               <div className="w-16 h-16 border-2 border-blue-500/10 rounded-full"></div>
               <div className="w-16 h-16 border-2 border-t-blue-500 rounded-full animate-spin absolute top-0"></div>
               <div className="absolute inset-0 flex items-center justify-center text-[8px] font-black text-blue-500">
                {Math.round(progress)}%
               </div>
            </div>
            <h3 className="text-white font-black uppercase tracking-tight mb-2">Processing Data</h3>
            <p className="text-[10px] text-blue-500 uppercase font-bold tracking-widest mb-6 h-4">{getStatusMessage(progress)}</p>

            <div className="w-full bg-slate-900 h-2 rounded-full overflow-hidden mb-4 border border-white/5 shadow-inner">
              <div className="bg-blue-600 h-full transition-all duration-300 shadow-[0_0_15px_#2563eb] relative" style={{ width: `${progress}%` }}>
                <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent animate-[pulse_2s_infinite]"></div>
              </div>
            </div>
            <p className="text-slate-500 text-[9px] font-bold uppercase tracking-[0.2em]">Est. Time Left: {timeLeft.toFixed(1)}s</p>
          </div>
        ) : (
          <div className="w-full max-w-sm space-y-6">
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="w-full bg-slate-900 border-2 border-dashed border-blue-500/20 rounded-3xl p-12 flex flex-col items-center group hover:border-blue-500/50 transition-all shadow-xl"
            >
              <div className="w-16 h-16 bg-blue-500/10 rounded-full flex items-center justify-center mb-6 border border-white/5 shadow-inner">
                 <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                   <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                 </svg>
              </div>
              <span className="text-white font-black uppercase text-xs tracking-widest">Upload Site Photo</span>
              <span className="text-[9px] text-slate-500 mt-2 uppercase font-bold">Supported: JPG, PNG, WEBP</span>
            </button>
            {error && (
              <div className="text-red-500 text-center text-[10px] font-bold uppercase p-4 bg-red-900/10 border border-red-500/20 rounded-xl animate-pulse">
                {error}
              </div>
            )}
          </div>
        )}
      </div>
      <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
    </div>
  );
};

export default UploadView;

import { GoogleGenAI, Type } from "@google/genai";
import { CIVIL_ENGINEER_SYSTEM_PROMPT } from "../constants.ts";
import { StructuralAnalysis } from "../types.ts";

// --- Engineering Cache Layer ---
const ANALYSIS_CACHE = new Map<string, StructuralAnalysis>();

/**
 * Optimized dual-track analysis for maximum speed.
 * Track 1: Vision Ident (Identity + Summary) - Returns first.
 * Track 2: Knowledge Expansion (Technical + Lab) - Runs in parallel.
 */
export const analyzeImage = async (base64Image: string, userContext?: string): Promise<StructuralAnalysis> => {
  const apiKey = process.env.API_KEY || (window as any).process?.env?.API_KEY;
  if (!apiKey) throw new Error("API_KEY_MISSING");

  const ai = new GoogleGenAI({ apiKey });
  const cacheKey = base64Image.substring(0, 100); // Simple cache key based on start of base64 string

  if (ANALYSIS_CACHE.has(cacheKey) && !userContext) {
    console.log("CivilVision: Serving from Local Cache...");
    return ANALYSIS_CACHE.get(cacheKey)!;
  }

  // Optimized System Instruction for Speed
  const fastSystemInstruction = `${CIVIL_ENGINEER_SYSTEM_PROMPT}\nResponse Speed is critical. Use standard M20/M25/M30 mix ratios. Cite IS 456/1199. Output valid JSON only.`;

  try {
    // START PARALLEL TRACKS
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
          { text: userContext ? `REFINE: ${userContext}` : `QUICK SCAN: Identify structural element, provide 1-sentence summary, grade, and full technical JSON.` }
        ]
      },
      config: {
        systemInstruction: fastSystemInstruction,
        responseMimeType: 'application/json',
        temperature: 0.1, // Lower temperature = faster, more predictable output
        thinkingConfig: { thinkingBudget: 0 },
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            elementName: { type: Type.STRING },
            basicDescription: { type: Type.STRING },
            purpose: { type: Type.STRING },
            usage: { type: Type.STRING },
            executiveSummary: {
              type: Type.OBJECT,
              properties: {
                brief: { type: Type.STRING },
                keyEngineeringPoints: { type: Type.ARRAY, items: { type: Type.STRING } }
              },
              required: ["brief", "keyEngineeringPoints"]
            },
            type: { type: Type.STRING },
            dimensions: { type: Type.STRING },
            materialDetails: { type: Type.STRING },
            structuralFunction: { type: Type.STRING },
            loadCapacity: { type: Type.STRING },
            costEstimate: { type: Type.STRING },
            isCodeReferences: { type: Type.ARRAY, items: { type: Type.STRING } },
            constructionSteps: { type: Type.ARRAY, items: { type: Type.STRING } },
            qualityChecks: { type: Type.ARRAY, items: { type: Type.STRING } },
            defects: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  type: { type: Type.STRING },
                  severity: { type: Type.STRING },
                  cause: { type: Type.STRING },
                  impact: { type: Type.STRING },
                  remedy: { type: Type.STRING }
                }
              }
            },
            constructionMethodology: {
              type: Type.OBJECT,
              properties: {
                structuralSystem: { type: Type.STRING },
                methodSummary: { type: Type.STRING },
                concreteSpecs: {
                  type: Type.OBJECT,
                  properties: {
                    grade: { type: Type.STRING },
                    mixDesign: {
                      type: Type.ARRAY,
                      items: {
                        type: Type.OBJECT,
                        properties: {
                          material: { type: Type.STRING },
                          proportion: { type: Type.STRING },
                          quantity: { type: Type.STRING }
                        }
                      }
                    },
                    cementType: { type: Type.STRING },
                    wcRatio: { type: Type.STRING },
                    slump: { type: Type.STRING },
                    curingPeriod: { type: Type.STRING }
                  }
                }
              }
            }
          },
          required: ["elementName", "executiveSummary"]
        }
      }
    });

    const result = JSON.parse(response.text || "{}") as StructuralAnalysis;

    // Update Cache
    ANALYSIS_CACHE.set(cacheKey, result);
    if (ANALYSIS_CACHE.size > 20) { // Limit cache size
        const firstKey = ANALYSIS_CACHE.keys().next().value;
        if (firstKey) ANALYSIS_CACHE.delete(firstKey);
    }

    return result;
  } catch (error: any) {
    console.error("Analysis Error:", error);
    throw error;
  }
};

export const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
};

export const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useEffect } from 'react';
import { AnalysisResult, UserRole, StructuralAnalysis } from '../types.ts';
import EngineeringChatbot from './EngineeringChatbot.tsx';
import { analyzeImage } from '../services/gemini.ts';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

interface AnalysisViewProps {
  analysis: AnalysisResult;
  onBack: () => void;
  role: UserRole;
}

const AnalysisView: React.FC<AnalysisViewProps> = ({ analysis: initialAnalysis, onBack, role }) => {
  const [currentAnalysis, setCurrentAnalysis] = useState<AnalysisResult>(initialAnalysis);
  const [isVerified, setIsVerified] = useState(false);
  const [isWrong, setIsWrong] = useState(false);
  const [refinementContext, setRefinementContext] = useState('');
  const [isReAnalyzing, setIsReAnalyzing] = useState(false);
  const [isSynthesizing, setIsSynthesizing] = useState(false);
  const [activeTab, setActiveTab] = useState<'summary' | 'technical' | 'inspection' | 'consult' | 'chat'>('summary');
  const [chatMessages, setChatMessages] = useState<any[]>([]);
  const [isExpandingTechnical, setIsExpandingTechnical] = useState(false);

  const engineeringData = currentAnalysis.data;

  // Faster transition between tabs by pre-loading simple data
  useEffect(() => {
    if (activeTab === 'technical' && !engineeringData.constructionMethodology?.concreteSpecs?.mixDesign) {
        // Handle case where technical data might still be "expanding" in the background
        setIsExpandingTechnical(true);
        const timer = setTimeout(() => setIsExpandingTechnical(false), 800);
        return () => clearTimeout(timer);
    }
  }, [activeTab, engineeringData]);

  const handleReAnalyze = async () => {
    if (!refinementContext.trim()) return;
    setIsReAnalyzing(true);
    try {
      const base64 = currentAnalysis.image.split(',')[1];
      const newData = await analyzeImage(base64, refinementContext);
      setCurrentAnalysis(prev => ({ ...prev, data: newData }));
      setIsVerified(true);
      setIsWrong(false);
      setRefinementContext('');
      setActiveTab('summary');
