        </button>
        <div className="text-center">
            <div className="text-[9px] mono text-blue-500 uppercase font-black tracking-[0.2em]">Structural Log</div>
            <div className="text-xs font-black uppercase truncate max-w-[180px] tracking-tight">{engineeringData.elementName}</div>
        </div>
