import { GoogleGenAI, Type } from "@google/genai";
import { CIVIL_ENGINEER_SYSTEM_PROMPT } from "../constants.ts";
import { StructuralAnalysis } from "../types.ts";

// --- Global Engineering Cache ---
const ANALYSIS_CACHE = new Map<string, StructuralAnalysis>();

/**
 * Optimized backend pipeline for Hackathon speed.
 * This function triggers two parallel API calls to satisfy the 'Parallel Execution' requirement:
 * 1. Identification Track (Vision-Heavy): Identifies the element and creates a summary.
 * 2. Technical Track (Knowledge-Heavy): Fetches IS Codes, Mix Designs, and Methodology.
 */
export const analyzeImage = async (base64Image: string, userContext?: string): Promise<StructuralAnalysis> => {
  const apiKey = process.env.API_KEY || (window as any).process?.env?.API_KEY;
  if (!apiKey) throw new Error("API_KEY_MISSING");

  const cacheKey = base64Image.substring(0, 150) + (userContext || '');
  if (ANALYSIS_CACHE.has(cacheKey)) {
    console.log("CivilVision: Cache Hit - Returning Pre-processed Data");
    return ANALYSIS_CACHE.get(cacheKey)!;
  }

  const ai = new GoogleGenAI({ apiKey });

  // Track 1: Identification & Visual Assessment (Fast Vision Model)
  const identPromise = ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
        { text: `QUICK IDENT: Identify this civil engineering element/apparatus. 
                 Provide elementName, basicDescription, type, dimensions, and executiveSummary. 
                 Context: ${userContext || 'None'}` }
      ]
    },
    config: {
      systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT,
      responseMimeType: 'application/json',
      thinkingConfig: { thinkingBudget: 0 },
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          elementName: { type: Type.STRING },
          basicDescription: { type: Type.STRING },
          type: { type: Type.STRING },
          dimensions: { type: Type.STRING },
          executiveSummary: {
            type: Type.OBJECT,
            properties: {
              brief: { type: Type.STRING },
              keyEngineeringPoints: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ["brief", "keyEngineeringPoints"]
          }
        },
        required: ["elementName", "executiveSummary"]
      }
    }
  });

  // Track 2: Technical Specs & IS Code Verification (Knowledge Base)
  // We send the image too so it can cross-reference visible rebar/texture with codes.
  const techPromise = ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
        { text: `TECH SPEC: Provide concrete mix design (IS 456), reinforcement specs, quality checks, and defects based on visual cues. 
                 Context: ${userContext || 'None'}` }
      ]
    },
    config: {
      systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT,
      responseMimeType: 'application/json',
      thinkingConfig: { thinkingBudget: 0 },
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          materialDetails: { type: Type.STRING },
          loadCapacity: { type: Type.STRING },
          isCodeReferences: { type: Type.ARRAY, items: { type: Type.STRING } },
          constructionSteps: { type: Type.ARRAY, items: { type: Type.STRING } },
          qualityChecks: { type: Type.ARRAY, items: { type: Type.STRING } },
          defects: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                type: { type: Type.STRING },
                severity: { type: Type.STRING },
                cause: { type: Type.STRING },
                impact: { type: Type.STRING },
                remedy: { type: Type.STRING }
              }
            }
          },
          constructionMethodology: {
            type: Type.OBJECT,
            properties: {
              structuralSystem: { type: Type.STRING },
              concreteSpecs: {
                type: Type.OBJECT,
                properties: {
                  grade: { type: Type.STRING },
                  mixDesign: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: { material: { type: Type.STRING }, proportion: { type: Type.STRING }, quantity: { type: Type.STRING } }
                    }
                  },
                  wcRatio: { type: Type.STRING }
                }
              }
            }
          }
        }
      }
    }
  });

  try {
    // Parallel Execution Triggered Here
    const [identRes, techRes] = await Promise.all([identPromise, techPromise]);

    // Merge results to satisfy the UI's StructuralAnalysis type
    const identData = JSON.parse(identRes.text || "{}");
    const techData = JSON.parse(techRes.text || "{}");

    const mergedResult: StructuralAnalysis = {
      ...identData,
      ...techData,
      // Fallbacks for missing fields
      purpose: identData.purpose || techData.purpose || "Structural Support",
      usage: identData.usage || techData.usage || "Construction Field Work",
      costEstimate: techData.costEstimate || "Calculating based on market rates...",
      structuralFunction: techData.structuralFunction || identData.basicDescription
    };

    ANALYSIS_CACHE.set(cacheKey, mergedResult);
    return mergedResult;
  } catch (error: any) {
    console.error("Parallel Analysis Pipeline Failed:", error);
    // If one fails, try a fallback single-track analysis or throw
    throw new Error("ENGINEERING_PIPELINE_ERROR: JSON truncation or connection loss.");
  }
};

export const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
};

export const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

