import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from '@google/genai';
import { StructuralAnalysis } from '../types.ts';
import { CIVIL_ENGINEER_SYSTEM_PROMPT } from '../constants.ts';

interface Message {
  role: 'user' | 'model';
  text: string;
  timestamp: string;
}

interface EngineeringChatbotProps {
  context: StructuralAnalysis;
  onMessagesUpdate?: (messages: Message[]) => void;
}

const EngineeringChatbot: React.FC<EngineeringChatbotProps> = ({ context, onMessagesUpdate }) => {
  const [messages, setMessages] = useState<Message[]>([
    { 
      role: 'model', 
      text: `Expert Consultant Online. I've scanned the **${context.elementName}**. How can I help?\n\n- Ask for **details** for a full report.\n- Ask about **defects** for remediation.`,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
    if (onMessagesUpdate) {
        onMessagesUpdate(messages);
    }
  }, [messages, isTyping, onMessagesUpdate]);

  const handleSend = async (customInput?: string) => {
    const userMessage = (customInput || input).trim();
    if (!userMessage || isTyping) return;

    const time = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage, timestamp: time }]);
    setIsTyping(true);

    try {
      const apiKey = process.env.API_KEY || (window as any).process?.env?.API_KEY;
      const ai = new GoogleGenAI({ apiKey: apiKey || '' });

      const chat = ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
          thinkingConfig: { thinkingBudget: 0 },
          systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT + `

          STRICT OPERATIONAL CONTEXT:
          Element: ${context.elementName}
          Grade: ${context.constructionMethodology?.concreteSpecs?.grade || 'N/A'}
          Dimensions: ${context.dimensions}
          Methodology: ${JSON.stringify(context.constructionMethodology)}
          Defects: ${JSON.stringify(context.defects)}

          CHAT RESPONSE RULES (CRITICAL):
          1. DIRECT ANSWERS: If the user asks a direct question (e.g., "What grade?", "Dimensions?"), answer in 10 words or less.
          2. NO UNSOLICITED DETAIL: Do NOT provide mix designs, IS Code tables, or long procedures unless the user explicitly uses keywords like "details", "specifications", "full report", "how to", or "explain".
          3. TAB AWARENESS: Information already in the SUMMARY or TECHNICAL tabs should not be repeated unless the user asks for a recap or specific clarification.
          4. NO LECTURING: Avoid engineering "context" or advice on aggregate quality unless the user specifically asks about "quality", "defects", or "remedy".
          5. FORMATTING: Use **bold** for numbers/codes. Use bullet points ONLY if requested for "steps" or "details".`,
        }
      });

      const response = await chat.sendMessage({ message: userMessage });
      const modelTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      setMessages(prev => [...prev, { 
        role: 'model', 
        text: response.text || "Consultant unavailable. System error.",
        timestamp: modelTime
      }]);
    } catch (err) {
      console.error("Chat Error:", err);
      setMessages(prev => [...prev, { 
        role: 'model', 
        text: "ERROR: Secure Link interrupted.",
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  const toggleVoiceInput = () => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitRecognition;
    if (!SpeechRecognition) {
      alert("Voice recognition not supported.");
      return;
    }

    if (isListening) {
      setIsListening(false);
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.interimResults = false;
    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onresult = (event: any) => setInput(event.results[0][0].transcript);
    recognition.start();
  };

  const formatText = (text: string) => {
    return text.split('\n').map((line, i) => {
      let processed = line.trim();
      if (!processed) return <div key={i} className="h-1" />;

      if (processed.startsWith('### ')) {
        return (
          <h3 key={i} className="text-[11px] font-black text-white uppercase tracking-tight border-b border-slate-700 pb-1 mb-2 mt-2">
            {processed.replace('### ', '')}
          </h3>
        );
      }

      const renderSpans = (str: string) => {
        const parts = str.split(/(\*\*.*?\*\*|`.*?`)/g);
        return parts.map((part, index) => {
          if (part.startsWith('**') && part.endsWith('**')) {
            return <strong key={index} className="text-white font-black">{part.slice(2, -2)}</strong>;
          }
          if (part.startsWith('`') && part.endsWith('`')) {
            return <code key={index} className="bg-blue-500/20 text-blue-400 px-1 rounded font-mono text-[9px] mx-0.5">{part.slice(1, -1)}</code>;
          }
          return part;
        });
      };

      if (processed.startsWith('- ') || processed.startsWith('* ')) {
        return (
          <div key={i} className="pl-4 relative mb-1 text-[11px]">
            <span className="absolute left-0 top-1.5 w-1 h-1 bg-orange-500 rounded-sm" />
            <span className="text-slate-200">{renderSpans(processed.substring(2))}</span>
          </div>
        );
      }

      return (
        <p key={i} className="mb-2 text-slate-300 leading-snug text-[11px]">
          {renderSpans(processed)}
        </p>
      );
    });
  };

  return (
    <div className="flex flex-col h-full bg-slate-950 font-mono relative">
      <div 
        ref={scrollRef} 
        className="flex-1 overflow-y-auto p-4 space-y-4 scrollbar-hide pb-24"
      >
        {messages.map((m, idx) => (
          <div key={idx} className={`flex w-full ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`flex flex-col max-w-[90%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
              <div className={`p-3 text-[11px] font-medium shadow-xl relative ${
                m.role === 'user' 
                ? 'bg-blue-600 text-white rounded-2xl rounded-br-none' 
                : 'bg-slate-900 border border-slate-800 rounded-2xl rounded-bl-none'
              }`}>
                {formatText(m.text)}
                <div className={`mt-1 text-[7px] font-black uppercase opacity-40 ${m.role === 'user' ? 'text-right' : 'text-left'}`}>
                  {m.timestamp}
                </div>
              </div>
            </div>
          </div>
        ))}

        {isTyping && (
          <div className="flex justify-start">
            <div className="bg-slate-900 text-blue-500 px-3 py-2 rounded-xl border border-slate-800 flex space-x-1">
              <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce"></div>
              <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce [animation-delay:0.2s]"></div>
              <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce [animation-delay:0.4s]"></div>
            </div>
          </div>
        )}
      </div>

      <div className="absolute bottom-4 left-4 right-4">
        <div className="bg-slate-900 border border-blue-500/30 rounded-2xl px-3 py-1 flex items-center shadow-2xl">
          <button onClick={toggleVoiceInput} className={`p-2 rounded-full transition-colors ${isListening ? 'bg-red-500 text-white' : 'text-slate-500 hover:text-blue-500'}`}>
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
            </svg>
          </button>
          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSend()}
            placeholder={isListening ? "Listening..." : "Ask a direct question..."}
            className="flex-1 bg-transparent border-none outline-none text-xs py-2 px-2 text-white placeholder:text-slate-600"
          />
          <button onClick={() => handleSend()} disabled={!input.trim() || isTyping} className="p-2 text-blue-500 hover:text-white disabled:opacity-30">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 rotate-90" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
};

export default EngineeringChatbot;

import React, { useRef, useState, useEffect } from 'react';
import heic2any from 'heic2any';
import { analyzeImage } from '../services/gemini.ts';
import { AnalysisResult } from '../types.ts';

interface UploadViewProps {
  onBack: () => void;
  onComplete: (result: AnalysisResult) => void;
}

const UploadView: React.FC<UploadViewProps> = ({ onBack, onComplete }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isConverting, setIsConverting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [progress, setProgress] = useState(0);
  const [timeLeft, setTimeLeft] = useState(5.0);

  const getStatusMessage = (p: number) => {
    if (isConverting) return '[Converting High-Efficiency Format...]';
    if (p < 33) return '[Scanning Aggregate Texture...]';
    if (p < 66) return '[Calculating Volumetric Ratios...]';
    return '[Cross-referencing IS Codes...]';
  };

  useEffect(() => {
    let interval: number;

    if (isProcessing && !isConverting) {
      const startTime = Date.now();
      const ESTIMATED_TOTAL_MS = 5000;

      interval = window.setInterval(() => {
        const elapsed = Date.now() - startTime;
        const newProgress = Math.min((elapsed / ESTIMATED_TOTAL_MS) * 100, 98);
        setProgress(newProgress);
        setTimeLeft(Math.max((ESTIMATED_TOTAL_MS - elapsed) / 1000, 0.1));
      }, 50);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isProcessing, isConverting]);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    let file = e.target.files?.[0];
    if (!file) return;

    setError(null);
    setIsProcessing(true);
    setProgress(0);
    setTimeLeft(5.0);

    const fileName = file.name.toLowerCase();
    const isHeic = fileName.endsWith('.heic') || fileName.endsWith('.heif');

    try {
      if (isHeic) {
        setIsConverting(true);
        const conversionResult = await heic2any({
          blob: file,
          toType: 'image/jpeg',
          quality: 0.9
        });
        // result could be a blob or an array of blobs
        const blob = Array.isArray(conversionResult) ? conversionResult[0] : conversionResult;
        file = new File([blob], fileName.replace(/\.(heic|heif)$/, '.jpg'), { type: 'image/jpeg' });
        setIsConverting(false);
      }

      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onload = async () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          const MAX_DIM = 1280;

          if (width > height) {
            if (width > MAX_DIM) {
              height *= MAX_DIM / width;
              width = MAX_DIM;
            }
          } else {
            if (height > MAX_DIM) {
              width *= MAX_DIM / height;
              height = MAX_DIM;
            }
          }

          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (ctx) {
            ctx.drawImage(img, 0, 0, width, height);
            const imageData = canvas.toDataURL('image/jpeg', 0.85);
            const base64Image = imageData.split(',')[1];

            try {
              const data = await analyzeImage(base64Image);
              setProgress(100);
              setTimeLeft(0);

              setTimeout(() => {
                onComplete({
                  id: Date.now().toString(),
                  timestamp: Date.now(),
                  image: imageData,
                  data
                });
              }, 200);
            } catch (err: any) {
              console.error("Upload Error:", err);
              setError(`PROC_ERROR: ${err.message || 'UPLOAD_ANALYSIS_FAILED'}`);
              setIsProcessing(false);
              setProgress(0);
            }
          }
        };
        img.onerror = () => {
          setError("FILE_READ_ERROR: Invalid image format.");
          setIsProcessing(false);
        };
        img.src = event.target?.result as string;
      };
      reader.readAsDataURL(file);
    } catch (err: any) {
      console.error("HEIC Conversion Error:", err);
      setError("Could not process HEIC file. Please try uploading a JPG or taking a live photo.");
      setIsProcessing(false);
      setIsConverting(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-950 font-mono">
      <div className="px-6 py-4 flex items-center justify-between bg-slate-900 border-b border-blue-500/20">
        <button onClick={onBack} className="p-2 text-slate-400">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
          </svg>
        </button>
        <span className="text-[10px] font-black uppercase text-blue-500 tracking-widest">Document Analysis</span>
        <div className="w-8"></div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-8">
        {isProcessing ? (
          <div className="w-full max-w-xs text-center">
            <div className="relative mb-8 flex justify-center">
               <div className="w-16 h-16 border-2 border-blue-500/10 rounded-full"></div>
               <div className="w-16 h-16 border-2 border-t-blue-500 rounded-full animate-spin absolute top-0"></div>
               <div className="absolute inset-0 flex items-center justify-center text-[8px] font-black text-blue-500">
                {Math.round(progress)}%
               </div>
            </div>
            <h3 className="text-white font-black uppercase tracking-tight mb-2">
              {isConverting ? 'Initializing Vision' : 'Processing Data'}
            </h3>
            <p className="text-[10px] text-blue-500 uppercase font-bold tracking-widest mb-6 h-4">{getStatusMessage(progress)}</p>

            <div className="w-full bg-slate-900 h-2 rounded-full overflow-hidden mb-4 border border-white/5 shadow-inner">
              <div className="bg-blue-600 h-full transition-all duration-300 shadow-[0_0_15px_#2563eb] relative" style={{ width: `${progress}%` }}>
                <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent animate-[pulse_2s_infinite]"></div>
              </div>
            </div>
            <p className="text-slate-500 text-[9px] font-bold uppercase tracking-[0.2em]">Est. Time Left: {isConverting ? '...' : timeLeft.toFixed(1) + 's'}</p>
          </div>
        ) : (
          <div className="w-full max-w-sm space-y-6">
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="w-full bg-slate-900 border-2 border-dashed border-blue-500/20 rounded-3xl p-12 flex flex-col items-center group hover:border-blue-500/50 transition-all shadow-xl"
            >
              <div className="w-16 h-16 bg-blue-500/10 rounded-full flex items-center justify-center mb-6 border border-white/5 shadow-inner">
                 <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                   <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                 </svg>
              </div>
              <span className="text-white font-black uppercase text-xs tracking-widest">Upload Site Photo</span>
              <div className="flex items-center space-x-2 mt-2">
                <span className="text-[9px] text-slate-500 uppercase font-bold">JPG, PNG</span>
                <span className="text-[9px] bg-blue-500/10 text-blue-400 px-1.5 py-0.5 rounded border border-blue-500/20 font-black">HEIC SUPPORTED</span>
              </div>
              <span className="text-[8px] text-slate-600 mt-2 italic">(iPhone high-efficiency photos auto-converted)</span>
            </button>
            {error && (
              <div className="text-red-500 text-center text-[10px] font-bold uppercase p-4 bg-red-900/10 border border-red-500/20 rounded-xl animate-pulse">
                {error}
              </div>
            )}
          </div>
        )}
      </div>
      <input 
        type="file" 
        ref={fileInputRef} 
        className="hidden" 
        accept="image/jpeg,image/png,image/webp,.heic,.heif" 
        onChange={handleFileUpload} 
      />
    </div>
  );
};

