import { GoogleGenAI, Type } from "@google/genai";
import { CIVIL_ENGINEER_SYSTEM_PROMPT } from "../constants.ts";
import { StructuralAnalysis } from "../types.ts";

// --- Local Correction DB (Simulated) ---
const CORRECTION_DB_KEY = 'civilvision_correction_memory';

/**
 * Generates a unique SHA-256 fingerprint for the image.
 */
export const getImageHash = async (base64: string): Promise<string> => {
  const msgUint8 = new TextEncoder().encode(base64);
  const hashBuffer = await crypto.subtle.digest('SHA-256', msgUint8);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
};

/**
 * Persists a user-verified correction to memory.
 */
export const saveCorrection = (hash: string, data: StructuralAnalysis) => {
  const db = JSON.parse(localStorage.getItem(CORRECTION_DB_KEY) || '{}');
  db[hash] = { data, timestamp: Date.now() };
  localStorage.setItem(CORRECTION_DB_KEY, JSON.stringify(db));

  // Log for retraining queue
  const queue = JSON.parse(localStorage.getItem('retraining_queue') || '[]');
  queue.push({ hash, labels: data, timestamp: Date.now() });
  localStorage.setItem('retraining_queue', JSON.stringify(queue));
};

/**
 * Optimized backend pipeline with Correction Memory.
 */
export const analyzeImage = async (base64Image: string, userContext?: string): Promise<StructuralAnalysis> => {
  const apiKey = process.env.API_KEY || (window as any).process?.env?.API_KEY;
  if (!apiKey) throw new Error("API_KEY_MISSING");

  const hash = await getImageHash(base64Image);

  // 1. Pre-Analysis Check: Check Correction Memory
  if (!userContext) {
    const db = JSON.parse(localStorage.getItem(CORRECTION_DB_KEY) || '{}');
    if (db[hash]) {
      console.log("CivilVision: Correction Memory Triggered - Applying Verified Data");
      return { ...db[hash].data, isCorrection: true, confidenceScore: 100 };
    }
  }

  const ai = new GoogleGenAI({ apiKey });

  // Identification & Confidence Scoring
  const identPromise = ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
        { text: `QUICK IDENT: Identify element. Include confidenceScore (0-100). Context: ${userContext || 'None'}` }
      ]
    },
    config: {
      systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT,
      responseMimeType: 'application/json',
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          elementName: { type: Type.STRING },
          confidenceScore: { type: Type.NUMBER },
          basicDescription: { type: Type.STRING },
          executiveSummary: {
            type: Type.OBJECT,
            properties: {
              brief: { type: Type.STRING },
              keyEngineeringPoints: { type: Type.ARRAY, items: { type: Type.STRING } }
            }
          }
        },
        required: ["elementName", "confidenceScore"]
      }
    }
  });

  const techPromise = ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
        { text: `TECH SPEC: Mix design, codes, methodology. Context: ${userContext || 'None'}` }
      ]
    },
    config: {
      systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT,
      responseMimeType: 'application/json',
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          isCodeReferences: { type: Type.ARRAY, items: { type: Type.STRING } },
          qualityChecks: { type: Type.ARRAY, items: { type: Type.STRING } },
          constructionMethodology: {
            type: Type.OBJECT,
            properties: {
              concreteSpecs: {
                type: Type.OBJECT,
                properties: {
                  grade: { type: Type.STRING },
                  wcRatio: { type: Type.STRING }
                }
              }
            }
          }
        }
      }
    }
  });

  try {
    const [identRes, techRes] = await Promise.all([identPromise, techPromise]);
    const identData = JSON.parse(identRes.text || "{}");
    const techData = JSON.parse(techRes.text || "{}");

    return {
      ...identData,
      ...techData,
      isCorrection: false,
      dimensions: identData.dimensions || "Field Verified Needed",
      defects: [] // Initialize for safety
    };
  } catch (error: any) {
    console.error("Pipeline Error:", error);
    throw new Error("ENGINEERING_LINK_FAILED");
  }
};

export const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
};

export const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useEffect } from 'react';
import { AnalysisResult, UserRole, StructuralAnalysis } from '../types.ts';
import EngineeringChatbot from './EngineeringChatbot.tsx';
import { analyzeImage, saveCorrection } from '../services/gemini.ts';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

interface AnalysisViewProps {
  analysis: AnalysisResult;
  onBack: () => void;
  role: UserRole;
}

const AnalysisView: React.FC<AnalysisViewProps> = ({ analysis: initialAnalysis, onBack, role }) => {
  const [currentAnalysis, setCurrentAnalysis] = useState<AnalysisResult>(initialAnalysis);
  const [isVerified, setIsVerified] = useState(false);
  const [isWrong, setIsWrong] = useState(false);
  const [refinementContext, setRefinementContext] = useState('');
  const [isReAnalyzing, setIsReAnalyzing] = useState(false);
  const [isSynthesizing, setIsSynthesizing] = useState(false);
  const [activeTab, setActiveTab] = useState<'summary' | 'technical' | 'inspection' | 'consult' | 'chat'>('summary');
  const [chatMessages, setChatMessages] = useState<any[]>([]);
  const [isLoadingDeepData, setIsLoadingDeepData] = useState(false);

  const engineeringData = currentAnalysis.data;
  const isCorrection = engineeringData.isCorrection;
  const confidenceScore = engineeringData.confidenceScore || 0;

  useEffect(() => {
    if (activeTab === 'technical' && !engineeringData.constructionMethodology) {
      setIsLoadingDeepData(true);
      const timer = setTimeout(() => setIsLoadingDeepData(false), 600);
      return () => clearTimeout(timer);
    }
  }, [activeTab, engineeringData]);

  const handleReAnalyze = async () => {
    if (!refinementContext.trim()) return;
    setIsReAnalyzing(true);
    try {
      const base64 = currentAnalysis.image.split(',')[1];
      const newData = await analyzeImage(base64, refinementContext);

      // Store original data before overwriting if user confirms it's a correction
      const updatedData = { ...newData, isCorrection: true, originalData: engineeringData };

      // Update local storage for Correction Memory
      saveCorrection(currentAnalysis.imageHash, updatedData);

      setCurrentAnalysis(prev => ({ ...prev, data: updatedData }));
      setIsVerified(true);
      setIsWrong(false);
      setRefinementContext('');
      setActiveTab('summary');
    } catch (err) {
      console.error("Re-analysis failed:", err);
    } finally {
      setIsReAnalyzing(false);
    }
  };

  const handleManualVerify = () => {
    if (confidenceScore < 70) {
      // Prompt user specifically if confidence is low
      const ok = confirm(`AI confidence is low (${confidenceScore}%). Are you sure these parameters are correct?`);
      if (!ok) {
        setIsWrong(true);
        return;
      }
    }
    setIsVerified(true);
  };

  const generateReport = async () => {
    setIsSynthesizing(true);
    try {
      const doc = new jsPDF();
      doc.text("CivilVision AI Report", 20, 20);
      doc.text(`Element: ${engineeringData.elementName}`, 20, 30);
      doc.text(`Confidence: ${confidenceScore}%`, 20, 40);
      if (isCorrection) doc.text("STATUS: USER VERIFIED CORRECTION", 20, 50);
      doc.save(`Report_${currentAnalysis.id}.pdf`);
    } finally {
      setIsSynthesizing(false);
    }
  };

  if (!isVerified) {
    return (
      <div className="flex flex-col h-full bg-theme-main font-mono">
        <div className="px-6 py-4 flex items-center justify-between border-b border-theme bg-theme-card/50 backdrop-blur-md">
