import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from '@google/genai';
import { StructuralAnalysis } from '../types.ts';
import { CIVIL_ENGINEER_SYSTEM_PROMPT } from '../constants.ts';

interface Message {
  role: 'user' | 'model';
  text: string;
  timestamp: string;
}

interface EngineeringChatbotProps {
  context: StructuralAnalysis;
  onMessagesUpdate?: (messages: Message[]) => void;
}

const EngineeringChatbot: React.FC<EngineeringChatbotProps> = ({ context, onMessagesUpdate }) => {
  const [messages, setMessages] = useState<Message[]>([
    { 
      role: 'model', 
      text: context.isCorrection 
        ? `I have applied the **Manual Override** for this element. How can I assist with this verified data?`
        : `Expert Consultant Online. I've scanned the **${context.elementName}**. How can I help?`,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
    if (onMessagesUpdate) {
        onMessagesUpdate(messages);
    }
  }, [messages, isTyping, onMessagesUpdate]);

  const handleSend = async (customInput?: string) => {
    const userMessage = (customInput || input).trim();
    if (!userMessage || isTyping) return;

    const time = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage, timestamp: time }]);
    setIsTyping(true);

    try {
      const apiKey = process.env.API_KEY || (window as any).process?.env?.API_KEY;
      const ai = new GoogleGenAI({ apiKey: apiKey || '' });

      const chat = ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
          thinkingConfig: { thinkingBudget: 0 },
          systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT + `

          STRICT OPERATIONAL CONTEXT:
          Element: ${context.elementName}
          Grade: ${context.constructionMethodology?.concreteSpecs?.grade || 'N/A'}
          Status: ${context.isCorrection ? 'USER_VERIFIED_CORRECTION' : 'AI_ESTIMATED'}
          Original AI data: ${JSON.stringify(context.originalData || {})}

          CHAT RESPONSE RULES (CRITICAL):
          1. CORRECTION AWARENESS: If the user asks "Why M20?" or similar, and Status is USER_VERIFIED_CORRECTION, explain: "I previously identified this as [Original Grade], but it was manually corrected based on site-specific mix data."
          2. DIRECT ANSWERS: If user asks direct question, answer in 10 words or less.
          3. NO LECTURING: Avoid engineering context unless specifically asked about "quality" or "defects".`,
        }
      });

      const response = await chat.sendMessage({ message: userMessage });
      setMessages(prev => [...prev, { 
        role: 'model', 
        text: response.text || "Secure Link error.",
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      }]);
    } catch (err) {
      console.error("Chat Error:", err);
      setMessages(prev => [...prev, { 
        role: 'model', 
        text: "ERROR: Secure Link interrupted.",
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  const toggleVoiceInput = () => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitRecognition;
    if (!SpeechRecognition) return;
    const recognition = new SpeechRecognition();
    recognition.onresult = (event: any) => setInput(event.results[0][0].transcript);
    recognition.start();
  };

  return (
    <div className="flex flex-col h-full bg-slate-950 font-mono relative">
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 pb-24 scrollbar-hide">
        {messages.map((m, idx) => (
          <div key={idx} className={`flex w-full ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`p-3 text-[11px] font-medium shadow-xl rounded-2xl ${m.role === 'user' ? 'bg-blue-600 text-white rounded-br-none' : 'bg-slate-900 border border-slate-800 text-slate-300 rounded-bl-none'}`}>
              {m.text}
              <div className="mt-1 text-[7px] font-black uppercase opacity-40">{m.timestamp}</div>
            </div>
          </div>
        ))}
        {isTyping && <div className="text-blue-500 text-[10px] animate-pulse">Neural engine processing...</div>}
      </div>
      <div className="p-4 bg-slate-950 border-t border-slate-900">
        <div className="bg-slate-900 border border-blue-500/30 rounded-2xl px-3 py-1 flex items-center">
          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Query structural history..."
            className="flex-1 bg-transparent border-none outline-none text-xs py-2 px-2 text-white"
          />
          <button onClick={() => handleSend()} className="p-2 text-blue-500">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 rotate-90" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
};

