export default AnalysisView;

import React, { useState, useEffect, useRef } from 'react';
import { AnalysisResult, UserRole, StructuralAnalysis } from '../types.ts';
import EngineeringChatbot from './EngineeringChatbot.tsx';
import { analyzeImage, saveCorrection } from '../services/gemini.ts';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

interface AnalysisViewProps {
  analysis: AnalysisResult;
  onBack: () => void;
  role: UserRole;
}

const AnalysisView: React.FC<AnalysisViewProps> = ({ analysis: initialAnalysis, onBack }) => {
  const [currentAnalysis, setCurrentAnalysis] = useState<AnalysisResult>(initialAnalysis);
  const [isVerified, setIsVerified] = useState(false);
  const [isWrong, setIsWrong] = useState(false);
  const [refinementContext, setRefinementContext] = useState('');
  const [isReAnalyzing, setIsReAnalyzing] = useState(false);
  const [isSynthesizing, setIsSynthesizing] = useState(false);
  const [activeTab, setActiveTab] = useState<'summary' | 'technical' | 'inspection' | 'consult' | 'chat'>('summary');
  const [isLoadingDeepData, setIsLoadingDeepData] = useState(true);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const engineeringData = currentAnalysis.data;
  const isCorrection = engineeringData.isCorrection;
  const confidenceScore = engineeringData.confidenceScore || 0;

  useEffect(() => {
    setActiveTab('summary');
    setIsVerified(false);
    setIsWrong(false);
    setIsLoadingDeepData(true);

    const checkData = () => {
      const hasSummary = !!engineeringData.executiveSummary?.brief;
      const hasTech = !!engineeringData.constructionMethodology || !!engineeringData.isCodeReferences;
      if (hasSummary && hasTech) {
        setIsLoadingDeepData(false);
      } else {
        setTimeout(checkData, 500);
      }
    };
    checkData();
  }, [initialAnalysis.id, engineeringData]);

  useEffect(() => {
    if (scrollContainerRef.current) {
      scrollContainerRef.current.scrollTop = 0;
    }
  }, [activeTab]);

  const handleReAnalyze = async () => {
    if (!refinementContext.trim()) return;
    setIsReAnalyzing(true);
    try {
      const base64 = currentAnalysis.image.split(',')[1];
      const newData = await analyzeImage(base64, refinementContext);
      const updatedData: StructuralAnalysis = { ...newData, isCorrection: true, originalData: engineeringData };
      saveCorrection(currentAnalysis.imageHash, updatedData);
      setCurrentAnalysis(prev => ({ ...prev, data: updatedData }));
      setIsVerified(true);
      setIsWrong(false);
      setRefinementContext('');
      setActiveTab('summary');
    } catch (err) {
      console.error("Re-analysis failed:", err);
    } finally {
      setIsReAnalyzing(false);
    }
  };

  const generateReport = async () => {
    setIsSynthesizing(true);
    try {
      const doc = new jsPDF();
      doc.setFontSize(18);
      doc.text("CivilVision AI Engineering Report", 20, 20);
      doc.setFontSize(12);
      doc.text(`Project ID: ${currentAnalysis.id}`, 20, 30);
      doc.text(`Element: ${engineeringData.elementName}`, 20, 40);
      doc.text(`Confidence Score: ${confidenceScore}%`, 20, 50);
      if (isCorrection) doc.text("VERIFICATION STATUS: MANUALLY CORRECTED", 20, 60);

      doc.text("Executive Summary:", 20, 75);
      const summary = doc.splitTextToSize(engineeringData.executiveSummary?.brief || "No summary available.", 170);
      doc.text(summary, 20, 82);

      doc.save(`CivilVision_Report_${currentAnalysis.id}.pdf`);
    } catch (err) {
      console.error("Report generation failed:", err);
    } finally {
      setIsSynthesizing(false);
    }
  };

  if (!isVerified) {
    return (
      <div className="flex flex-col h-full bg-theme-main font-mono overflow-hidden">
        <div className="px-6 py-4 flex items-center justify-between border-b border-theme bg-theme-card/50 backdrop-blur-md">
          <button onClick={onBack} className="p-2 -ml-2 text-theme-muted">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
            </svg>
          </button>
          <span className="text-[10px] font-black uppercase text-blue-500 tracking-[0.2em]">Data Verification</span>
          <div className="w-8"></div>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-6 flex flex-col items-center pb-24">
          <div className="w-full aspect-video rounded-3xl overflow-hidden border border-theme shadow-2xl relative bg-slate-900 shrink-0">
            <img src={currentAnalysis.image} alt="Scan" className="w-full h-full object-contain" />
            {confidenceScore < 70 && !isCorrection && (
              <div className="absolute top-4 left-4 right-4 bg-orange-600/90 text-white p-3 rounded-2xl flex items-center space-x-3 backdrop-blur-md border border-orange-500/50 animate-pulse">
                <span className="text-xl">⚠️</span>
                <span className="text-[10px] font-black uppercase tracking-tighter">Low Confidence Texture Check</span>
              </div>
            )}
          </div>

          <div className="w-full bg-theme-card/80 border border-theme rounded-3xl p-6 text-center shadow-lg relative shrink-0">
            {isCorrection && (
              <div className="absolute -top-3 left-1/2 -translate-x-1/2 bg-green-600 text-[8px] font-black uppercase px-3 py-1 rounded-full text-white shadow-lg border border-green-500">
                Verified By User
              </div>
            )}
            <h2 className="text-[9px] text-blue-500 font-black uppercase tracking-widest mb-3 italic">Detected Project</h2>
            <div className="text-xl font-black uppercase italic text-theme-main mb-2 leading-tight tracking-tight">{engineeringData.elementName}</div>

            <div className="flex items-center justify-center space-x-4 mb-4">
              <div className="flex flex-col">
                <span className="text-[8px] text-theme-muted uppercase font-bold mb-1">Confidence</span>
                <span className={`text-xs font-black ${confidenceScore > 80 ? 'text-green-500' : confidenceScore > 50 ? 'text-orange-500' : 'text-red-500'}`}>{confidenceScore}%</span>
              </div>
              <div className="w-[1px] h-6 bg-theme-muted/20"></div>
              <div className="flex flex-col">
                <span className="text-[8px] text-theme-muted uppercase font-bold mb-1">Method</span>
                <span className="text-[10px] font-black text-blue-400 uppercase">{isCorrection ? 'Learned' : 'Neural'}</span>
              </div>
            </div>

            <p className="text-[11px] text-theme-muted font-medium px-4 leading-relaxed italic">
              {engineeringData.executiveSummary?.brief || "Validating structural properties..."}
            </p>
          </div>

          {!isWrong ? (
            <div className="w-full space-y-4 pt-4 shrink-0">
              <div className="grid grid-cols-2 gap-4">
                <button 
                  onClick={() => setIsVerified(true)}
                  className="bg-blue-600 hover:bg-blue-500 text-white py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all active:scale-95 shadow-xl shadow-blue-500/20"
                >
                  Verify Data
                </button>
                <button 
                  onClick={() => setIsWrong(true)}
                  className="bg-theme-card border border-theme text-theme-muted py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all hover:border-red-500/30 hover:text-red-400"
                >
                  Correct Detection
                </button>
              </div>
            </div>
          ) : (
            <div className="w-full space-y-6 pt-2 animate-in fade-in slide-in-from-bottom-2 duration-300 shrink-0">
              <textarea 
                value={refinementContext}
                onChange={(e) => setRefinementContext(e.target.value)}
                placeholder="Input specific parameters (e.g., 'Grade is M20')..."
                className="w-full bg-theme-card border border-theme rounded-2xl p-4 text-[11px] font-bold text-theme-main outline-none focus:border-blue-500 h-28 resize-none shadow-inner"
              />
              <div className="flex gap-4">
                <button onClick={() => setIsWrong(false)} className="flex-1 bg-theme-card text-theme-muted py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest border border-theme">Cancel</button>
                <button 
                  disabled={!refinementContext.trim() || isReAnalyzing}
                  onClick={handleReAnalyze}
                  className="flex-[2] bg-blue-600 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest disabled:opacity-50 transition-all"
                >
                  {isReAnalyzing ? 'Updating...' : 'Save Correction'}
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  const renderSummaryTab = () => (
    <div className="space-y-6">
      <div className="bg-blue-600/10 p-6 rounded-3xl border border-blue-500/20 shadow-xl">
        <h4 className="text-[10px] font-black uppercase text-blue-500 tracking-widest mb-4">Executive Brief</h4>
        <p className="text-sm font-bold text-theme-main leading-relaxed italic mb-8">
          "{engineeringData.executiveSummary?.brief || "Analysis in progress..."}"
        </p>
        <div className="space-y-4">
          {engineeringData.executiveSummary?.keyEngineeringPoints?.map((point, idx) => (
            <div key={idx} className="flex items-start space-x-3">
