          ))}
        </div>
      </div>
      <div className="flex gap-4 pt-4">
        <button onClick={generateReport} className="flex-1 bg-blue-600 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-lg">Download Report</button>
