import { GoogleGenAI, Type } from "@google/genai";
import { CIVIL_ENGINEER_SYSTEM_PROMPT } from "../constants.ts";
import { StructuralAnalysis } from "../types.ts";

const CORRECTION_DB_KEY = 'civilvision_correction_memory';

export const getImageHash = async (base64: string): Promise<string> => {
  const msgUint8 = new TextEncoder().encode(base64);
  const hashBuffer = await crypto.subtle.digest('SHA-256', msgUint8);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
};

export const saveCorrection = (hash: string, data: StructuralAnalysis) => {
  const db = JSON.parse(localStorage.getItem(CORRECTION_DB_KEY) || '{}');
  db[hash] = { data, timestamp: Date.now() };
  localStorage.setItem(CORRECTION_DB_KEY, JSON.stringify(db));

  const queue = JSON.parse(localStorage.getItem('retraining_queue') || '[]');
  queue.push({ hash, labels: data, timestamp: Date.now() });
  localStorage.setItem('retraining_queue', JSON.stringify(queue));
};

export const analyzeImage = async (base64Image: string, userContext?: string): Promise<StructuralAnalysis> => {
  const apiKey = process.env.API_KEY || (window as any).process?.env?.API_KEY;
  if (!apiKey) throw new Error("API_KEY_MISSING");

  const hash = await getImageHash(base64Image);

  if (!userContext) {
    const db = JSON.parse(localStorage.getItem(CORRECTION_DB_KEY) || '{}');
    if (db[hash]) {
      return { ...db[hash].data, isCorrection: true, confidenceScore: 100 };
    }
  }

  const ai = new GoogleGenAI({ apiKey });

  const identPromise = ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
        { text: `QUICK IDENT: Identify element/apparatus. Include confidenceScore (0-100). Context: ${userContext || 'None'}` }
      ]
    },
    config: {
      systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT,
      responseMimeType: 'application/json',
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          elementName: { type: Type.STRING },
          confidenceScore: { type: Type.NUMBER },
          basicDescription: { type: Type.STRING },
          type: { type: Type.STRING },
          executiveSummary: {
            type: Type.OBJECT,
            properties: {
              brief: { type: Type.STRING },
              keyEngineeringPoints: { type: Type.ARRAY, items: { type: Type.STRING } }
            }
          }
        },
        required: ["elementName", "confidenceScore"]
      }
    }
  });

  const techPromise = ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
        { text: `TECH SPEC: Detailed mix design, IS codes (IS 456, IS 1199), construction methodology, quality checklists, failure patterns, and consultation advice. Context: ${userContext || 'None'}` }
      ]
    },
    config: {
      systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT,
      responseMimeType: 'application/json',
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          isCodeReferences: { type: Type.ARRAY, items: { type: Type.STRING } },
          qualityChecks: { type: Type.ARRAY, items: { type: Type.STRING } },
          constructionMethodology: {
            type: Type.OBJECT,
            properties: {
              concreteSpecs: {
                type: Type.OBJECT,
                properties: {
                  grade: { type: Type.STRING },
                  mixDesign: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: { 
                        material: { type: Type.STRING }, 
                        proportion: { type: Type.STRING }, 
                        quantity: { type: Type.STRING } 
                      }
                    }
                  },
                  wcRatio: { type: Type.STRING }
                }
              },
              processBreakdown: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    phase: { type: Type.STRING },
                    steps: { type: Type.ARRAY, items: { type: Type.STRING } }
                  }
                }
              }
            }
          },
          consultation: {
            type: Type.OBJECT,
            properties: {
              recommendations: { type: Type.ARRAY, items: { type: Type.STRING } },
              optimization: { type: Type.ARRAY, items: { type: Type.STRING } },
              nextSteps: { type: Type.ARRAY, items: { type: Type.STRING } }
            }
          }
        }
      }
    }
  });

  try {
    const [identRes, techRes] = await Promise.all([identPromise, techPromise]);
    const identData = JSON.parse(identRes.text || "{}");
    const techData = JSON.parse(techRes.text || "{}");

    return {
      ...identData,
      ...techData,
      isCorrection: false,
      dimensions: identData.dimensions || "Standard (Verify in field)",
      defects: []
    };
  } catch (error) {
    console.error("Pipeline Error:", error);
    throw new Error("ENGINEERING_LINK_FAILED");
  }
};

export const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
};

export const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useEffect } from 'react';
