import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from '@google/genai';
import { StructuralAnalysis } from '../types.ts';
import { CIVIL_ENGINEER_SYSTEM_PROMPT } from '../constants.ts';

interface Message {
  role: 'user' | 'model';
  text: string;
  timestamp: string;
}

interface EngineeringChatbotProps {
  context: StructuralAnalysis;
  onMessagesUpdate?: (messages: Message[]) => void;
}

const EngineeringChatbot: React.FC<EngineeringChatbotProps> = ({ context, onMessagesUpdate }) => {
  const [messages, setMessages] = useState<Message[]>([
    { 
      role: 'model', 
      text: context.isCorrection 
        ? `I have applied the **Manual Override** for this element. How can I assist with this verified data?`
        : `Expert Consultant Online. I've scanned the **${context.elementName}**. How can I help?`,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isRetrying, setIsRetrying] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
    if (onMessagesUpdate) {
        onMessagesUpdate(messages);
    }
  }, [messages, isTyping, onMessagesUpdate]);

  const handleSend = async (customInput?: string, retryCount = 0) => {
    const userMessage = (customInput || input).trim();
    if (!userMessage || isTyping) return;

    if (retryCount === 0) {
      const time = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      setInput('');
      setMessages(prev => [...prev, { role: 'user', text: userMessage, timestamp: time }]);
      setIsTyping(true);
    } else {
      setIsRetrying(true);
    }

    try {
      // Create new instance with 60s timeout handling conceptually (Gemini SDK uses standard fetch)
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // OPTIMIZATION: Stripping heavy data (base64 images) and only sending critical metadata strings
      const metadataContext = {
        elementName: context.elementName,
        grade: context.constructionMethodology?.concreteSpecs?.grade || 'N/A',
        category: context.elementCategory,
        status: context.isCorrection ? 'MANUALLY_VERIFIED' : 'AI_ESTIMATED',
        defects: context.defects?.map(d => d.type).join(', '),
        originalAIAnalysis: context.originalData ? "ELEMENT_VERIFIED_BY_FIELD_ENGINEER" : "FIRST_SCAN"
      };

      const chat = ai.chats.create({
        model: 'gemini-3-pro-preview',
        config: {
          thinkingConfig: { thinkingBudget: 0 },
          systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT + `

          STRICT OPERATIONAL CONTEXT:
          ${JSON.stringify(metadataContext)}

          CHAT RESPONSE RULES (CRITICAL):
          1. SILENT RECONNECT: You are part of a continuous secure link. If state is re-synced, just continue.
          2. PAYLOAD AWARENESS: You are receiving only structural metadata to conserve site bandwidth.
          3. CORRECTION AWARENESS: If status is MANUALLY_VERIFIED, honor the user's field override.
          4. DIRECT ANSWERS: If user asks direct question, answer in 10 words or less.
          5. NO LECTURING: Focus only on "quality", "remediation", and "IS code lookup".`,
        }
      });

      const response = await chat.sendMessage({ message: userMessage });
      const mText = response.text || "Secure Link error.";

      setMessages(prev => [...prev, { 
        role: 'model', 
        text: mText,
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      }]);
      setIsRetrying(false);
    } catch (err) {
      console.error(`Chat Link Interrupted (Retry ${retryCount}):`, err);

      // AUTO SILENT RECONNECT LOGIC: Retry up to 2 times
      if (retryCount < 2) {
        console.log("Re-establishing Secure Link...");
        setTimeout(() => handleSend(userMessage, retryCount + 1), 1500);
      } else {
        setMessages(prev => [...prev, { 
          role: 'model', 
          text: "⚠️ SECURITY PROTOCOL: Link lost after multiple attempts. Please check site network stability.",
          timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        }]);
        setIsRetrying(false);
      }
    } finally {
      if (retryCount >= 2 || !isRetrying) {
        setIsTyping(false);
        setIsRetrying(false);
      }
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-950 font-mono relative">
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 pb-24 scrollbar-hide">
        {messages.map((m, idx) => (
          <div key={idx} className={`flex w-full ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`p-3 text-[11px] font-medium shadow-xl rounded-2xl ${m.role === 'user' ? 'bg-blue-600 text-white rounded-br-none' : 'bg-slate-900 border border-slate-800 text-slate-300 rounded-bl-none'}`}>
              {m.text}
              <div className="mt-1 text-[7px] font-black uppercase opacity-40">{m.timestamp}</div>
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex items-center space-x-2 px-2">
            <div className="flex space-x-1">
              <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce"></div>
              <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce delay-75"></div>
              <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce delay-150"></div>
            </div>
            <span className="text-blue-500 text-[9px] uppercase font-black tracking-widest">
              {isRetrying ? 'Re-establishing Link...' : 'AI Consultant Processing...'}
            </span>
          </div>
        )}
      </div>
      <div className="p-4 bg-slate-950 border-t border-slate-900">
        <div className={`bg-slate-900 border border-blue-500/30 rounded-2xl px-3 py-1 flex items-center transition-all ${isTyping ? 'opacity-40 pointer-events-none' : 'opacity-100'}`}>
          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            disabled={isTyping}
            placeholder="Query structural history..."
            className="flex-1 bg-transparent border-none outline-none text-xs py-2 px-2 text-white placeholder:text-slate-700"
          />
          <button onClick={() => handleSend()} disabled={isTyping} className="p-2 text-blue-500 disabled:text-slate-700">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 rotate-90" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
};

export default EngineeringChatbot;

export enum AppMode {
