              <div className="space-y-6">
                <div className="h-40 bg-slate-900/50 rounded-3xl animate-pulse"></div>
                <div className="h-20 bg-slate-900/50 rounded-3xl animate-pulse delay-75"></div>
              </div>
            ) : (
              <React.Fragment>
                {activeTab === 'summary' && renderSummaryTab()}
                {activeTab === 'technical' && renderTechnicalTab()}
                {activeTab === 'inspection' && renderInspectionTab()}
                {activeTab === 'consult' && renderConsultTab()}
                {activeTab === 'chat' && (
                  <div className="bg-theme-card rounded-3xl overflow-hidden border border-theme shadow-2xl h-[500px]">
                    <EngineeringChatbot context={engineeringData} />
                  </div>
                )}
              </React.Fragment>
            )}
          </div>
        </div>
        {renderActionButtons()}
      </div>
    </div>
  );
};

export default AnalysisView;

import React, { useState, useEffect, useRef } from 'react';
import { AnalysisResult, UserRole, StructuralAnalysis, Defect } from '../types.ts';
import EngineeringChatbot from './EngineeringChatbot.tsx';
import VoiceLiveSession from './VoiceLiveSession.tsx';
import { analyzeImage, saveCorrection, refineExpertAdvice } from '../services/gemini.ts';
import { CONCRETE_STANDARDS } from '../constants.ts';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

interface AnalysisViewProps {
  analysis: AnalysisResult;
  onBack: () => void;
  role: UserRole;
}

const TABS = ['summary', 'technical', 'inspection', 'consult', 'chat'] as const;

const AnalysisView: React.FC<AnalysisViewProps> = ({ analysis: initialAnalysis, onBack }) => {
  const [currentAnalysis, setCurrentAnalysis] = useState<AnalysisResult>(initialAnalysis);
  const [isVerified, setIsVerified] = useState(false);
  const [isWrong, setIsWrong] = useState(false);
  const [refinementContext, setRefinementContext] = useState('');
  const [isReAnalyzing, setIsReAnalyzing] = useState(false);
  const [activeTab, setActiveTab] = useState<typeof TABS[number]>('summary');
  const [isLoadingDeepData, setIsLoadingDeepData] = useState(true);

  // Content Override States
  const [isEditingContent, setIsEditingContent] = useState(false);
  const [tempOverrides, setTempOverrides] = useState<Record<string, string>>({});
  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const engineeringData = currentAnalysis.data;
  const isExperiment = engineeringData.elementCategory === 'EXPERIMENT';

  useEffect(() => {
    setActiveTab('summary');
    setIsVerified(false);
    setIsWrong(false);
    setIsLoadingDeepData(true);
    setIsEditingContent(false);
    setTempOverrides({});
    setHasUnsavedChanges(false);

    const timer = setTimeout(() => setIsLoadingDeepData(false), 800);
    return () => clearTimeout(timer);
  }, [initialAnalysis.id]);

  useEffect(() => {
    if (scrollContainerRef.current) {
      scrollContainerRef.current.scrollTop = 0;
    }
  }, [activeTab]);

  // Prevent leaving with unsaved changes
  useEffect(() => {
    const handleBeforeUnload = (e: BeforeUnloadEvent) => {
      if (hasUnsavedChanges) {
        e.preventDefault();
        e.returnValue = "Unsaved changes in report content. Stay or Leave?";
      }
    };
    window.addEventListener('beforeunload', handleBeforeUnload);
    return () => window.removeEventListener('beforeunload', handleBeforeUnload);
  }, [hasUnsavedChanges]);

  const handleReAnalyze = async () => {
    const capturedContext = refinementContext.trim();
    if (!capturedContext || isReAnalyzing) return;

    // 1. Instant UI Lock & Validation
    setIsReAnalyzing(true);

    // 2. Local Intelligence - Detect Grade Overrides
    const gradeMatch = capturedContext.match(/M[0-9]{2}/i);
    const targetGrade = gradeMatch ? gradeMatch[0].toUpperCase() : null;

    let updatedData: StructuralAnalysis = { ...engineeringData };

    if (targetGrade && CONCRETE_STANDARDS[targetGrade]) {
      // 3. Fast Parameter Override (Local Math) - Skips full re-inference
      const std = CONCRETE_STANDARDS[targetGrade];
      updatedData = {
        ...updatedData,
        isCorrection: true,
        constructionMethodology: {
          ...updatedData.constructionMethodology,
          methodSummary: updatedData.constructionMethodology?.methodSummary || "",
          concreteSpecs: {
            ...updatedData.constructionMethodology?.concreteSpecs,
            grade: targetGrade,
            mixDesign: [
              { material: 'Cement', quantity: std.cement, proportion: std.ratio.split(':')[0] || '1' },
              { material: 'Water/Cement', quantity: std.wc, proportion: 'Ratio' },
              { material: 'Aggregates', quantity: 'Calculated', proportion: std.ratio.split(':').slice(1).join(':') }
            ]
          }
        }
      };

      // Fast transition - under 1s for immediate state update
      setTimeout(() => {
        setCurrentAnalysis(prev => ({ ...prev, data: updatedData }));
        setIsVerified(true);
        setIsWrong(false);
        setIsReAnalyzing(false);
        setRefinementContext('');
        saveCorrection(currentAnalysis.imageHash, updatedData);
      }, 800);

      // 4. Background Expert Advice Refinement (Asynchronous Update)
      refineExpertAdvice(updatedData, capturedContext).then(refinements => {
        if (Object.keys(refinements).length > 0) {
          setCurrentAnalysis(prev => ({
            ...prev,
            data: { ...prev.data, ...refinements }
          }));
        }
      });

      return;
    }

    // Fallback: Full AI analysis if no simple grade match found
    try {
      const base64 = currentAnalysis.image.split(',')[1];
      const newData = await analyzeImage(base64, capturedContext);
      updatedData = { ...newData, isCorrection: true, originalData: engineeringData };
      saveCorrection(currentAnalysis.imageHash, updatedData);
      setCurrentAnalysis(prev => ({ ...prev, data: updatedData }));
      setIsVerified(true);
      setIsWrong(false);
      setRefinementContext('');
    } catch (err) {
      console.error("Re-analysis failed:", err);
    } finally {
      setIsReAnalyzing(false);
    }
  };

  const getConfidenceStatus = (score: number) => {
    if (score > 85) return "High Confidence";
    if (score > 60) return "Needs Engineering Verification";
    return "Visual Data Unclear";
  };

  const toggleEditMode = () => {
    if (isEditingContent) {
      if (hasUnsavedChanges) {
        setShowConfirmModal(true);
      } else {
        setIsEditingContent(false);
      }
    } else {
      setIsEditingContent(true);
      const initial: Record<string, string> = { ...engineeringData.contentOverrides };
      setTempOverrides(initial);
    }
  };

  const handleOverrideChange = (key: string, value: string) => {
    setTempOverrides(prev => ({ ...prev, [key]: value }));
    setHasUnsavedChanges(true);
  };

  const saveOverrides = () => {
    const updatedData = { 
      ...engineeringData, 
      contentOverrides: { ...tempOverrides } 
    };
    setCurrentAnalysis(prev => ({ ...prev, data: updatedData }));
    saveCorrection(currentAnalysis.imageHash, updatedData);
    setIsEditingContent(false);
    setHasUnsavedChanges(false);
    setShowConfirmModal(false);
  };

  const resetToOriginal = () => {
    if (window.confirm("Are you sure you want to discard all manual edits and reset to AI original?")) {
      const updatedData = { ...engineeringData, contentOverrides: {} };
      setCurrentAnalysis(prev => ({ ...prev, data: updatedData }));
      saveCorrection(currentAnalysis.imageHash, updatedData);
      setTempOverrides({});
      setHasUnsavedChanges(false);
      setIsEditingContent(false);
    }
  };

  const getContent = (key: string, defaultValue: string) => {
    return engineeringData.contentOverrides?.[key] ?? defaultValue;
  };

  const generatePDFReport = () => {
    const doc = new jsPDF();
    const data = engineeringData;

    doc.setFontSize(22);
    doc.text("CivilVision AI: Structural Inspection Report", 20, 20);

    doc.setFontSize(12);
    doc.text(`Element: ${data.elementName}`, 20, 30);
    doc.text(`Category: ${data.elementCategory}`, 20, 37);
    doc.text(`Status: ${getConfidenceStatus(data.confidenceScore)}`, 20, 44);

    doc.setFontSize(16);
    doc.text("Executive Summary", 20, 55);
    doc.setFontSize(10);
    const brief = getContent('summary_brief', data.executiveSummary?.brief || "");
    const splitBrief = doc.splitTextToSize(brief, 170);
    doc.text(splitBrief, 20, 62);

    let y = 62 + (splitBrief.length * 5) + 10;

    doc.setFontSize(16);
    doc.text("Technical Details", 20, y);
    y += 7;
    doc.setFontSize(10);
    const techText = isExperiment 
      ? getContent('tech_procedure', data.labExperiment?.procedure?.join('\n') || "")
      : getContent('tech_methodology', data.constructionMethodology?.methodSummary || "");
    const splitTech = doc.splitTextToSize(techText, 170);
    doc.text(splitTech, 20, y);

    y += (splitTech.length * 5) + 10;
    doc.setFontSize(16);
    doc.text("Inspection & Defects", 20, y);
    y += 7;
    // Defensive check for defects iteration
    (data.defects || []).forEach((d, i) => {
      doc.setFontSize(11);
      doc.text(`${i+1}. ${d.type} (${d.severity})`, 20, y);
      y += 5;
      doc.setFontSize(9);
      const cause = getContent(`defect_${i}_cause`, d.cause);
      const remedy = getContent(`defect_${i}_remedy`, d.remedy);
      doc.text(`Cause: ${cause}`, 25, y);
      y += 5;
      doc.text(`Remedy: ${remedy}`, 25, y);
      y += 8;
    });

    doc.save(`CivilVision_Report_${data.elementName.replace(/\s+/g, '_')}.pdf`);
  };

  const renderEditableText = (key: string, value: string, placeholder: string = "Enter text...") => {
    const currentVal = tempOverrides[key] ?? value;
    const isOverridden = !!engineeringData.contentOverrides?.[key];

    if (isEditingContent) {
      return (
        <textarea
          value={currentVal}
          onChange={(e) => handleOverrideChange(key, e.target.value)}
          placeholder={placeholder}
          className="w-full bg-slate-900 border border-blue-500/50 rounded-xl p-3 text-xs text-white focus:outline-none min-h-[100px] resize-none animate-in fade-in duration-200"
        />
      );
    }
    return (
      <div className={`relative transition-all ${isOverridden ? 'border-l-2 border-blue-500 pl-4 py-1 italic' : ''}`}>
        <p className="text-xs font-medium text-theme-muted leading-relaxed">
          {getContent(key, value)}
        </p>
        {isOverridden && (
          <span className="text-[7px] font-black text-blue-500 uppercase tracking-widest absolute -top-3 left-4">User Verified Override</span>
        )}
      </div>
    );
  };

  const renderSummaryTab = () => (
    <div className="space-y-6">
      <div className="bg-blue-600/10 p-6 rounded-3xl border border-blue-500/20 shadow-xl relative">
        <h4 className="text-[10px] font-black uppercase text-blue-500 tracking-widest mb-4">Executive Brief</h4>
        {renderEditableText('summary_brief', engineeringData.executiveSummary?.brief || "")}

        <div className="space-y-4 mt-8">
          {engineeringData.executiveSummary?.keyEngineeringPoints?.map((point, idx) => (
            <div key={idx} className="flex items-start space-x-3">
              <div className="w-1.5 h-1.5 bg-blue-500 rounded-full mt-1.5 shrink-0"></div>
              <p className="text-xs font-bold text-theme-muted leading-snug">{point}</p>
            </div>
          ))}
        </div>
      </div>
      <div className="flex gap-4 pt-4">
        <button onClick={generatePDFReport} className="flex-1 bg-blue-600 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-lg active:scale-95 transition-all">Download PDF Report</button>
      </div>
    </div>
  );

  const renderTechnicalTab = () => (
    <div className="space-y-6">
      <div className="bg-theme-card p-6 rounded-3xl border border-theme">
        <h4 className="text-[10px] font-black uppercase text-blue-500 tracking-widest mb-4 italic">
          {isExperiment ? "🛠️ Step-by-Step Procedure" : "🏗️ Construction Methodology"}
        </h4>

        {isExperiment ? (
          <div className="space-y-4">
             {isEditingContent ? (
                renderEditableText('tech_procedure', engineeringData.labExperiment?.procedure?.join('\n') || "", "Enter steps one per line...")
             ) : (
                engineeringData.labExperiment?.procedure?.map((step, idx) => (
                  <div key={idx} className="flex space-x-3">
                    <span className="text-blue-500 font-black text-[10px] mt-0.5">{idx + 1}.</span>
                    <p className="text-[11px] font-medium text-theme-muted leading-relaxed">
                      {getContent(`tech_step_${idx}`, step)}
                    </p>
                  </div>
                ))
             )}
             <div className="mt-6 pt-4 border-t border-theme">
               <h5 className="text-[9px] font-black uppercase text-theme-muted mb-2">Apparatus Requirements</h5>
               <div className="flex flex-wrap gap-2">
                 {engineeringData.labExperiment?.apparatus?.map((item, i) => (
                   <span key={i} className="px-2 py-1 bg-slate-900 border border-slate-800 rounded text-[9px] font-bold text-slate-400">{item}</span>
                 ))}
               </div>
             </div>
          </div>
        ) : (
          <div className="space-y-6">
            {renderEditableText('tech_methodology', engineeringData.constructionMethodology?.methodSummary || "")}
            <div className="grid grid-cols-2 gap-4">
              <div className="p-3 bg-slate-900 rounded-2xl border border-slate-800">
                <span className="text-[8px] text-blue-500 font-black uppercase block mb-1">Shuttering</span>
                <span className="text-[10px] font-black text-white">{engineeringData.constructionMethodology?.concreteSpecs?.shutteringType || "Plywood/Steel"}</span>
              </div>
              <div className="p-3 bg-slate-900 rounded-2xl border border-slate-800">
                <span className="text-[8px] text-blue-500 font-black uppercase block mb-1">Rebar Density</span>
                <span className="text-[10px] font-black text-white">{engineeringData.constructionMethodology?.concreteSpecs?.reinforcementDensity || "Standard"}</span>
              </div>
            </div>

            {/* Mix Design Table */}
            {engineeringData.constructionMethodology?.concreteSpecs?.mixDesign && (
              <div className="mt-4 bg-slate-900 border border-theme rounded-2xl p-4">
                 <h5 className="text-[8px] font-black text-blue-500 uppercase mb-3">IS 456 Mix Ratios ({engineeringData.constructionMethodology.concreteSpecs.grade})</h5>
                 <div className="space-y-2">
                   {engineeringData.constructionMethodology.concreteSpecs.mixDesign.map((item, i) => (
                     <div key={i} className="flex justify-between items-center text-[10px] border-b border-white/5 pb-1">
                        <span className="text-slate-500 font-bold uppercase">{item.material}</span>
                        <div className="flex space-x-4">
                          <span className="text-white font-black">{item.quantity}</span>
                          <span className="text-blue-500/60 font-mono">[{item.proportion}]</span>
                        </div>
                     </div>
                   ))}
                 </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );

  const renderInspectionTab = () => (
    <div className="space-y-6">
      <div className="flex items-center justify-between px-2">
        <h4 className="text-[10px] font-black uppercase text-theme-muted tracking-widest italic">⚠️ Defects & Quality Issues</h4>
        <span className="px-2 py-0.5 bg-red-500/20 text-red-500 text-[8px] font-black rounded uppercase">Critical Section</span>
      </div>

      {engineeringData.defects && engineeringData.defects.length > 0 ? (
        engineeringData.defects.map((defect, idx) => {
          const isCritical = defect.severity === 'Critical';
          const isMedium = defect.severity === 'Medium';
          const cardColorClass = isCritical 
            ? 'bg-red-950/20 border-red-500/40' 
            : isMedium 
              ? 'bg-yellow-950/20 border-yellow-500/40' 
              : 'bg-blue-950/20 border-blue-500/40';

          return (
            <div key={idx} className={`${cardColorClass} border rounded-3xl p-6 space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-500 shadow-xl`}>
               <div className="flex justify-between items-start">
                 <div className="flex-1">
                    <h5 className="text-[9px] font-black uppercase opacity-60 mb-1 tracking-widest">[ISSUE]</h5>
                    <div className="text-lg font-black text-white uppercase italic tracking-tight leading-tight">{defect.type}</div>
                 </div>
                 <span className={`px-2 py-1 rounded-lg text-[8px] font-black uppercase ml-4 whitespace-nowrap ${
                   isCritical ? 'bg-red-600 text-white' : 
                   isMedium ? 'bg-yellow-600 text-slate-950' : 'bg-blue-600 text-white'
                 }`}>
                   {defect.severity}
                 </span>
               </div>

               <div className="grid grid-cols-1 gap-4 pt-2">
                 <div>
                   <span className="text-[8px] font-black opacity-50 uppercase block mb-1 tracking-widest">[CAUSE]</span>
                   {renderEditableText(`defect_${idx}_cause`, defect.cause)}
                 </div>
                 <div className="bg-black/40 p-4 rounded-2xl border border-white/5">
                   <span className="text-[8px] font-black text-green-500 uppercase block mb-1 tracking-widest">[FIX]</span>
                   {renderEditableText(`defect_${idx}_remedy`, defect.remedy)}
                 </div>
               </div>
            </div>
          );
        })
      ) : (
        <div className="bg-theme-card p-12 rounded-3xl border border-theme border-dashed text-center">
          <div className="text-3xl mb-3 opacity-20">🛡️</div>
          <p className="text-[10px] text-theme-muted uppercase font-black tracking-widest">No structural defects detected within visible range.</p>
        </div>
      )}
    </div>
  );

  const renderConsultTab = () => {
    // Fixed: Defensive check for defects map to prevent Uncaught TypeError
    const defectTypes = (engineeringData.defects || []).map(d => d.type).join(', ') || 'General Structural Properties';
    return (
      <div className="bg-theme-card rounded-3xl overflow-hidden border border-theme shadow-2xl h-[500px]">
        <VoiceLiveSession 
          context={engineeringData} 
          initialPrompt={`Deep dive consultation for ${engineeringData.elementName}. Discuss elements: ${defectTypes}.`} 
        />
      </div>
    );
  };

  const renderActionButtons = () => {
    if (!isEditingContent) return null;
    return (
      <div className="fixed bottom-24 left-6 right-6 z-50 animate-in slide-in-from-bottom-4 duration-300">
        <div className="bg-slate-900 border border-blue-500/30 p-4 rounded-3xl shadow-2xl flex flex-col space-y-3 backdrop-blur-xl">
           <div className="flex items-center space-x-2 px-2">
              <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-pulse"></span>
              <span className="text-[8px] font-black text-blue-400 uppercase tracking-widest">Unsaved Manual Overrides Detected</span>
           </div>
           <div className="flex gap-3">
              <button onClick={resetToOriginal} className="flex-1 bg-slate-800 text-slate-400 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest border border-slate-700 active:scale-95 transition-all">Reset to Original</button>
              <button onClick={() => setShowConfirmModal(true)} disabled={!hasUnsavedChanges} className="flex-[2] bg-blue-600 text-white py-3 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg shadow-blue-500/20 active:scale-95 transition-all disabled:opacity-50">Save Changes</button>
           </div>
        </div>
      </div>
    );
  };

  const renderConfirmModal = () => {
    if (!showConfirmModal) return null;
    return (
      <div className="fixed inset-0 z-[100] bg-slate-950/80 backdrop-blur-md flex items-center justify-center p-8">
        <div className="bg-theme-card border border-blue-500/30 p-8 rounded-[2.5rem] shadow-2xl max-w-sm w-full text-center space-y-6 animate-in zoom-in-95 duration-200">
           <div className="w-16 h-16 bg-blue-600/10 rounded-3xl mx-auto flex items-center justify-center text-3xl">⚠️</div>
           <div className="space-y-2">
              <h3 className="text-sm font-black text-white uppercase tracking-widest">Confirm Edit</h3>
              <p className="text-[10px] text-slate-400 leading-relaxed font-bold italic">
                You are overriding AI-generated technical data. This will update the primary report and PDF output. Do you wish to proceed?
              </p>
           </div>
           <div className="flex gap-4">
              <button onClick={() => setShowConfirmModal(false)} className="flex-1 bg-slate-900 border border-slate-800 text-slate-500 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest active:scale-95 transition-all">Cancel</button>
              <button onClick={saveOverrides} className="flex-[2] bg-blue-600 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl shadow-blue-500/20 active:scale-95 transition-all">Save Override</button>
           </div>
        </div>
      </div>
    );
  };

  if (!isVerified) {
    return (
      <div className="flex flex-col h-full bg-theme-main font-mono overflow-hidden">
        <div className="px-6 py-4 flex items-center justify-between border-b border-theme bg-theme-card/50 backdrop-blur-md">
          <button onClick={onBack} disabled={isReAnalyzing} className="p-2 -ml-2 text-theme-muted hover:text-white transition-colors disabled:opacity-20">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
            </svg>
          </button>
          <span className="text-[10px] font-black uppercase text-blue-500 tracking-[0.2em]">Data Verification</span>
          <div className="w-8"></div>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-6 flex flex-col items-center pb-24 relative">
          {isReAnalyzing && (
            <div className="absolute inset-0 z-50 bg-slate-950/60 backdrop-blur-sm flex items-center justify-center p-8">
              <div className="bg-theme-card border border-blue-500/30 p-8 rounded-3xl shadow-2xl flex flex-col items-center animate-in zoom-in-95 duration-200">
                <div className="w-12 h-12 border-4 border-blue-500/10 border-t-blue-500 rounded-full animate-spin mb-4"></div>
                <h3 className="text-xs font-black text-white uppercase tracking-widest">Applying Engineering Standards...</h3>
                <p className="text-[9px] text-blue-400 mt-2 uppercase font-bold">Optimizing IS 456 Parameters</p>
              </div>
            </div>
          )}

          <div className="w-full aspect-video rounded-3xl overflow-hidden border border-theme shadow-2xl relative bg-slate-900 shrink-0">
            <img src={currentAnalysis.image} alt="Scan" className="w-full h-full object-contain" />
            <div className="absolute top-4 left-4 bg-black/50 backdrop-blur-md px-3 py-1.5 rounded-xl border border-white/10 flex items-center space-x-2">
                <span className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></span>
                <span className="text-[9px] font-black text-white uppercase">{engineeringData.elementCategory}</span>
            </div>
          </div>

          <div className="w-full bg-theme-card/80 border border-theme rounded-3xl p-6 text-center shadow-lg relative shrink-0">
            <h2 className="text-[9px] text-blue-500 font-black uppercase tracking-widest mb-3 italic">Detected Project</h2>
            <div className="text-xl font-black uppercase italic text-theme-main mb-2 leading-tight tracking-tight">{engineeringData.elementName}</div>

            <div className="flex items-center justify-center space-x-4 mb-4">
              <div className="flex flex-col">
                <span className="text-[8px] text-theme-muted uppercase font-bold mb-1">Status</span>
                <span className={`text-xs font-black uppercase italic tracking-tighter ${engineeringData.confidenceScore > 80 ? 'text-green-500' : 'text-orange-500'}`}>
                  {getConfidenceStatus(engineeringData.confidenceScore)}
                </span>
              </div>
            </div>

            <p className="text-[11px] text-theme-muted font-medium px-4 leading-relaxed italic">
              {getContent('summary_brief', engineeringData.executiveSummary?.brief || "Analysis complete.")}
            </p>
          </div>

          {!isWrong ? (
            <div className="w-full space-y-4 pt-4 shrink-0">
              <div className="grid grid-cols-2 gap-4">
                <button 
                  onClick={() => setIsVerified(true)}
                  className="bg-blue-600 hover:bg-blue-500 text-white py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all active:scale-95 shadow-xl shadow-blue-500/20"
                >
                  Confirm & View
                </button>
                <button 
                  onClick={() => setIsWrong(true)}
                  className="bg-theme-card border border-theme text-theme-muted py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all hover:border-red-500/30 hover:text-red-400"
                >
                  Correct ID
                </button>
              </div>
            </div>
          ) : (
            <div className="w-full space-y-6 pt-2 animate-in fade-in slide-in-from-bottom-2 duration-300 shrink-0">
              <div className="relative">
                <textarea 
                  value={refinementContext}
                  onChange={(e) => setRefinementContext(e.target.value)}
                  readOnly={isReAnalyzing}
                  placeholder="Input specific parameters (e.g., 'Grade is M20')..."
                  className={`w-full bg-theme-card border border-theme rounded-2xl p-4 text-[11px] font-bold text-theme-main outline-none focus:border-blue-500 h-28 resize-none shadow-inner transition-all ${isReAnalyzing ? 'opacity-50 grayscale cursor-not-allowed' : ''}`}
                />
                {isReAnalyzing && (
                   <div className="absolute inset-0 bg-slate-900/10 flex items-center justify-center rounded-2xl">
                     <div className="w-6 h-6 border-2 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                   </div>
                )}
              </div>
              <div className="flex gap-4">
                <button onClick={() => setIsWrong(false)} disabled={isReAnalyzing} className="flex-1 bg-theme-card text-theme-muted py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest border border-theme disabled:opacity-20 transition-all">Cancel</button>
                <button 
                  disabled={!refinementContext.trim() || isReAnalyzing}
                  onClick={handleReAnalyze}
                  className="flex-[2] bg-blue-600 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest disabled:opacity-50 transition-all shadow-lg shadow-blue-500/20 active:scale-95"
                >
                  {isReAnalyzing ? 'Applying...' : 'Apply Correction'}
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-theme-main overflow-hidden font-sans">
      {renderConfirmModal()}

      <div className="px-6 py-4 flex items-center justify-between bg-theme-card/90 border-b border-theme sticky top-0 z-30 backdrop-blur-xl shrink-0">
        <button onClick={onBack} className="p-2 -ml-2 text-theme-muted hover:text-theme-main transition-colors">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
          </svg>
        </button>
        <div className="text-center">
          <div className="text-[8px] text-blue-500 font-black uppercase tracking-widest mb-1 italic">{engineeringData.elementCategory} ANALYSIS</div>
          <div className="text-xs font-black uppercase truncate max-w-[180px] tracking-tight">{engineeringData.elementName}</div>
        </div>
        <div className="flex items-center">
          <button 
            onClick={toggleEditMode}
            className={`p-2.5 rounded-xl border transition-all ${
              isEditingContent 
                ? 'bg-blue-600 border-blue-500 text-white' 
                : 'bg-slate-900 border-slate-800 text-slate-400 hover:border-blue-500/50 hover:text-blue-400'
            }`}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
            </svg>
          </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col overflow-hidden relative">
        <div ref={scrollContainerRef} className="analysis-content scrollbar-hide">
          <div className="relative w-full h-56 bg-slate-950 overflow-hidden shrink-0">
            <img src={currentAnalysis.image} alt="Site Vision" className="w-full h-full object-contain block" />
            <div className="absolute inset-0 bg-gradient-to-t from-theme-main via-transparent to-transparent"></div>
          </div>

          <div className="sticky top-0 z-20 px-4 py-3 bg-theme-main/95 backdrop-blur-xl border-b border-theme shadow-xl overflow-x-auto scrollbar-hide shrink-0">
            <div className="flex p-1 bg-theme-card/50 rounded-2xl border border-theme relative min-w-max">
              {TABS.map((id) => (
                <button 
                  key={id}
                  onClick={() => setActiveTab(id)}
                  className={`px-4 py-2.5 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all duration-300 relative z-10 ${
                    activeTab === id ? 'text-white' : 'text-theme-muted hover:text-theme-main'
                  }`}
                >
                  {activeTab === id && (
                    <div className="absolute inset-0 bg-blue-600 rounded-xl shadow-lg"></div>
                  )}
                  <span className="relative z-10">{id}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="p-6 pb-40 animate-in fade-in duration-500 tab-content flex-1">
            {isLoadingDeepData && activeTab !== 'chat' ? (
              <div className="space-y-6">
                <div className="h-40 bg-slate-900/50 rounded-3xl animate-pulse"></div>
                <div className="h-20 bg-slate-900/50 rounded-3xl animate-pulse delay-75"></div>
              </div>
            ) : (
              <React.Fragment>
                {activeTab === 'summary' && renderSummaryTab()}
                {activeTab === 'technical' && renderTechnicalTab()}
                {activeTab === 'inspection' && renderInspectionTab()}
                {activeTab === 'consult' && renderConsultTab()}
                {activeTab === 'chat' && (
                  <div className="bg-theme-card rounded-3xl overflow-hidden border border-theme shadow-2xl h-[500px]">
                    <EngineeringChatbot context={engineeringData} />
                  </div>
                )}
              </React.Fragment>
            )}
          </div>
        </div>
        {renderActionButtons()}
      </div>
    </div>
  );
};

export default AnalysisView;

