  const [statusText, setStatusText] = useState("Initializing Site Vision...");

  // Debouncing Logic
  const lastCaptureTimeRef = useRef<number>(0);

  useEffect(() => {
    let interval: number;
    if (isProcessing) {
      const startTime = Date.now();
      const ESTIMATED_TOTAL_MS = 3500;
      interval = window.setInterval(() => {
        const elapsed = Date.now() - startTime;
        setProgress(Math.min((elapsed / ESTIMATED_TOTAL_MS) * 100, 98));
      }, 50);
    }
    return () => clearInterval(interval);
  }, [isProcessing]);

  useEffect(() => {
    const startCamera = async () => {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1280 } },
          audio: false 
        });
        setStream(s);
        if (videoRef.current) videoRef.current.srcObject = s;
      } catch (err) {
        setError('CRITICAL: CAMERA_ACCESS_DENIED');
      }
    };
    startCamera();
    return () => stream?.getTracks().forEach(track => track.stop());
  }, []);

  const handleCapture = async () => {
    const now = Date.now();
    if (now - lastCaptureTimeRef.current < 5000) {
      console.warn("Capture debounced. Please wait 5s.");
      return;
    }
    lastCaptureTimeRef.current = now;

    if (!videoRef.current || !canvasRef.current || isProcessing) return;
    setIsProcessing(true);
    setProgress(0);
    setStatusText("Capturing Frame...");
    setError(null);

    const canvas = canvasRef.current;
    const video = videoRef.current;
    const ctx = canvas.getContext('2d');

    if (ctx) {
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      ctx.drawImage(video, 0, 0);
      const imageData = canvas.toDataURL('image/jpeg', 0.8);
      const base64 = imageData.split(',')[1];

      try {
        setStatusText("Verifying Structural Signature...");
        const hash = await getImageHash(base64);

        // Check for existing verified data to skip re-inference
        const stored = getStoredCorrection(hash);
        if (stored) {
          setStatusText("Previous user correction found. Applying verified data...");
          setProgress(100);
          setTimeout(() => {
            onComplete({
              id: Date.now().toString(),
              timestamp: Date.now(),
              image: imageData,
              imageHash: hash,
              data: { ...stored, isCorrection: true },
              isFromMemory: true
            });
          }, 800);
          return;
        }

        setStatusText("Scanning Neural weights...");
        const result = await analyzeImage(base64);

        onComplete({
          id: Date.now().toString(),
          timestamp: Date.now(),
          image: imageData,
          imageHash: hash,
          data: result
        });
      } catch (err: any) {
        console.error("Camera capture analysis failed:", err);
        if (err?.message === 'QUOTA_EXCEEDED' || err?.status === 429) {
          setError("AI Consultant peak capacity. Please try again in 60s or select from history.");
        } else {
          setError("SITE_SCAN_FAILED");
        }
        setIsProcessing(false);
      }
    }
  };

  return (
    <div className="relative h-full w-full bg-black overflow-hidden flex flex-col font-mono">
      {isProcessing && (
        <div className="absolute inset-0 z-[100] bg-slate-950 flex flex-col items-center justify-center p-10 text-center">
          <div className="w-16 h-16 border-2 border-blue-500/10 border-t-blue-500 rounded-full animate-spin mb-4"></div>
          <h2 className="text-sm font-black text-white uppercase italic tracking-tighter">{statusText}</h2>
          <div className="w-full max-w-xs bg-slate-900 h-1 rounded-full overflow-hidden mt-4">
            <div className="bg-blue-600 h-full transition-all" style={{ width: `${progress}%` }}></div>
          </div>
        </div>
      )}
      <video ref={videoRef} autoPlay playsInline className="flex-1 w-full object-cover" />
      <div className="absolute bottom-12 left-0 right-0 flex flex-col items-center z-50">
        <button 
          onClick={handleCapture}
          className="w-20 h-20 bg-white rounded-full flex items-center justify-center border-8 border-slate-400/30 shadow-2xl active:scale-95 transition-all"
        >
          <div className="w-14 h-14 border-2 border-slate-900 rounded-full bg-slate-100 flex items-center justify-center">
             <div className="w-4 h-4 bg-blue-600 rounded-sm"></div>
          </div>
        </button>
      </div>
      <button onClick={onBack} className="absolute top-6 left-6 z-50 bg-black/40 p-3 rounded-xl border border-white/10 text-white">
        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M6 18L18 6M6 6l12 12" /></svg>
      </button>

      {error && (
        <div className="absolute top-24 left-6 right-6 z-50 bg-red-950/80 border border-red-500/30 p-4 rounded-2xl backdrop-blur-md animate-in slide-in-from-top-4 duration-300">
          <div className="flex items-center space-x-3">
             <span className="text-lg">⚠️</span>
             <p className="text-[10px] text-red-200 font-black uppercase tracking-tight leading-tight">{error}</p>
          </div>
        </div>
      )}
      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default CameraInterface;

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from '@google/genai';
import { StructuralAnalysis } from '../types.ts';
import { CIVIL_ENGINEER_SYSTEM_PROMPT } from '../constants.ts';

interface Message {
  role: 'user' | 'model';
  text: string;
  timestamp: string;
}

interface EngineeringChatbotProps {
  context: StructuralAnalysis;
  onMessagesUpdate?: (messages: Message[]) => void;
}

const EngineeringChatbot: React.FC<EngineeringChatbotProps> = ({ context, onMessagesUpdate }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isRetrying, setIsRetrying] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Set initial greeting based on data source
    const initialText = context.isCorrection 
      ? `I remember this specimen from a previous analysis where you corrected parameters. I am utilizing those verified ${context.constructionMethodology?.concreteSpecs?.grade || ''} values now. How can I assist?`
      : `Expert Consultant Online. I've scanned the **${context.elementName}**. How can I help?`;

    setMessages([{ 
      role: 'model', 
      text: initialText,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    }]);
  }, [context.id]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
    if (onMessagesUpdate) {
        onMessagesUpdate(messages);
    }
  }, [messages, isTyping, onMessagesUpdate]);

  const handleSend = async (customInput?: string, retryCount = 0) => {
    const userMessage = (customInput || input).trim();
    if (!userMessage || isTyping) return;

    if (retryCount === 0) {
      const time = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      setInput('');
      setMessages(prev => [...prev, { role: 'user', text: userMessage, timestamp: time }]);
      setIsTyping(true);
    } else {
      setIsRetrying(true);
    }

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const metadataContext = {
        elementName: context.elementName,
        grade: context.constructionMethodology?.concreteSpecs?.grade || 'N/A',
        category: context.elementCategory,
        status: context.isCorrection ? 'MANUALLY_VERIFIED_BY_ENGINEER' : 'AI_ESTIMATED',
        defects: (context.defects || []).map(d => d.type).join(', '),
        originalAIAnalysis: context.originalData ? "ELEMENT_VERIFIED_BY_FIELD_ENGINEER" : "FIRST_SCAN"
      };

      const chat = ai.chats.create({
        // Switched to flash-preview to resolve quota issues and avoid specific pro-preview constraints
        model: 'gemini-3-flash-preview',
        config: {
          // Removed thinkingBudget: 0 as it's invalid for some Gemini 3 models
          systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT + `

          STRICT OPERATIONAL CONTEXT:
          ${JSON.stringify(metadataContext)}

          CHAT RESPONSE RULES (CRITICAL):
          1. SILENT RECONNECT: You are part of a continuous secure link.
          2. PAYLOAD AWARENESS: Heavy data stripped. Focus on metadata.
          3. CORRECTION AWARENESS: If status is MANUALLY_VERIFIED_BY_ENGINEER, honor the user's field override and mention you remember the correction.
          4. DIRECT ANSWERS: If user asks direct question, answer in 10 words or less.
          5. NO LECTURING: Focus only on "quality", "remediation", and "IS code lookup".`,
        }
      });

      const response = await chat.sendMessage({ message: userMessage });
      const mText = response.text || "Secure Link error.";

      setMessages(prev => [...prev, { 
        role: 'model', 
        text: mText,
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      }]);
      setIsRetrying(false);
    } catch (err) {
      console.error(`Chat Link Interrupted (Retry ${retryCount}):`, err);

      if (retryCount < 2) {
        console.log("Re-establishing Secure Link...");
        setTimeout(() => handleSend(userMessage, retryCount + 1), 1500);
      } else {
        setMessages(prev => [...prev, { 
          role: 'model', 
          text: "⚠️ SECURITY PROTOCOL: Link lost after multiple attempts. Please check site network stability.",
          timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        }]);
        setIsRetrying(false);
      }
    } finally {
      if (retryCount >= 2 || !isRetrying) {
        setIsTyping(false);
        setIsRetrying(false);
      }
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-950 font-mono relative">
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 pb-24 scrollbar-hide">
        {messages.map((m, idx) => (
          <div key={idx} className={`flex w-full ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`p-3 text-[11px] font-medium shadow-xl rounded-2xl ${m.role === 'user' ? 'bg-blue-600 text-white rounded-br-none' : 'bg-slate-900 border border-slate-800 text-slate-300 rounded-bl-none'}`}>
              {m.text}
              <div className="mt-1 text-[7px] font-black uppercase opacity-40">{m.timestamp}</div>
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex items-center space-x-2 px-2">
            <div className="flex space-x-1">
              <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce"></div>
              <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce delay-75"></div>
              <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce delay-150"></div>
            </div>
            <span className="text-blue-500 text-[9px] uppercase font-black tracking-widest">
              {isRetrying ? 'Re-establishing Link...' : 'AI Consultant Processing...'}
            </span>
          </div>
        )}
      </div>
      <div className="p-4 bg-slate-950 border-t border-slate-900">
        <div className={`bg-slate-900 border border-blue-500/30 rounded-2xl px-3 py-1 flex items-center transition-all ${isTyping ? 'opacity-40 pointer-events-none' : 'opacity-100'}`}>
          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            disabled={isTyping}
            placeholder="Query structural history..."
            className="flex-1 bg-transparent border-none outline-none text-xs py-2 px-2 text-white placeholder:text-slate-700"
          />
          <button onClick={() => handleSend()} disabled={isTyping} className="p-2 text-blue-500 disabled:text-slate-700">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 rotate-90" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
};

