          )}
          {activeTab === 'chat' && (
            <div className="bg-theme-card rounded-3xl overflow-hidden border border-theme h-[500px]">
              <EngineeringChatbot context={engineeringData} />
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

