const CORRECTION_DB_KEY = 'civilvision_correction_memory';

// Utility for exponential backoff retries
async function callWithRetry<T>(fn: () => Promise<T>, maxRetries = 2, initialDelay = 1500): Promise<T> {
  let lastError: any;
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fn();
    } catch (error: any) {
      lastError = error;
      const errorMsg = error?.message || "";
      const isQuotaError = errorMsg.includes('429') || errorMsg.includes('QUOTA_EXCEEDED') || error?.status === 'RESOURCE_EXHAUSTED';

      if (!isQuotaError || i === maxRetries - 1) {
        if (isQuotaError) {
          const quotaErr = new Error("QUOTA_EXCEEDED");
          (quotaErr as any).status = 429;
          throw quotaErr;
        }
        throw error;
      }

      const delay = initialDelay * Math.pow(2, i);
      console.warn(`Quota exceeded. Retrying in ${delay}ms...`);
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }
  throw lastError;
}

export const getImageHash = async (base64: string): Promise<string> => {
  const msgUint8 = new TextEncoder().encode(base64);
  const hashBuffer = await crypto.subtle.digest('SHA-256', msgUint8);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
};

export const saveCorrection = (hash: string, data: StructuralAnalysis) => {
  const db = JSON.parse(localStorage.getItem(CORRECTION_DB_KEY) || '{}');
  db[hash] = { data, timestamp: Date.now() };
  localStorage.setItem(CORRECTION_DB_KEY, JSON.stringify(db));
};

export const getStoredCorrection = (hash: string): StructuralAnalysis | null => {
  const db = JSON.parse(localStorage.getItem(CORRECTION_DB_KEY) || '{}');
  return db[hash]?.data || null;
};

// Client-side Image Compression
export const compressImage = async (base64Str: string, maxWidth = 1024, quality = 0.7): Promise<string> => {
  return new Promise((resolve) => {
    const img = new Image();
    img.src = `data:image/jpeg;base64,${base64Str}`;
    img.onload = () => {
      const canvas = document.createElement('canvas');
      let width = img.width;
      let height = img.height;

      if (width > maxWidth) {
        height = Math.round((height * maxWidth) / width);
        width = maxWidth;
      }

      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        resolve(base64Str);
        return;
      }
      ctx.drawImage(img, 0, 0, width, height);
      // toDataURL returns "data:image/jpeg;base64,..."
      const newDataUrl = canvas.toDataURL('image/jpeg', quality);
      resolve(newDataUrl.split(',')[1]);
    };
    img.onerror = () => resolve(base64Str);
  });
};

export const analyzeImage = async (base64Image: string, userContext?: string, onFirstChunk?: () => void): Promise<StructuralAnalysis> => {
  return callWithRetry(async () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Compress image before sending to save tokens and bandwidth
    const compressedBase64 = await compressImage(base64Image);

    // Use generateContentStream for faster Time-To-First-Byte (TTFB) perception
    const responseStream = await ai.models.generateContentStream({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: compressedBase64, mimeType: 'image/jpeg' } },
          { text: `ANALYZE BRIEF: Identify item as EXPERIMENT, STRUCTURE, or MACHINERY. 
          STRICT LIMIT: Max 100 words total. Be concise.
          Output JSON. Context: ${userContext || 'None'}` }
        ]
      },
      config: {
        systemInstruction: CIVIL_ENGINEER_SYSTEM_PROMPT,
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            elementName: { type: Type.STRING },
            elementCategory: { type: Type.STRING, description: 'EXPERIMENT, STRUCTURE, or MACHINERY' },
            confidenceScore: { type: Type.NUMBER },
            executiveSummary: {
              type: Type.OBJECT,
              properties: {
                brief: { type: Type.STRING },
                keyEngineeringPoints: { type: Type.ARRAY, items: { type: Type.STRING } }
              }
            },
            isCodeReferences: { type: Type.ARRAY, items: { type: Type.STRING } },
            defects: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  type: { type: Type.STRING },
                  severity: { type: Type.STRING },
                  cause: { type: Type.STRING },
                  remedy: { type: Type.STRING }
                }
              }
            },
            constructionMethodology: {
              type: Type.OBJECT,
              properties: {
                methodSummary: { type: Type.STRING },
                concreteSpecs: {
                  type: Type.OBJECT,
                  properties: {
                    grade: { type: Type.STRING },
                    mixDesign: {
                      type: Type.ARRAY,
                      items: {
                        type: Type.OBJECT,
                        properties: { material: { type: Type.STRING }, quantity: { type: Type.STRING }, proportion: { type: Type.STRING } }
                      }
                    }
                  }
                },
                machinerySpecs: {
                  type: Type.OBJECT,
                  properties: {
                    liftingCapacity: { type: Type.STRING },
                    boomLength: { type: Type.STRING },
                    safetyFactor: { type: Type.STRING }
                  }
                }
              }
            },
            recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["elementName", "elementCategory", "confidenceScore"]
        }
      }
    });

    let fullText = '';
    let hasCalledBack = false;

    for await (const chunk of responseStream) {
      if (!hasCalledBack && onFirstChunk) {
        onFirstChunk();
        hasCalledBack = true;
      }
      fullText += chunk.text;
    }

    try {
      // Clean potential markdown blocks if present (though responseMimeType usually handles this)
      const jsonStr = fullText.replace(/```json/g, '').replace(/```/g, '').trim();
      return JSON.parse(jsonStr);
    } catch (error) {
      console.error("Pipeline Error:", error);
      throw new Error("ENGINEERING_LINK_FAILED");
    }
  });
};

